GO
USE master;
GO

DECLARE @Lan INT = 1;
WHILE DB_ID(N'QuanLyThuongMaiDienTu') IS NOT NULL AND @Lan <= 5
BEGIN
    BEGIN TRY
        ALTER DATABASE QuanLyThuongMaiDienTu SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
        DROP DATABASE QuanLyThuongMaiDienTu;
    END TRY
    BEGIN CATCH
        SET @Lan = @Lan + 1;
        WAITFOR DELAY '00:00:02';
    END CATCH
END
IF DB_ID(N'QuanLyThuongMaiDienTu') IS NOT NULL
    THROW 50000, N'Không xóa được database QuanLyThuongMaiDienTu sau 5 lần thử: đang có kết nối khác giữ nó.', 1;
GO

CREATE DATABASE QuanLyThuongMaiDienTu;
GO
USE QuanLyThuongMaiDienTu;
GO

CREATE SEQUENCE seq_VanDon AS INT START WITH 6 INCREMENT BY 1;
GO

CREATE TABLE NhaCungCap (
    MaNCC VARCHAR(20) PRIMARY KEY,
    TenNCC NVARCHAR(255) NOT NULL,
    SoDT VARCHAR(20),
    DiaChi NVARCHAR(255),
    SoNgayCongNo INT NOT NULL DEFAULT 0 CHECK (SoNgayCongNo >= 0)
);

CREATE TABLE DanhMuc (
    MaDanhMuc VARCHAR(20) PRIMARY KEY,
    TenDanhMuc NVARCHAR(255) NOT NULL
);

CREATE TABLE SanPham (
    MaSP VARCHAR(50) PRIMARY KEY,
    MaDanhMuc VARCHAR(20) FOREIGN KEY REFERENCES DanhMuc(MaDanhMuc),
    Barcode VARCHAR(50),
    TenSP NVARCHAR(255) NOT NULL,
    GiaBan DECIMAL(18,2) DEFAULT 0 CHECK (GiaBan >= 0),
    NguongAnToan INT DEFAULT 10 CHECK (NguongAnToan >= 0),
    HinhAnh NVARCHAR(255) NULL,
    MaSKUShopee VARCHAR(50) NULL,
    TonKhoAnToan INT NULL,
    DiemDatHangLai_ROP INT NULL,
    SoNgayConLai_DuKien DECIMAL(10,1) NULL,
    DiemCamXuc_CSAT DECIMAL(5,2) NULL,
    DoCoGiang_PED DECIMAL(10,4) NULL,
    GiaVon DECIMAL(18,2) NULL,
    DangKinhDoanh BIT NOT NULL DEFAULT 1,
    SoThangBaoHanh INT NOT NULL DEFAULT 12 CHECK (SoThangBaoHanh BETWEEN 0 AND 120)
);

CREATE TABLE Kho (
    MaKho VARCHAR(20) PRIMARY KEY,
    TenKho NVARCHAR(255) NOT NULL,
    DiaChi NVARCHAR(255)
);

CREATE TABLE PhieuNhap (
    MaPN VARCHAR(20) PRIMARY KEY,
    NgayNhap DATETIME DEFAULT GETDATE(),
    NgayDatHang DATETIME NULL,
    MaNCC VARCHAR(20) FOREIGN KEY REFERENCES NhaCungCap(MaNCC),
    MaKho VARCHAR(20) FOREIGN KEY REFERENCES Kho(MaKho),
    TongTien DECIMAL(18,2) DEFAULT 0 CHECK (TongTien >= 0)
);

CREATE TABLE ChiTietPhieuNhap (
    MaPN VARCHAR(20) FOREIGN KEY REFERENCES PhieuNhap(MaPN) ON DELETE CASCADE,
    MaSP VARCHAR(50) FOREIGN KEY REFERENCES SanPham(MaSP),
    SoLuong INT CHECK (SoLuong > 0),
    DonGia DECIMAL(18,2) CHECK (DonGia >= 0),
    ThanhTien AS (SoLuong * DonGia),
    PRIMARY KEY (MaPN, MaSP)
);

CREATE TABLE KhachHang (
    MaKH VARCHAR(20) PRIMARY KEY,
    TenKH NVARCHAR(255) NOT NULL,
    SoDT VARCHAR(20),
    DiaChi NVARCHAR(255),
    Nhom_RFM NVARCHAR(30) NULL,
    XacSuatRoiBo DECIMAL(5,4) NULL CHECK (XacSuatRoiBo BETWEEN 0 AND 1),
    DanhSachDen_Blacklist BIT NOT NULL DEFAULT 0,
    SoDienThoai_ChuanHoa VARCHAR(20) NULL,
    DiaChi_ChuanHoa NVARCHAR(255) NULL,
    DiemNhayCamGia DECIMAL(6,2) NULL
);

CREATE TABLE DoiTac (
    MaDoiTac VARCHAR(20) PRIMARY KEY,
    TenDoiTac NVARCHAR(255) NOT NULL,
    MST VARCHAR(20),
    SoDT VARCHAR(20),
    DiaChi NVARCHAR(255),
    LoaiKenh NVARCHAR(30) NOT NULL DEFAULT N'Sàn thương mại điện tử'
        CHECK (LoaiKenh IN (N'Cửa hàng', N'Sàn thương mại điện tử'))
);

CREATE TABLE DonHang (
    MaDH VARCHAR(20) PRIMARY KEY,
    NgayDat DATETIME DEFAULT GETDATE(),
    MaKH VARCHAR(20) FOREIGN KEY REFERENCES KhachHang(MaKH),
    MaDoiTac VARCHAR(20) NULL FOREIGN KEY REFERENCES DoiTac(MaDoiTac),
    TrangThai NVARCHAR(50) DEFAULT N'Chờ xác nhận',
    TongTien DECIMAL(18,2) DEFAULT 0 CHECK (TongTien >= 0),
    TyLeRuiRoHuyDon DECIMAL(5,2) NULL,
    TrangThaiCanhBaoHuy NVARCHAR(50) NULL,
    CoNghiNghiepGianLan BIT NOT NULL DEFAULT 0,
    PhuongThucThanhToan NVARCHAR(50) NULL,
    HinhThucNhan NVARCHAR(30) NOT NULL DEFAULT N'Giao tận nơi'
        CHECK (HinhThucNhan IN (N'Giao tận nơi', N'Nhận tại cửa hàng')),
    TenNguoiNhan NVARCHAR(255) NULL,
    SdtNguoiNhan VARCHAR(20) NULL,
    DiaChiGiao NVARCHAR(255) NULL,
    GiamGiaCuaShop DECIMAL(18,2) NOT NULL DEFAULT 0 CHECK (GiamGiaCuaShop >= 0),
    PhiVanChuyenKhachTra DECIMAL(18,2) NOT NULL DEFAULT 0 CHECK (PhiVanChuyenKhachTra >= 0),
    NgayXacNhan DATETIME NULL,
    NgayGiao DATETIME NULL,
    NgayHuy DATETIME NULL,
    LyDoHuy NVARCHAR(255) NULL,
    Feature_DayOfWeek AS ((DATEDIFF(DAY, '19000101', NgayDat) % 7) + 1),
    Feature_IsWeekend AS (CASE WHEN DATEDIFF(DAY, '19000101', NgayDat) % 7 >= 5 THEN 1 ELSE 0 END),
    Feature_Hour AS (DATEPART(HOUR, NgayDat))
);

CREATE TABLE ChiTietDonHang (
    MaDH VARCHAR(20) FOREIGN KEY REFERENCES DonHang(MaDH) ON DELETE CASCADE,
    MaSP VARCHAR(50) FOREIGN KEY REFERENCES SanPham(MaSP),
    SoLuong INT CHECK (SoLuong > 0),
    DonGia DECIMAL(18,2) CHECK (DonGia >= 0),
    ThanhTien AS (SoLuong * DonGia),
    GiaVon DECIMAL(18,2) NULL,
    PRIMARY KEY (MaDH, MaSP)
);

CREATE TABLE PhieuXuat (
    MaPX VARCHAR(20) PRIMARY KEY,
    MaDH VARCHAR(20) FOREIGN KEY REFERENCES DonHang(MaDH),
    MaKho VARCHAR(20) FOREIGN KEY REFERENCES Kho(MaKho),
    NgayXuat DATETIME DEFAULT GETDATE(),
    NguoiLap NVARCHAR(100)
);

CREATE TABLE ChiTietPhieuXuat (
    MaPX VARCHAR(20) FOREIGN KEY REFERENCES PhieuXuat(MaPX) ON DELETE CASCADE,
    MaSP VARCHAR(50) FOREIGN KEY REFERENCES SanPham(MaSP),
    SoLuong INT CHECK (SoLuong > 0),
    PRIMARY KEY (MaPX, MaSP)
);

CREATE TABLE ViTriKho (
    MaViTri VARCHAR(20) PRIMARY KEY,
    MaKho VARCHAR(20) FOREIGN KEY REFERENCES Kho(MaKho),
    KeSo NVARCHAR(50),
    OChua NVARCHAR(50),
    TrangThai NVARCHAR(50) DEFAULT N'Trống'
);

CREATE TABLE TonKho (
    MaKho VARCHAR(20) FOREIGN KEY REFERENCES Kho(MaKho),
    MaSP VARCHAR(50) FOREIGN KEY REFERENCES SanPham(MaSP),
    SoLuongTon INT DEFAULT 0 CHECK (SoLuongTon >= 0),
    PRIMARY KEY (MaKho, MaSP)
);

CREATE TABLE CanhBaoTonHet (
    MaCanhBao VARCHAR(20) PRIMARY KEY,
    MaKho VARCHAR(20) FOREIGN KEY REFERENCES Kho(MaKho),
    MaSP VARCHAR(50) FOREIGN KEY REFERENCES SanPham(MaSP),
    NgayCanhBao DATETIME DEFAULT GETDATE(),
    TrangThai NVARCHAR(50) DEFAULT N'Chưa xử lý'
);

CREATE TABLE HoaDon (
    MaHD VARCHAR(20) PRIMARY KEY,
    MaDH VARCHAR(20) FOREIGN KEY REFERENCES DonHang(MaDH),
    NgayLap DATETIME DEFAULT GETDATE(),
    TongTien DECIMAL(18,2) DEFAULT 0 CHECK (TongTien >= 0),
    LoaiHoaDon NVARCHAR(30) NOT NULL DEFAULT N'Hóa đơn bán hàng'
        CHECK (LoaiHoaDon IN (N'Hóa đơn bán hàng', N'Điều chỉnh giảm')),
    MaHDGoc VARCHAR(20) NULL FOREIGN KEY REFERENCES HoaDon(MaHD),
    GiamGia DECIMAL(18,2) NOT NULL DEFAULT 0 CHECK (GiamGia >= 0),
    ThueSuat DECIMAL(5,2) NOT NULL DEFAULT 0,
    TienChuaThue DECIMAL(18,2) NOT NULL DEFAULT 0,
    TienThue DECIMAL(18,2) NOT NULL DEFAULT 0,
    TenNguoiMua NVARCHAR(255) NULL,
    DiaChiNguoiMua NVARCHAR(255) NULL,
    MaSoThueNguoiMua VARCHAR(20) NULL,
    CONSTRAINT CK_HoaDon_Goc CHECK ((LoaiHoaDon = N'Hóa đơn bán hàng' AND MaHDGoc IS NULL)
                                    OR (LoaiHoaDon = N'Điều chỉnh giảm' AND MaHDGoc IS NOT NULL)),
    CONSTRAINT CK_HoaDon_Thue CHECK (TienChuaThue + TienThue = TongTien)
);

CREATE TABLE ChiTietHoaDon (
    MaHD VARCHAR(20) FOREIGN KEY REFERENCES HoaDon(MaHD) ON DELETE CASCADE,
    MaSP VARCHAR(50) FOREIGN KEY REFERENCES SanPham(MaSP),
    SoLuong INT CHECK (SoLuong > 0),
    DonGia DECIMAL(18,2) CHECK (DonGia >= 0),
    ThanhTien DECIMAL(18,2) NULL,
    PRIMARY KEY (MaHD, MaSP)
);

CREATE TABLE ThongTinCuaHang (
    Id INT PRIMARY KEY CHECK (Id = 1),
    TenCuaHang NVARCHAR(255) NOT NULL,
    MaSoThue VARCHAR(20) NOT NULL,
    DiaChi NVARCHAR(255) NOT NULL,
    SoDT VARCHAR(20) NULL
);

CREATE TABLE ThueSuatGTGT (
    Id INT IDENTITY(1,1) PRIMARY KEY,
    TuNgay DATE NOT NULL,
    DenNgay DATE NULL,
    ThueSuat DECIMAL(5,2) NOT NULL CHECK (ThueSuat >= 0),
    NguonThongTin NVARCHAR(500) NULL,
    CONSTRAINT CK_ThueSuat_Ngay CHECK (DenNgay IS NULL OR DenNgay >= TuNgay)
);

CREATE TABLE QuanLyHDDT (
    MaHDDT VARCHAR(50) PRIMARY KEY,
    MaHD VARCHAR(20) FOREIGN KEY REFERENCES HoaDon(MaHD),
    MaXacThuc VARCHAR(255),
    ChuKySo NVARCHAR(2000),
    NgayPhatHanh DATETIME DEFAULT GETDATE()
);

CREATE TABLE VanDon (
    MaVanDon VARCHAR(50) NOT NULL
        CONSTRAINT DF_VanDon_MaVanDon DEFAULT ('VD' + RIGHT('000000' + CAST(NEXT VALUE FOR seq_VanDon AS VARCHAR(10)), 6)),
    MaDH VARCHAR(20) FOREIGN KEY REFERENCES DonHang(MaDH),
    DonViVC NVARCHAR(100),
    MaTracking VARCHAR(100),
    TrangThai NVARCHAR(50) NULL DEFAULT N'Đang giao',
    NgayTao DATETIME NULL DEFAULT GETDATE(),
    NgayGiaoXong DATETIME NULL,
    AnhChupVanDon NVARCHAR(255) NULL,
    MaVanDonShopee VARCHAR(100) NULL,
    SoNgayGiaoDuKien_AI DECIMAL(5,1) NULL,
    DiemUyTin_NVDV DECIMAL(5,2) NULL,
    CONSTRAINT PK_VanDon PRIMARY KEY (MaVanDon)
);

CREATE TABLE DongBoShopee (
    MaDongBo VARCHAR(20) PRIMARY KEY,
    MaDH VARCHAR(20) NOT NULL FOREIGN KEY REFERENCES DonHang(MaDH),
    MaDonShopee VARCHAR(50) NULL,
    TrangThaiDongBo NVARCHAR(50) NOT NULL DEFAULT N'Chưa đồng bộ',
    ThoiGianTao DATETIME DEFAULT GETDATE(),
    ThoiGianDongBo DATETIME NULL,
    GhiChu NVARCHAR(255) NULL
);

CREATE TABLE BaoHanh (
    MaBaoHanh VARCHAR(20) PRIMARY KEY,
    MaSP VARCHAR(50) FOREIGN KEY REFERENCES SanPham(MaSP),
    MaDH VARCHAR(20) FOREIGN KEY REFERENCES DonHang(MaDH),
    LyDoHong NVARCHAR(255),
    NgayNhan DATETIME DEFAULT GETDATE(),
    NgayHenTra DATETIME,
    TrangThai NVARCHAR(40) NOT NULL DEFAULT N'Đang xử lý'
        CHECK (TrangThai IN (N'Đang xử lý', N'Đã sửa xong, trả khách', N'Hãng đổi máy mới, trả khách', N'Từ chối bảo hành', N'Chuyển sang trả hàng')),
    CachXuLy NVARCHAR(255) NULL,
    NgayTraKhach DATETIME NULL,
    ChiPhiShopChiu DECIMAL(18,2) NOT NULL DEFAULT 0 CHECK (ChiPhiShopChiu >= 0),
    CONSTRAINT CK_BaoHanh_TraKhach CHECK ((TrangThai = N'Đang xử lý' AND NgayTraKhach IS NULL)
                                          OR (TrangThai <> N'Đang xử lý' AND NgayTraKhach IS NOT NULL))
);

CREATE TABLE TraHang (
    MaTraHang VARCHAR(20) PRIMARY KEY,
    MaDH VARCHAR(20) FOREIGN KEY REFERENCES DonHang(MaDH),
    MaKho VARCHAR(20) FOREIGN KEY REFERENCES Kho(MaKho),
    MaSP VARCHAR(50) FOREIGN KEY REFERENCES SanPham(MaSP),
    SoLuong INT CHECK (SoLuong > 0),
    LyDoTra NVARCHAR(255),
    SoTienHoan DECIMAL(18,2) DEFAULT 0 CHECK (SoTienHoan >= 0),
    NgayTra DATETIME DEFAULT GETDATE(),
    CamXucKhachHang NVARCHAR(30) NULL,
    NhomLyDoChinh NVARCHAR(100) NULL,
    CoGianLanDoiTra BIT NOT NULL DEFAULT 0,
    NoiDung_DaLamSach NVARCHAR(1000) NULL,
    TinhTrangHang NVARCHAR(30) NOT NULL DEFAULT N'Còn bán được'
        CHECK (TinhTrangHang IN (N'Còn bán được', N'Hỏng, không bán lại'))
);

CREATE TABLE NguoiDung (
    MaND VARCHAR(20) PRIMARY KEY,
    TenTK VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CS_AS UNIQUE NOT NULL,
    MatKhau VARBINARY(32) NOT NULL,
    Salt VARCHAR(36) NOT NULL,
    HoTen NVARCHAR(100),
    SoDT VARCHAR(20),
    TrangThai NVARCHAR(20) NOT NULL DEFAULT N'Đang dùng' CHECK (TrangThai IN (N'Đang dùng', N'Đã khóa')),
    SoLanSaiMatKhau INT NOT NULL DEFAULT 0,
    KhoaDen DATETIME NULL
);

CREATE TABLE PhanQuyen (
    MaQuyen VARCHAR(50) PRIMARY KEY,
    MaND VARCHAR(20) FOREIGN KEY REFERENCES NguoiDung(MaND),
    TenQuyen NVARCHAR(100),
    QuyenKho BIT DEFAULT 0,
    QuyenBanHang BIT DEFAULT 0,
    QuyenBaoCao BIT DEFAULT 0
);

CREATE TABLE NhatKyHeThong (
    MaLog INT IDENTITY(1,1) PRIMARY KEY,
    MaND VARCHAR(20) NULL,
    ThaoTac NVARCHAR(255),
    ThoiGian DATETIME DEFAULT GETDATE()
);

CREATE TABLE LichSuGiaoDich (
    MaLichSu INT IDENTITY(1,1) PRIMARY KEY,
    LoaiGiaoDich NVARCHAR(50) NOT NULL,
    MaThamChieu VARCHAR(50) NOT NULL,
    MaSP VARCHAR(50) NULL FOREIGN KEY REFERENCES SanPham(MaSP),
    MaKho VARCHAR(20) NULL FOREIGN KEY REFERENCES Kho(MaKho),
    SoLuong INT NULL,
    SoTien DECIMAL(18,2) NULL,
    MoTa NVARCHAR(500),
    MaND VARCHAR(20) NULL FOREIGN KEY REFERENCES NguoiDung(MaND),
    ThoiGianGD DATETIME DEFAULT GETDATE()
);

CREATE TABLE LichSuTruyVan_AI (
    Id INT IDENTITY(1,1) PRIMARY KEY,
    CauHoiText NVARCHAR(MAX) NOT NULL,
    CauLenhSQL NVARCHAR(MAX) NULL,
    ThoiGian DATETIME NOT NULL DEFAULT GETDATE(),
    NguoiDungId VARCHAR(20) NULL FOREIGN KEY REFERENCES NguoiDung(MaND)
);

CREATE TABLE PhanTich_CamXuc_DanhGia (
    Id INT IDENTITY(1,1) PRIMARY KEY,
    DoiTuongId VARCHAR(50) NOT NULL,
    LoaiDoiTuong NVARCHAR(50) NOT NULL,
    DiemCamXuc DECIMAL(6,4) NULL,
    NhomCamXuc NVARCHAR(30) NULL CHECK (NhomCamXuc IN (N'Khen', N'Trung tính', N'Chê')),
    NoiDungGoc NVARCHAR(MAX) NULL,
    GanTay BIT NOT NULL DEFAULT 0
);

CREATE TABLE ChuDe_KhieuNai (
    Id INT IDENTITY(1,1) PRIMARY KEY,
    TenChuDe NVARCHAR(200) NOT NULL UNIQUE,
    TanSuatXuatHien INT NOT NULL DEFAULT 0,
    MucDoUuTien INT NULL,
    NgayCapNhat DATETIME NOT NULL DEFAULT GETDATE()
);

CREATE TABLE Log_BatThuongKho (
    Id INT IDENTITY(1,1) PRIMARY KEY,
    SanPhamId VARCHAR(50) NOT NULL FOREIGN KEY REFERENCES SanPham(MaSP),
    SoLuongLech INT NOT NULL,
    ChiSo_ZScore DECIMAL(10,4) NULL,
    MucDoCaiBao NVARCHAR(30) NULL,
    ThoiGian DATETIME NOT NULL DEFAULT GETDATE()
);

CREATE TABLE DeXuat_ComboKhuyenMai (
    Id INT IDENTITY(1,1) PRIMARY KEY,
    SanPhamChinhId VARCHAR(50) NOT NULL FOREIGN KEY REFERENCES SanPham(MaSP),
    SanPhamKemId VARCHAR(50) NOT NULL FOREIGN KEY REFERENCES SanPham(MaSP),
    ChiSo_Support DECIMAL(9,6) NULL,
    ChiSo_Confidence DECIMAL(9,6) NULL,
    ChiSo_Lift DECIMAL(12,4) NULL,
    CONSTRAINT UQ_DeXuat_Combo UNIQUE (SanPhamChinhId, SanPhamKemId),
    CONSTRAINT CK_DeXuat_HaiSPKhacNhau CHECK (SanPhamChinhId <> SanPhamKemId)
);

CREATE TABLE BatThuong_DonHang_GianLan (
    Id INT IDENTITY(1,1) PRIMARY KEY,
    DonHangId VARCHAR(20) NOT NULL FOREIGN KEY REFERENCES DonHang(MaDH),
    KhachHangId VARCHAR(20) NULL FOREIGN KEY REFERENCES KhachHang(MaKH),
    DiemRuiRo DECIMAL(5,2) NULL,
    LyDoCanhBao NVARCHAR(500) NULL,
    TrangThaiXuly NVARCHAR(50) NOT NULL DEFAULT N'Chưa xử lý'
);

CREATE TABLE Log_TienXuLyDuLieu (
    Id INT IDENTITY(1,1) PRIMARY KEY,
    TenTienTrinh NVARCHAR(200) NOT NULL,
    SoBanGhiDaSua INT NOT NULL DEFAULT 0,
    SoBanGhiLoi INT NOT NULL DEFAULT 0,
    ThoiGianChay DATETIME NOT NULL DEFAULT GETDATE()
);

CREATE TABLE TuDien_Teencode (
    Id INT IDENTITY(1,1) PRIMARY KEY,
    TuGoc NVARCHAR(100) NOT NULL UNIQUE,
    TuChuanHoa NVARCHAR(100) NOT NULL,
    LoaiTu NVARCHAR(50) NULL
);

CREATE TABLE PhiSan (
    Id INT IDENTITY(1,1) PRIMARY KEY,
    MaDoiTac VARCHAR(20) NOT NULL FOREIGN KEY REFERENCES DoiTac(MaDoiTac),
    MaDanhMuc VARCHAR(20) NULL FOREIGN KEY REFERENCES DanhMuc(MaDanhMuc),
    LoaiPhi NVARCHAR(50) NOT NULL,
    CachTinh NVARCHAR(30) NOT NULL
        CHECK (CachTinh IN (N'Phần trăm tiền hàng', N'Phần trăm tiền khách trả', N'Số tiền mỗi đơn')),
    GiaTri DECIMAL(18,4) NOT NULL CHECK (GiaTri >= 0),
    TuNgay DATE NOT NULL,
    DenNgay DATE NULL,
    NguonThongTin NVARCHAR(500) NULL,
    CONSTRAINT CK_PhiSan_Ngay CHECK (DenNgay IS NULL OR DenNgay >= TuNgay),
    CONSTRAINT CK_PhiSan_DanhMuc CHECK (MaDanhMuc IS NULL OR CachTinh = N'Phần trăm tiền hàng')
);

CREATE TABLE HangHoanVeKho (
    Id INT IDENTITY(1,1) PRIMARY KEY,
    MaDH VARCHAR(20) NOT NULL FOREIGN KEY REFERENCES DonHang(MaDH),
    MaPX VARCHAR(20) NOT NULL FOREIGN KEY REFERENCES PhieuXuat(MaPX),
    MaKho VARCHAR(20) NOT NULL FOREIGN KEY REFERENCES Kho(MaKho),
    MaSP VARCHAR(50) NOT NULL FOREIGN KEY REFERENCES SanPham(MaSP),
    SoLuong INT NOT NULL CHECK (SoLuong > 0),
    LyDo NVARCHAR(255) NULL,
    NgayHoan DATETIME NOT NULL DEFAULT GETDATE(),
    TrangThai NVARCHAR(30) NOT NULL DEFAULT N'Đang hoàn về'
        CHECK (TrangThai IN (N'Đang hoàn về', N'Đã nhận về kho')),
    NgayNhanVe DATETIME NULL,
    CONSTRAINT CK_HangHoanVeKho_NgayNhanVe CHECK ((TrangThai = N'Đang hoàn về' AND NgayNhanVe IS NULL)
                                                 OR (TrangThai = N'Đã nhận về kho' AND NgayNhanVe IS NOT NULL))
);

GO

CREATE NONCLUSTERED INDEX IX_PhieuNhap_NgayNhap ON PhieuNhap(NgayNhap) INCLUDE (TongTien, MaKho);
CREATE NONCLUSTERED INDEX IX_PhieuXuat_NgayXuat ON PhieuXuat(NgayXuat) INCLUDE (MaKho, MaDH);
CREATE NONCLUSTERED INDEX IX_DonHang_NgayDat ON DonHang(NgayDat) INCLUDE (TongTien, TrangThai);
CREATE TABLE LichSuGiaBan (
    Id INT IDENTITY(1,1) PRIMARY KEY,
    MaSP VARCHAR(50) NOT NULL FOREIGN KEY REFERENCES SanPham(MaSP),
    GiaBanCu DECIMAL(18,2) NULL,
    GiaBanMoi DECIMAL(18,2) NULL,
    GiaVonLucDoi DECIMAL(18,2) NULL,
    NgayDoi DATETIME NOT NULL DEFAULT GETDATE(),
    MaND VARCHAR(20) NULL FOREIGN KEY REFERENCES NguoiDung(MaND)
);

CREATE TABLE ChiPhiVanHanh (
    MaCP INT IDENTITY(1,1) PRIMARY KEY,
    Thang DATE NOT NULL CHECK (DAY(Thang) = 1),
    NhomChiPhi NVARCHAR(50) NOT NULL
        CHECK (NhomChiPhi IN (N'Mặt bằng', N'Kho bãi', N'Nhân viên', N'Điện nước, internet', N'Đóng gói', N'Quảng cáo', N'Vận chuyển', N'Khác')),
    TenChiPhi NVARCHAR(150) NOT NULL,
    SoTien DECIMAL(18,2) NOT NULL CHECK (SoTien >= 0),
    CachTinh NVARCHAR(500) NULL,
    CONSTRAINT UQ_ChiPhiVanHanh UNIQUE (Thang, TenChiPhi)
);

CREATE TABLE ThanhToanNCC (
    MaTT VARCHAR(20) PRIMARY KEY,
    MaPN VARCHAR(20) NOT NULL FOREIGN KEY REFERENCES PhieuNhap(MaPN),
    NgayTra DATETIME NOT NULL DEFAULT GETDATE(),
    SoTien DECIMAL(18,2) NOT NULL CHECK (SoTien > 0),
    HinhThuc NVARCHAR(50) NOT NULL CHECK (HinhThuc IN (N'Tiền mặt', N'Chuyển khoản ngân hàng')),
    NguoiLap NVARCHAR(100) NULL
);

CREATE TABLE TienSanChuyenVe (
    MaDH VARCHAR(20) PRIMARY KEY FOREIGN KEY REFERENCES DonHang(MaDH),
    MaDot VARCHAR(30) NOT NULL,
    NgayChuyen DATETIME NOT NULL,
    SoTienSanTra DECIMAL(18,2) NOT NULL,
    GhiChu NVARCHAR(255) NULL
);

CREATE TABLE PhieuKiemKe (
    MaKK VARCHAR(20) PRIMARY KEY,
    MaKho VARCHAR(20) NOT NULL FOREIGN KEY REFERENCES Kho(MaKho),
    NgayKiemKe DATETIME NOT NULL DEFAULT GETDATE(),
    NguoiKiem NVARCHAR(100) NULL,
    TrangThai NVARCHAR(20) NOT NULL DEFAULT N'Đang kiểm' CHECK (TrangThai IN (N'Đang kiểm', N'Đã chốt')),
    NgayChot DATETIME NULL
);

CREATE TABLE ChiTietKiemKe (
    MaKK VARCHAR(20) NOT NULL FOREIGN KEY REFERENCES PhieuKiemKe(MaKK) ON DELETE CASCADE,
    MaSP VARCHAR(50) NOT NULL FOREIGN KEY REFERENCES SanPham(MaSP),
    SoSach INT NOT NULL,
    ThucTe INT NULL CHECK (ThucTe >= 0),
    ChenhLech AS (ThucTe - SoSach),
    LyDoLech NVARCHAR(255) NULL,
    PRIMARY KEY (MaKK, MaSP)
);

CREATE TABLE PhieuChuyenKho (
    MaCK VARCHAR(20) PRIMARY KEY,
    TuKho VARCHAR(20) NOT NULL FOREIGN KEY REFERENCES Kho(MaKho),
    DenKho VARCHAR(20) NOT NULL FOREIGN KEY REFERENCES Kho(MaKho),
    MaSP VARCHAR(50) NOT NULL FOREIGN KEY REFERENCES SanPham(MaSP),
    SoLuong INT NOT NULL CHECK (SoLuong > 0),
    NgayChuyen DATETIME NOT NULL DEFAULT GETDATE(),
    NguoiLap NVARCHAR(100) NULL,
    CONSTRAINT CK_PhieuChuyenKho_Kho CHECK (TuKho <> DenKho)
);

CREATE NONCLUSTERED INDEX IX_HoaDon_NgayLap ON HoaDon(NgayLap) INCLUDE (TongTien);
