CREATE TYPE dbo.DanhSachHangMua AS TABLE (
    MaSP VARCHAR(50) NOT NULL PRIMARY KEY,
    SoLuong INT NOT NULL CHECK (SoLuong > 0)
);
GO

CREATE OR ALTER FUNCTION dbo.fn_LaQuanLy (@MaND VARCHAR(20))
RETURNS BIT
AS
BEGIN
    RETURN CASE WHEN EXISTS (SELECT 1 FROM PhanQuyen pq JOIN NguoiDung nd ON nd.MaND = pq.MaND
                             WHERE pq.MaND = @MaND AND nd.TrangThai = N'Đang dùng'
                               AND pq.QuyenKho = 1 AND pq.QuyenBanHang = 1 AND pq.QuyenBaoCao = 1)
                THEN 1 ELSE 0 END;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_GhiLanSaiMatKhau;
GO
CREATE PROCEDURE dbo.sp_GhiLanSaiMatKhau
    @MaND VARCHAR(20),
    @ViecDangLam NVARCHAR(50) = N'Đăng nhập'
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @SoLan INT;
    UPDATE NguoiDung
    SET @SoLan = SoLanSaiMatKhau = CASE WHEN KhoaDen IS NOT NULL THEN 1 ELSE SoLanSaiMatKhau + 1 END,
        KhoaDen = NULL
    WHERE MaND = @MaND;

    IF @SoLan >= 5
    BEGIN
        UPDATE NguoiDung SET KhoaDen = DATEADD(MINUTE, 15, GETDATE()) WHERE MaND = @MaND;
        THROW 50082, N'Nhập sai mật khẩu 5 lần liền nên tài khoản bị tạm khóa 15 phút. Hãy thử lại sau, hoặc nhờ quản lý mở khóa.', 1;
    END

    DECLARE @ThongBao NVARCHAR(300) = N'Sai tên đăng nhập hoặc mật khẩu. Còn ' + CAST(5 - @SoLan AS NVARCHAR(5))
                                      + N' lần thử, sai tiếp thì tài khoản bị tạm khóa 15 phút.';
    THROW 50080, @ThongBao, 1;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_DangNhap;
GO
CREATE PROCEDURE dbo.sp_DangNhap
    @TenTK VARCHAR(50),
    @MatKhau VARCHAR(255)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @MaND VARCHAR(20), @Salt VARCHAR(36), @MatKhauLuu VARBINARY(32), @TrangThai NVARCHAR(20), @KhoaDen DATETIME;
    SELECT @MaND = MaND, @Salt = Salt, @MatKhauLuu = MatKhau, @TrangThai = TrangThai, @KhoaDen = KhoaDen
    FROM NguoiDung
    WHERE TenTK COLLATE SQL_Latin1_General_CP1_CS_AS = @TenTK;

    IF @MaND IS NULL
        THROW 50080, N'Sai tên đăng nhập hoặc mật khẩu.', 1;
    IF @TrangThai = N'Đã khóa'
        THROW 50081, N'Tài khoản này đã bị quản lý khóa (ví dụ nhân viên đã nghỉ việc). Hãy liên hệ quản lý cửa hàng.', 1;
    IF @KhoaDen > GETDATE()
    BEGIN
        DECLARE @ThongBaoKhoa NVARCHAR(400) = N'Tài khoản đang tạm khóa vì nhập sai mật khẩu 5 lần liền. Mở lại lúc '
            + CONVERT(NVARCHAR(5), @KhoaDen, 108) + N' ngày ' + CONVERT(NVARCHAR(10), @KhoaDen, 103) + N', hoặc nhờ quản lý mở khóa.';
        THROW 50082, @ThongBaoKhoa, 1;
    END

    IF HASHBYTES('SHA2_256', CONVERT(VARCHAR(255), LTRIM(RTRIM(@MatKhau))) + @Salt) <> @MatKhauLuu
    BEGIN
        EXEC dbo.sp_GhiLanSaiMatKhau @MaND = @MaND, @ViecDangLam = N'Đăng nhập';
        RETURN;
    END

    UPDATE NguoiDung SET SoLanSaiMatKhau = 0, KhoaDen = NULL WHERE MaND = @MaND;

    SELECT
        nd.MaND,
        nd.HoTen,
        nd.SoDT,
        ISNULL(pq.TenQuyen, N'Chưa phân quyền') AS TenQuyen,
        ISNULL(pq.QuyenKho, 0) AS QuyenKho,
        ISNULL(pq.QuyenBanHang, 0) AS QuyenBanHang,
        ISNULL(pq.QuyenBaoCao, 0) AS QuyenBaoCao
    FROM NguoiDung nd
    LEFT JOIN PhanQuyen pq ON nd.MaND = pq.MaND
    WHERE nd.MaND = @MaND;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_DangKyTaiKhoan;
GO
CREATE PROCEDURE dbo.sp_DangKyTaiKhoan
    @MaNDQuanLy VARCHAR(20),
    @TenTK VARCHAR(50),
    @MatKhau VARCHAR(255),
    @HoTen NVARCHAR(100),
    @SoDT VARCHAR(20),
    @MaND VARCHAR(20) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF dbo.fn_LaQuanLy(@MaNDQuanLy) = 0
        THROW 50083, N'Chỉ quản lý cửa hàng mới tạo được tài khoản cho nhân viên.', 1;
    SET @TenTK = LTRIM(RTRIM(ISNULL(@TenTK, '')));
    IF LEN(@TenTK) < 3
        THROW 50084, N'Tên đăng nhập cần ít nhất 3 ký tự.', 1;
    IF LEN(LTRIM(RTRIM(ISNULL(@MatKhau, '')))) < 6
        THROW 50085, N'Mật khẩu phải có từ 6 ký tự trở lên.', 1;
    IF LEN(LTRIM(RTRIM(ISNULL(@HoTen, N'')))) = 0
        THROW 50086, N'Chưa nhập họ tên nhân viên.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;
        IF EXISTS (SELECT 1 FROM NguoiDung WITH (UPDLOCK, HOLDLOCK) WHERE TenTK COLLATE SQL_Latin1_General_CP1_CS_AS = @TenTK)
            THROW 50087, N'Tên đăng nhập này đã có người dùng. Hãy chọn tên khác.', 1;

        DECLARE @So INT = (SELECT ISNULL(MAX(TRY_CAST(SUBSTRING(MaND, 3, 20) AS INT)), 0) + 1
                           FROM NguoiDung WITH (UPDLOCK, HOLDLOCK) WHERE MaND LIKE 'NV%');
        SET @MaND = 'NV' + CASE WHEN @So < 1000 THEN RIGHT('00' + CAST(@So AS VARCHAR(10)), 3) ELSE CAST(@So AS VARCHAR(10)) END;

        DECLARE @Salt VARCHAR(36) = NEWID();
        VALUES (@MaND, @TenTK, HASHBYTES('SHA2_256', CONVERT(VARCHAR(255), LTRIM(RTRIM(@MatKhau))) + @Salt), @Salt,
                LTRIM(RTRIM(@HoTen)), @SoDT);

        VALUES ('Q_' + @MaND, @MaND, N'Nhân viên mới', 0, 1, 0);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_DoiMatKhau;
GO
CREATE PROCEDURE dbo.sp_DoiMatKhau
    @TenTK VARCHAR(50),
    @MatKhauCu VARCHAR(255),
    @MatKhauMoi VARCHAR(255)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @MaND VARCHAR(20), @Salt VARCHAR(36), @MatKhauLuu VARBINARY(32), @TrangThai NVARCHAR(20), @KhoaDen DATETIME;
    SELECT @MaND = MaND, @Salt = Salt, @MatKhauLuu = MatKhau, @TrangThai = TrangThai, @KhoaDen = KhoaDen
    FROM NguoiDung
    WHERE TenTK COLLATE SQL_Latin1_General_CP1_CS_AS = @TenTK;

    IF @MaND IS NULL
        THROW 50080, N'Sai tên đăng nhập hoặc mật khẩu.', 1;
    IF @TrangThai = N'Đã khóa'
        THROW 50081, N'Tài khoản này đã bị quản lý khóa. Hãy liên hệ quản lý cửa hàng.', 1;
    IF @KhoaDen > GETDATE()
        THROW 50082, N'Tài khoản đang tạm khóa vì nhập sai mật khẩu nhiều lần. Hãy đợi 15 phút hoặc nhờ quản lý mở khóa.', 1;

    IF HASHBYTES('SHA2_256', CONVERT(VARCHAR(255), LTRIM(RTRIM(@MatKhauCu))) + @Salt) <> @MatKhauLuu
    BEGIN
        EXEC dbo.sp_GhiLanSaiMatKhau @MaND = @MaND, @ViecDangLam = N'Đổi mật khẩu';
        RETURN;
    END

    IF LEN(LTRIM(RTRIM(ISNULL(@MatKhauMoi, '')))) < 6
        THROW 50085, N'Mật khẩu mới phải có từ 6 ký tự trở lên.', 1;
    IF CONVERT(VARBINARY(255), LTRIM(RTRIM(@MatKhauMoi))) = CONVERT(VARBINARY(255), LTRIM(RTRIM(@MatKhauCu)))
        THROW 50088, N'Mật khẩu mới phải khác mật khẩu đang dùng.', 1;

    DECLARE @SaltMoi VARCHAR(36) = NEWID();
    UPDATE NguoiDung
    SET MatKhau = HASHBYTES('SHA2_256', CONVERT(VARCHAR(255), LTRIM(RTRIM(@MatKhauMoi))) + @SaltMoi),
        Salt = @SaltMoi, SoLanSaiMatKhau = 0, KhoaDen = NULL
    WHERE MaND = @MaND;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_DatLaiMatKhau;
GO
CREATE PROCEDURE dbo.sp_DatLaiMatKhau
    @MaNDQuanLy VARCHAR(20),
    @MaND VARCHAR(20),
    @MatKhauMoi VARCHAR(255)
AS
BEGIN
    SET NOCOUNT ON;
    IF dbo.fn_LaQuanLy(@MaNDQuanLy) = 0
        THROW 50083, N'Chỉ quản lý cửa hàng mới đặt lại được mật khẩu cho nhân viên.', 1;
    IF NOT EXISTS (SELECT 1 FROM NguoiDung WHERE MaND = @MaND)
        THROW 50089, N'Không tìm thấy tài khoản này.', 1;
    IF LEN(LTRIM(RTRIM(ISNULL(@MatKhauMoi, '')))) < 6
        THROW 50085, N'Mật khẩu mới phải có từ 6 ký tự trở lên.', 1;

    DECLARE @Salt VARCHAR(36) = NEWID();
    UPDATE NguoiDung
    SET MatKhau = HASHBYTES('SHA2_256', CONVERT(VARCHAR(255), LTRIM(RTRIM(@MatKhauMoi))) + @Salt),
        Salt = @Salt, SoLanSaiMatKhau = 0, KhoaDen = NULL
    WHERE MaND = @MaND;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_KhoaMoTaiKhoan;
GO
CREATE PROCEDURE dbo.sp_KhoaMoTaiKhoan
    @MaNDQuanLy VARCHAR(20),
    @MaND VARCHAR(20),
    @Khoa BIT
AS
BEGIN
    SET NOCOUNT ON;
    IF dbo.fn_LaQuanLy(@MaNDQuanLy) = 0
        THROW 50083, N'Chỉ quản lý cửa hàng mới khóa hoặc mở được tài khoản.', 1;
    IF NOT EXISTS (SELECT 1 FROM NguoiDung WHERE MaND = @MaND)
        THROW 50089, N'Không tìm thấy tài khoản này.', 1;
    IF @Khoa = 1 AND @MaND = @MaNDQuanLy
        THROW 50091, N'Không tự khóa tài khoản đang đăng nhập.', 1;

    UPDATE NguoiDung
    SET TrangThai = CASE WHEN @Khoa = 1 THEN N'Đã khóa' ELSE N'Đang dùng' END,
        SoLanSaiMatKhau = 0, KhoaDen = NULL
    WHERE MaND = @MaND;
    VALUES (@MaNDQuanLy, CASE WHEN @Khoa = 1 THEN N'Khóa tài khoản ' ELSE N'Mở khóa tài khoản ' END + @MaND);
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_CapNhatPhanQuyen;
GO
CREATE PROCEDURE dbo.sp_CapNhatPhanQuyen
    @MaNDQuanLy VARCHAR(20),
    @MaND VARCHAR(20),
    @QuyenKho BIT,
    @QuyenBanHang BIT,
    @QuyenBaoCao BIT,
    @TenQuyen NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF dbo.fn_LaQuanLy(@MaNDQuanLy) = 0
        THROW 50083, N'Chỉ quản lý cửa hàng mới phân quyền được cho nhân viên.', 1;
    BEGIN TRANSACTION;
    BEGIN TRY
        IF NOT EXISTS (SELECT 1 FROM NguoiDung WITH (UPDLOCK) WHERE MaND = @MaND)
        BEGIN
            RAISERROR(N'Mã người dùng không tồn tại trên hệ thống!', 16, 1);
        END

        IF EXISTS (SELECT 1 FROM PhanQuyen WITH (UPDLOCK, HOLDLOCK) WHERE MaND = @MaND)
        BEGIN
            UPDATE PhanQuyen
            SET QuyenKho = @QuyenKho,
                QuyenBanHang = @QuyenBanHang,
                QuyenBaoCao = @QuyenBaoCao,
                TenQuyen = ISNULL(@TenQuyen, TenQuyen)
            WHERE MaND = @MaND;
        END
        ELSE
        BEGIN
            VALUES ('Q_' + @MaND, @MaND, ISNULL(@TenQuyen, N'Nhân viên'), @QuyenKho, @QuyenBanHang, @QuyenBaoCao);
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_PhatHanhHoaDon;
GO
CREATE PROCEDURE dbo.sp_PhatHanhHoaDon
    @MaDH VARCHAR(20),
    @MaSoThueNguoiMua VARCHAR(20) = NULL,
    @MaHD VARCHAR(20) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @TrangThai NVARCHAR(50), @GiamGia DECIMAL(18,2), @Ten NVARCHAR(255), @DiaChi NVARCHAR(255), @Loi NVARCHAR(400);
        SELECT @TrangThai = dh.TrangThai, @GiamGia = dh.GiamGiaCuaShop,
               @Ten = ISNULL(dh.TenNguoiNhan, kh.TenKH), @DiaChi = ISNULL(dh.DiaChiGiao, kh.DiaChi)
        FROM DonHang dh WITH (UPDLOCK)
        LEFT JOIN KhachHang kh ON kh.MaKH = dh.MaKH
        WHERE dh.MaDH = @MaDH;

        IF @TrangThai IS NULL
            THROW 50001, N'Không tìm thấy đơn hàng để lập hóa đơn.', 1;
        IF @TrangThai NOT IN (N'Đã giao', N'Trả hàng/Hoàn tiền')
            THROW 50002, N'Chỉ lập hóa đơn cho đơn đã giao tới khách. Đơn đang chờ xác nhận, chờ lấy hàng, đang giao hoặc đã hủy thì chưa lập.', 1;
        SELECT @MaHD = MaHD FROM HoaDon WHERE MaDH = @MaDH AND LoaiHoaDon = N'Hóa đơn bán hàng';
        IF @MaHD IS NOT NULL
        BEGIN
            SET @Loi = N'Đơn này đã có hóa đơn ' + @MaHD + N'. Hóa đơn đã phát hành thì không sửa được; khách trả hàng thì lập hóa đơn điều chỉnh giảm.';
            THROW 50003, @Loi, 1;
        END

        DECLARE @TienHang DECIMAL(18,2) = (SELECT ISNULL(SUM(SoLuong * DonGia), 0) FROM ChiTietDonHang WHERE MaDH = @MaDH);
        DECLARE @TongTien DECIMAL(18,2) = CASE WHEN @TienHang - ISNULL(@GiamGia, 0) < 0 THEN 0 ELSE @TienHang - ISNULL(@GiamGia, 0) END;
        DECLARE @ThueSuat DECIMAL(5,2) = ISNULL((SELECT TOP 1 ThueSuat FROM ThueSuatGTGT
                                                 WHERE TuNgay <= CAST(GETDATE() AS DATE) AND (DenNgay IS NULL OR DenNgay >= CAST(GETDATE() AS DATE))
                                                 ORDER BY TuNgay DESC), 10);
        DECLARE @ChuaThue DECIMAL(18,2) = ROUND(@TongTien * 100 / (100 + @ThueSuat), 0);

        DECLARE @So INT = (SELECT ISNULL(MAX(TRY_CAST(SUBSTRING(MaHD, 3, 20) AS INT)), 0) + 1 FROM HoaDon WITH (UPDLOCK, HOLDLOCK) WHERE MaHD LIKE 'HD%');
        SET @MaHD = 'HD' + RIGHT('000000' + CAST(@So AS VARCHAR(10)), 6);

        VALUES (@MaHD, @MaDH, GETDATE(), @TongTien, N'Hóa đơn bán hàng', ISNULL(@GiamGia, 0), @ThueSuat, @ChuaThue, @TongTien - @ChuaThue,
                @Ten, @DiaChi, NULLIF(LTRIM(RTRIM(@MaSoThueNguoiMua)), ''));

        SELECT @MaHD, MaSP, SoLuong, DonGia, SoLuong * DonGia FROM ChiTietDonHang WHERE MaDH = @MaDH;

        VALUES ('HDDT-' + @MaHD, @MaHD, UPPER(LEFT(REPLACE(CONVERT(VARCHAR(36), NEWID()), '-', ''), 16)),
                N'Hóa đơn mô phỏng, chưa ký số và chưa gửi cơ quan thuế', GETDATE());

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_LapHoaDonDieuChinh;
GO
CREATE PROCEDURE dbo.sp_LapHoaDonDieuChinh
    @MaDH VARCHAR(20),
    @MaHD VARCHAR(20) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @Goc VARCHAR(20), @Ten NVARCHAR(255), @DiaChi NVARCHAR(255), @Mst VARCHAR(20);
        SELECT @Goc = MaHD, @Ten = TenNguoiMua, @DiaChi = DiaChiNguoiMua, @Mst = MaSoThueNguoiMua
        FROM HoaDon WITH (UPDLOCK) WHERE MaDH = @MaDH AND LoaiHoaDon = N'Hóa đơn bán hàng';
        IF @Goc IS NULL
            THROW 50004, N'Đơn này chưa có hóa đơn bán hàng nên không cần lập hóa đơn điều chỉnh.', 1;

        DECLARE @DaHoan DECIMAL(18,2) = (SELECT ISNULL(SUM(SoTienHoan), 0) FROM TraHang WHERE MaDH = @MaDH);
        DECLARE @DaDieuChinh DECIMAL(18,2) = (SELECT ISNULL(SUM(TongTien), 0) FROM HoaDon WHERE MaDH = @MaDH AND LoaiHoaDon = N'Điều chỉnh giảm');
        DECLARE @Tien DECIMAL(18,2) = @DaHoan - @DaDieuChinh;
        IF @Tien <= 0
            THROW 50005, N'Tiền hoàn của đơn này đã được lập hóa đơn điều chỉnh đủ rồi.', 1;

        DECLARE @ThueSuat DECIMAL(5,2) = (SELECT ThueSuat FROM HoaDon WHERE MaHD = @Goc);
        DECLARE @ChuaThue DECIMAL(18,2) = ROUND(@Tien * 100 / (100 + @ThueSuat), 0);
        DECLARE @So INT = (SELECT ISNULL(MAX(TRY_CAST(SUBSTRING(MaHD, 3, 20) AS INT)), 0) + 1 FROM HoaDon WITH (UPDLOCK, HOLDLOCK) WHERE MaHD LIKE 'HD%');
        SET @MaHD = 'HD' + RIGHT('000000' + CAST(@So AS VARCHAR(10)), 6);

        VALUES (@MaHD, @MaDH, GETDATE(), @Tien, N'Điều chỉnh giảm', @Goc, 0, @ThueSuat, @ChuaThue, @Tien - @ChuaThue, @Ten, @DiaChi, @Mst);

        SELECT @MaHD, t.MaSP, SUM(t.SoLuong), ROUND(SUM(t.SoTienHoan) / SUM(t.SoLuong), 2), SUM(t.SoTienHoan)
        FROM TraHang t
        WHERE t.MaDH = @MaDH
          AND NOT EXISTS (SELECT 1 FROM ChiTietHoaDon c JOIN HoaDon h ON h.MaHD = c.MaHD
                          WHERE h.MaDH = @MaDH AND h.LoaiHoaDon = N'Điều chỉnh giảm' AND c.MaSP = t.MaSP)
        GROUP BY t.MaSP;

        IF NOT EXISTS (SELECT 1 FROM ChiTietHoaDon WHERE MaHD = @MaHD)
            THROW 50006, N'Các món khách trả đã có trong hóa đơn điều chỉnh trước. Lần trả thêm của cùng món cần người quản trị lập tay.', 1;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_DongBoShopee_CapNhat;
GO
CREATE PROCEDURE dbo.sp_DongBoShopee_CapNhat
    @MaDongBo VARCHAR(20),
    @MaDonShopee VARCHAR(50),
    @TrangThaiDongBo NVARCHAR(50),
    @GhiChu NVARCHAR(255) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE DongBoShopee
    SET MaDonShopee = @MaDonShopee,
        TrangThaiDongBo = @TrangThaiDongBo,
        ThoiGianDongBo = CASE WHEN @TrangThaiDongBo = N'Đã đồng bộ' THEN GETDATE() ELSE ThoiGianDongBo END,
        GhiChu = ISNULL(@GhiChu, GhiChu)
    WHERE MaDongBo = @MaDongBo;
END;
GO

CREATE OR ALTER FUNCTION fn_TopSanPhamBanChay
(
    @TuNgay DATETIME,
    @DenNgay DATETIME
)
RETURNS TABLE
AS
RETURN
(
    SELECT
        sp.MaSP,
        sp.TenSP,
        ISNULL(SUM(ct.SoLuong), 0) AS TongSoLuongBan,
        ISNULL(SUM(ct.SoLuong * ct.DonGia), 0) AS DoanhThu
    FROM SanPham sp WITH (NOLOCK)
    JOIN ChiTietDonHang ct WITH (NOLOCK) ON sp.MaSP = ct.MaSP
    JOIN DonHang dh WITH (NOLOCK) ON ct.MaDH = dh.MaDH
    WHERE dh.NgayDat >= @TuNgay AND dh.NgayDat < DATEADD(DAY, 1, @DenNgay)
      AND ISNULL(dh.TrangThai, N'') NOT LIKE N'%hủy%'
    GROUP BY sp.MaSP, sp.TenSP
);
GO

CREATE OR ALTER FUNCTION fn_DanhSachCanhBaoTon()
RETURNS TABLE
AS
RETURN
(
    SELECT
        tk.MaKho,
        k.TenKho,
        sp.MaSP,
        sp.TenSP,
        tk.SoLuongTon AS TonHienTai,
        sp.NguongAnToan
    FROM TonKho tk WITH (NOLOCK)
    JOIN Kho k WITH (NOLOCK) ON tk.MaKho = k.MaKho
    JOIN SanPham sp WITH (NOLOCK) ON tk.MaSP = sp.MaSP
    WHERE tk.SoLuongTon <= sp.NguongAnToan
);
GO

CREATE OR ALTER FUNCTION fn_BaoCaoXuatNhapTon
(
    @TuNgay DATETIME,
    @DenNgay DATETIME
)
RETURNS TABLE
AS
RETURN
(
    SELECT
        sp.MaSP,
        sp.TenSP,
        ISNULL(Nhap.TongNhap, 0) AS TongNhap,
        ISNULL(Xuat.TongXuat, 0) AS TongXuat,
        ISNULL(Hoan.SoLuong, 0) AS HangHoanVe,
        ISNULL(Tra.SoLuong, 0) AS KhachTraNhapLai,
        ISNULL(KiemKe.SoLuong, 0) AS ChenhLechKiemKe,
        ISNULL(Ton.SoLuongTon, 0) AS TonCuoiKy
    FROM SanPham sp WITH (NOLOCK)
    LEFT JOIN (
        SELECT ctn.MaSP, SUM(ctn.SoLuong) AS TongNhap
        FROM ChiTietPhieuNhap ctn WITH (NOLOCK)
        JOIN PhieuNhap pn WITH (NOLOCK) ON ctn.MaPN = pn.MaPN
        WHERE pn.NgayNhap >= @TuNgay AND pn.NgayNhap < DATEADD(DAY, 1, @DenNgay)
        GROUP BY ctn.MaSP
    ) Nhap ON sp.MaSP = Nhap.MaSP
    LEFT JOIN (
        SELECT ctx.MaSP, SUM(ctx.SoLuong) AS TongXuat
        FROM ChiTietPhieuXuat ctx WITH (NOLOCK)
        JOIN PhieuXuat px WITH (NOLOCK) ON ctx.MaPX = px.MaPX
        WHERE px.NgayXuat >= @TuNgay AND px.NgayXuat < DATEADD(DAY, 1, @DenNgay)
        GROUP BY ctx.MaSP
    ) Xuat ON sp.MaSP = Xuat.MaSP
    LEFT JOIN (
        SELECT h.MaSP, SUM(h.SoLuong) AS SoLuong
        FROM HangHoanVeKho h WITH (NOLOCK)
        WHERE h.TrangThai = N'Đã nhận về kho'
          AND h.NgayNhanVe >= @TuNgay AND h.NgayNhanVe < DATEADD(DAY, 1, @DenNgay)
        GROUP BY h.MaSP
    ) Hoan ON sp.MaSP = Hoan.MaSP
    LEFT JOIN (
        SELECT ct.MaSP, SUM(ct.ChenhLech) AS SoLuong
        FROM ChiTietKiemKe ct WITH (NOLOCK)
        JOIN PhieuKiemKe p WITH (NOLOCK) ON p.MaKK = ct.MaKK
        WHERE p.TrangThai = N'Đã chốt'
          AND p.NgayChot >= @TuNgay AND p.NgayChot < DATEADD(DAY, 1, @DenNgay)
        GROUP BY ct.MaSP
    ) KiemKe ON sp.MaSP = KiemKe.MaSP
    LEFT JOIN (
        SELECT t.MaSP, SUM(t.SoLuong) AS SoLuong
        FROM TraHang t WITH (NOLOCK)
        WHERE t.TinhTrangHang = N'Còn bán được'
          AND t.NgayTra >= @TuNgay AND t.NgayTra < DATEADD(DAY, 1, @DenNgay)
        GROUP BY t.MaSP
    ) Tra ON sp.MaSP = Tra.MaSP
    LEFT JOIN (
        SELECT MaSP, SUM(SoLuongTon) AS SoLuongTon
        FROM TonKho WITH (NOLOCK)
        GROUP BY MaSP
    ) Ton ON sp.MaSP = Ton.MaSP
);
GO

CREATE OR ALTER VIEW dbo.vw_TienDonHang
AS
SELECT
    b.*,
    b.TienShopNhan - b.GiaVonHangBan AS LaiGop
FROM (
    SELECT
        dh.MaDH,
        dh.NgayDat,
        CAST(dh.NgayDat AS DATE) AS Ngay,
        dh.MaDoiTac,
        ISNULL(dt.TenDoiTac, N'Bán lẻ') AS KenhBan,
        dh.TrangThai,
        dh.PhuongThucThanhToan,
        x.DaHuy,
        x.DaGiao,
        CASE WHEN x.DaHuy = 1 THEN 0 ELSE ISNULL(dh.TongTien, 0) END AS TienHang,
        CASE WHEN x.DaHuy = 1 THEN 0 ELSE dh.GiamGiaCuaShop END AS GiamGiaCuaShop,
        CASE WHEN x.DaHuy = 1 THEN 0 ELSE dh.PhiVanChuyenKhachTra END AS PhiVanChuyenKhachTra,
        CASE WHEN x.DaHuy = 1 THEN 0 ELSE ISNULL(dh.TongTien, 0) - dh.GiamGiaCuaShop + dh.PhiVanChuyenKhachTra END AS KhachThanhToan,
        CASE WHEN x.DaGiao = 1 THEN ISNULL(phi.PhiXuLyGiaoDich, 0) ELSE 0 END AS PhiXuLyGiaoDich,
        CASE WHEN x.DaGiao = 1 THEN ISNULL(phi.PhiCoDinh, 0) ELSE 0 END AS PhiCoDinh,
        CASE WHEN x.DaGiao = 1 THEN ISNULL(phi.PhiKhac, 0) ELSE 0 END AS PhiKhac,
        CASE WHEN x.DaGiao = 1 THEN ISNULL(phi.TongPhi, 0) ELSE 0 END AS PhiSan,
        CASE WHEN x.DaGiao = 1 THEN ISNULL(th.TienHoan, 0) ELSE 0 END AS TienHoanKhach,
        CASE WHEN x.DaGiao = 1
             THEN ISNULL(dh.TongTien, 0) - dh.GiamGiaCuaShop - ISNULL(phi.TongPhi, 0) - ISNULL(th.TienHoan, 0)
             ELSE 0 END AS TienShopNhan,
        CASE WHEN x.DaGiao = 1 THEN ISNULL(gv.GiaVon, 0) - ISNULL(th.GiaVonNhapLai, 0) ELSE 0 END AS GiaVonHangBan
    FROM DonHang dh
    LEFT JOIN DoiTac dt ON dt.MaDoiTac = dh.MaDoiTac
    CROSS APPLY (
        SELECT CASE WHEN ISNULL(dh.TrangThai, N'') LIKE N'%hủy%' THEN 1 ELSE 0 END AS DaHuy,
               CASE WHEN dh.TrangThai IN (N'Đã giao', N'Trả hàng/Hoàn tiền') THEN 1 ELSE 0 END AS DaGiao
    ) x
    OUTER APPLY (
        SELECT SUM(ct.SoLuong * ISNULL(ct.GiaVon, 0)) AS GiaVon
        FROM ChiTietDonHang ct
        WHERE ct.MaDH = dh.MaDH
    ) gv
    OUTER APPLY (
        SELECT SUM(t.SoTienHoan) AS TienHoan,
               SUM(CASE WHEN t.TinhTrangHang = N'Còn bán được' THEN t.SoLuong * ISNULL(ct.GiaVon, 0) ELSE 0 END) AS GiaVonNhapLai
        FROM TraHang t
        LEFT JOIN ChiTietDonHang ct ON ct.MaDH = t.MaDH AND ct.MaSP = t.MaSP
        WHERE t.MaDH = dh.MaDH
    ) th
    OUTER APPLY (
        SELECT SUM(CASE WHEN p.LoaiPhi = N'Phí xử lý giao dịch' THEN v.Tien ELSE 0 END) AS PhiXuLyGiaoDich,
               SUM(CASE WHEN p.LoaiPhi = N'Phí cố định' THEN v.Tien ELSE 0 END) AS PhiCoDinh,
               SUM(CASE WHEN p.LoaiPhi NOT IN (N'Phí xử lý giao dịch', N'Phí cố định') THEN v.Tien ELSE 0 END) AS PhiKhac,
               SUM(v.Tien) AS TongPhi
        FROM PhiSan p
        OUTER APPLY (
            SELECT SUM(ct.SoLuong * ct.DonGia) AS TienHangDanhMuc
            FROM ChiTietDonHang ct
            JOIN SanPham sp ON sp.MaSP = ct.MaSP
            WHERE p.MaDanhMuc IS NOT NULL AND ct.MaDH = dh.MaDH AND sp.MaDanhMuc = p.MaDanhMuc
        ) dm
        CROSS APPLY (
            SELECT ROUND(CASE p.CachTinh
                             WHEN N'Phần trăm tiền hàng' THEN
                                 CASE WHEN p.MaDanhMuc IS NULL THEN ISNULL(dh.TongTien, 0) - dh.GiamGiaCuaShop
                                      ELSE ISNULL(dm.TienHangDanhMuc, 0) END * p.GiaTri / 100
                             WHEN N'Phần trăm tiền khách trả' THEN (ISNULL(dh.TongTien, 0) - dh.GiamGiaCuaShop + dh.PhiVanChuyenKhachTra) * p.GiaTri / 100
                             ELSE p.GiaTri END, 0) AS Tien
        ) v
        WHERE p.MaDoiTac = dh.MaDoiTac
          AND p.TuNgay <= CAST(dh.NgayDat AS DATE)
          AND (p.DenNgay IS NULL OR p.DenNgay >= CAST(dh.NgayDat AS DATE))
    ) phi
) b;
GO

CREATE OR ALTER FUNCTION fn_ThongKeDoanhThu
(
    @TuNgay DATETIME,
    @DenNgay DATETIME
)
RETURNS TABLE
AS
RETURN
(
    SELECT
        Ngay,
        COUNT(MaDH) AS SoDon,
        SUM(TienHang) AS TongDoanhThu,
        SUM(DaGiao) AS SoDonDaGiao,
        SUM(GiamGiaCuaShop) AS GiamGiaCuaShop,
        SUM(PhiSan) AS PhiSan,
        SUM(TienHoanKhach) AS TienHoanKhach,
        SUM(TienShopNhan) AS TienShopNhan,
        SUM(GiaVonHangBan) AS GiaVonHangBan,
        SUM(LaiGop) AS LaiGop
    FROM dbo.vw_TienDonHang
    WHERE NgayDat >= @TuNgay AND NgayDat < DATEADD(DAY, 1, @DenNgay)
      AND DaHuy = 0
    GROUP BY Ngay
);
GO

CREATE OR ALTER FUNCTION fn_LayNguoiDungHienTai()
RETURNS VARCHAR(20)
AS
BEGIN
    DECLARE @UserSession VARCHAR(20);
    SET @UserSession = CAST(SESSION_CONTEXT(N'CurrentUserID') AS VARCHAR(20));

    IF @UserSession IS NULL OR NOT EXISTS (SELECT 1 FROM NguoiDung WHERE MaND = @UserSession)
    BEGIN
        SELECT TOP 1 @UserSession = MaND
        FROM NguoiDung
        WHERE TenTK = SUSER_SNAME() OR MaND = SUSER_SNAME();
    END

    IF @UserSession IS NOT NULL AND NOT EXISTS (SELECT 1 FROM NguoiDung WHERE MaND = @UserSession)
        SET @UserSession = NULL;

    RETURN @UserSession;
END;
GO

CREATE OR ALTER FUNCTION dbo.fn_NgayDuLieuMoiNhat()
RETURNS DATE
AS
BEGIN
    DECLARE @Ngay DATE = (SELECT CAST(MAX(NgayDat) AS DATE) FROM DonHang);
    RETURN ISNULL(@Ngay, CAST(GETDATE() AS DATE));
END;
GO

CREATE OR ALTER VIEW vw_LichSuGiaoDich
AS
SELECT
    ls.MaLichSu,
    ls.LoaiGiaoDich,
    ls.MaThamChieu,
    ls.MaSP,
    sp.TenSP,
    ls.MaKho,
    k.TenKho,
    ls.SoLuong,
    ls.SoTien,
    ls.MoTa,
    ls.MaND,
    nd.HoTen AS NguoiThucHien,
    ls.ThoiGianGD
FROM LichSuGiaoDich ls
LEFT JOIN SanPham sp ON ls.MaSP = sp.MaSP
LEFT JOIN Kho k ON ls.MaKho = k.MaKho
LEFT JOIN NguoiDung nd ON ls.MaND = nd.MaND;
GO

CREATE OR ALTER VIEW vw_SanPham_NCCGanNhat
AS
SELECT sp.MaSP, ncc.MaNCC, ncc.TenNCC
FROM SanPham sp
OUTER APPLY (
    SELECT TOP 1 pn.MaNCC
    FROM ChiTietPhieuNhap ctn
    JOIN PhieuNhap pn ON pn.MaPN = ctn.MaPN
    WHERE ctn.MaSP = sp.MaSP
    ORDER BY pn.NgayNhap DESC
) LastPN
LEFT JOIN NhaCungCap ncc ON ncc.MaNCC = LastPN.MaNCC;
GO

CREATE OR ALTER VIEW vw_DongBoShopee
AS
SELECT
    ds.MaDongBo,
    ds.MaDH,
    dh.NgayDat,
    dh.TrangThai AS TrangThaiDonHang,
    dh.TongTien,
    kh.TenKH,
    dt.TenDoiTac,
    ds.MaDonShopee,
    ds.TrangThaiDongBo,
    ds.ThoiGianTao,
    ds.ThoiGianDongBo,
    ds.GhiChu
FROM DongBoShopee ds
JOIN DonHang dh ON ds.MaDH = dh.MaDH
LEFT JOIN KhachHang kh ON dh.MaKH = kh.MaKH
LEFT JOIN DoiTac dt ON dh.MaDoiTac = dt.MaDoiTac;
GO

CREATE OR ALTER TRIGGER trg_CapNhatTonKho_Nhap
ON ChiTietPhieuNhap
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT pn.MaKho, C.MaSP, SUM(C.SoLuongChenhLech) AS SoLuongChenhLech
            FROM (
                SELECT i.MaPN, i.MaSP, i.SoLuong AS SoLuongChenhLech FROM inserted i
                UNION ALL
                SELECT d.MaPN, d.MaSP, -d.SoLuong AS SoLuongChenhLech FROM deleted d
            ) C
            JOIN PhieuNhap pn ON pn.MaPN = C.MaPN
            GROUP BY pn.MaKho, C.MaSP
        ) Agg
        JOIN TonKho T WITH (UPDLOCK) ON T.MaKho = Agg.MaKho AND T.MaSP = Agg.MaSP
        WHERE Agg.SoLuongChenhLech < 0 AND (T.SoLuongTon + Agg.SoLuongChenhLech < 0)
    )
    BEGIN
        RAISERROR(N'Lỗi: Sản phẩm trong kho đã được xuất bán, không thể giảm số lượng nhập hoặc xóa phiếu nhập!', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    MERGE TonKho WITH (ROWLOCK) AS target
    USING (
        SELECT pn.MaKho, C.MaSP, SUM(C.SoLuongChenhLech) AS SoLuongChenhLech
        FROM (
            SELECT i.MaPN, i.MaSP, i.SoLuong AS SoLuongChenhLech FROM inserted i
            UNION ALL
            SELECT d.MaPN, d.MaSP, -d.SoLuong AS SoLuongChenhLech FROM deleted d
        ) C
        JOIN PhieuNhap pn ON pn.MaPN = C.MaPN
        GROUP BY pn.MaKho, C.MaSP
    ) AS source
    ON target.MaKho = source.MaKho AND target.MaSP = source.MaSP
    WHEN MATCHED THEN
        UPDATE SET target.SoLuongTon = target.SoLuongTon + source.SoLuongChenhLech
    WHEN NOT MATCHED BY TARGET AND source.SoLuongChenhLech > 0 THEN
        INSERT (MaKho, MaSP, SoLuongTon) VALUES (source.MaKho, source.MaSP, source.SoLuongChenhLech);
END;
GO

CREATE OR ALTER TRIGGER trg_PhieuXuat_DoiKho
ON PhieuXuat
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF UPDATE(MaKho)
    BEGIN
        SET XACT_ABORT ON;

        IF EXISTS (
            SELECT 1
            FROM (
                SELECT i.MaKho, ctx.MaSP, SUM(ctx.SoLuong) AS TongSoLuong
                FROM inserted i
                JOIN ChiTietPhieuXuat ctx WITH (NOLOCK) ON i.MaPX = ctx.MaPX
                GROUP BY i.MaKho, ctx.MaSP
            ) Req
            LEFT JOIN TonKho T WITH (UPDLOCK) ON T.MaKho = Req.MaKho AND T.MaSP = Req.MaSP
            WHERE T.MaSP IS NULL OR T.SoLuongTon < Req.TongSoLuong
        )
        BEGIN
            RAISERROR(N'Lỗi: Kho mới được chọn không đủ tồn kho để chuyển đổi!', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        UPDATE T
        SET T.SoLuongTon = T.SoLuongTon + CT.TongSoLuong
        FROM TonKho T WITH (UPDLOCK)
        JOIN (
            SELECT d.MaKho, ctx.MaSP, SUM(ctx.SoLuong) AS TongSoLuong
            FROM deleted d JOIN ChiTietPhieuXuat ctx WITH (NOLOCK) ON d.MaPX = ctx.MaPX
            GROUP BY d.MaKho, ctx.MaSP
        ) CT ON T.MaKho = CT.MaKho AND T.MaSP = CT.MaSP;

        UPDATE T
        SET T.SoLuongTon = T.SoLuongTon - CT.TongSoLuong
        FROM TonKho T WITH (UPDLOCK)
        JOIN (
            SELECT i.MaKho, ctx.MaSP, SUM(ctx.SoLuong) AS TongSoLuong
            FROM inserted i JOIN ChiTietPhieuXuat ctx WITH (NOLOCK) ON i.MaPX = ctx.MaPX
            GROUP BY i.MaKho, ctx.MaSP
        ) CT ON T.MaKho = CT.MaKho AND T.MaSP = CT.MaSP;
    END
END;
GO

CREATE OR ALTER TRIGGER trg_CapNhatTonKho_Xuat
ON ChiTietPhieuXuat
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT px.MaKho, C.MaSP, SUM(C.SoLuongXuatChenhLech) AS SoLuongXuatChenhLech
            FROM (
                SELECT i.MaPX, i.MaSP, i.SoLuong AS SoLuongXuatChenhLech FROM inserted i
                UNION ALL
                SELECT d.MaPX, d.MaSP, -d.SoLuong AS SoLuongXuatChenhLech FROM deleted d
            ) C
            JOIN PhieuXuat px ON px.MaPX = C.MaPX
            GROUP BY px.MaKho, C.MaSP
        ) C
        LEFT JOIN TonKho T WITH (UPDLOCK) ON T.MaKho = C.MaKho AND T.MaSP = C.MaSP
        WHERE (C.SoLuongXuatChenhLech > 0 AND (T.MaSP IS NULL OR T.SoLuongTon < C.SoLuongXuatChenhLech))
           OR (C.SoLuongXuatChenhLech < 0 AND (T.MaSP IS NULL OR T.SoLuongTon + (-C.SoLuongXuatChenhLech) < 0))
    )
    BEGIN
        RAISERROR(N'Lỗi: Số lượng tồn kho không đủ hoặc thao tác điều chỉnh làm sai lệch tồn kho!', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    UPDATE T
    SET T.SoLuongTon = T.SoLuongTon - C.SoLuongXuatChenhLech
    FROM TonKho T WITH (UPDLOCK)
    JOIN (
        SELECT px.MaKho, C.MaSP, SUM(C.SoLuongXuatChenhLech) AS SoLuongXuatChenhLech
        FROM (
            SELECT i.MaPX, i.MaSP, i.SoLuong AS SoLuongXuatChenhLech FROM inserted i
            UNION ALL
            SELECT d.MaPX, d.MaSP, -d.SoLuong AS SoLuongXuatChenhLech FROM deleted d
        ) C
        JOIN PhieuXuat px ON px.MaPX = C.MaPX
        GROUP BY px.MaKho, C.MaSP
    ) C ON T.MaKho = C.MaKho AND T.MaSP = C.MaSP;
END;
GO

CREATE OR ALTER TRIGGER trg_CapNhatTongTienPhieuNhap
ON ChiTietPhieuNhap
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE PhieuNhap
    SET TongTien = ISNULL((
        SELECT SUM(ThanhTien)
        FROM ChiTietPhieuNhap WITH (NOLOCK)
        WHERE ChiTietPhieuNhap.MaPN = PhieuNhap.MaPN
    ), 0)
    WHERE MaPN IN (
        SELECT MaPN FROM inserted
        UNION
        SELECT MaPN FROM deleted
    );

    UPDATE sp
    SET sp.GiaVon = g.GiaVon
    FROM SanPham sp
    JOIN (
        SELECT MaSP, CAST(SUM(SoLuong * DonGia) / NULLIF(SUM(SoLuong), 0) AS DECIMAL(18,2)) AS GiaVon
        FROM ChiTietPhieuNhap WITH (NOLOCK)
        WHERE MaSP IN (SELECT MaSP FROM inserted UNION SELECT MaSP FROM deleted)
        GROUP BY MaSP
    ) g ON g.MaSP = sp.MaSP
    WHERE g.GiaVon IS NOT NULL;
END;
GO

CREATE OR ALTER TRIGGER trg_CapNhatTongTienDonHang
ON ChiTietDonHang
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE ct
    SET ct.GiaVon = sp.GiaVon
    FROM ChiTietDonHang ct
    JOIN inserted i ON i.MaDH = ct.MaDH AND i.MaSP = ct.MaSP
    JOIN SanPham sp ON sp.MaSP = ct.MaSP
    WHERE ct.GiaVon IS NULL;

    UPDATE DonHang
    SET TongTien = ISNULL((
        SELECT SUM(ThanhTien)
        FROM ChiTietDonHang WITH (NOLOCK)
        WHERE ChiTietDonHang.MaDH = DonHang.MaDH
    ), 0)
    WHERE MaDH IN (
        SELECT MaDH FROM inserted
        UNION
        SELECT MaDH FROM deleted
    );
END;
GO

CREATE OR ALTER TRIGGER trg_DongBoTrangThaiVanDon
ON VanDon
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT (UPDATE(MaDH) OR UPDATE(TrangThai) OR UPDATE(NgayGiaoXong)) RETURN;

    UPDATE DH
    SET DH.TrangThai = I.TrangThai,
        DH.NgayGiao = CASE WHEN I.TrangThai = N'Đã giao' THEN I.NgayGiaoXong ELSE DH.NgayGiao END
    FROM DonHang DH
    JOIN inserted I ON DH.MaDH = I.MaDH
    WHERE I.TrangThai IN (N'Đang giao', N'Đã giao')
      AND ISNULL(DH.TrangThai, N'') NOT IN (N'Đã hủy', N'Trả hàng/Hoàn tiền')
      AND ISNULL(DH.TrangThai, N'') <> I.TrangThai;
END;
GO

CREATE OR ALTER TRIGGER trg_CapNhatTonKho_TraHang
ON TraHang
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF EXISTS (SELECT 1 FROM inserted) AND EXISTS (SELECT 1 FROM deleted)
       AND NOT (UPDATE(MaKho) OR UPDATE(MaSP) OR UPDATE(SoLuong) OR UPDATE(TinhTrangHang))
        RETURN;

    IF EXISTS (SELECT 1 FROM deleted WHERE TinhTrangHang = N'Còn bán được')
    BEGIN
        IF EXISTS (
            SELECT 1
            FROM (
                SELECT CAST(MaKho AS VARCHAR(20)) AS MaKho, CAST(MaSP AS VARCHAR(50)) AS MaSP, SUM(SoLuong) AS TongSoLuong
                FROM deleted
                WHERE TinhTrangHang = N'Còn bán được'
                GROUP BY MaKho, MaSP
            ) D
            JOIN TonKho T WITH (UPDLOCK) ON T.MaKho = D.MaKho AND T.MaSP = D.MaSP
            WHERE T.SoLuongTon < D.TongSoLuong
        )
        BEGIN
            RAISERROR(N'Lỗi: Số lượng tồn kho không đủ để thực hiện việc hủy hoặc sửa phiếu trả hàng!', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        UPDATE T
        SET T.SoLuongTon = T.SoLuongTon - D.TongSoLuong
        FROM TonKho T WITH (UPDLOCK)
        JOIN (
            SELECT CAST(MaKho AS VARCHAR(20)) AS MaKho, CAST(MaSP AS VARCHAR(50)) AS MaSP, SUM(SoLuong) AS TongSoLuong
            FROM deleted
            WHERE TinhTrangHang = N'Còn bán được'
            GROUP BY MaKho, MaSP
        ) D ON T.MaKho = D.MaKho AND T.MaSP = D.MaSP;
    END

    MERGE TonKho WITH (ROWLOCK) AS target
    USING (
        SELECT CAST(MaKho AS VARCHAR(20)) AS MaKho, CAST(MaSP AS VARCHAR(50)) AS MaSP, SUM(SoLuong) AS TongSoLuong
        FROM inserted
        WHERE TinhTrangHang = N'Còn bán được'
        GROUP BY MaKho, MaSP
    ) AS source
    ON target.MaKho = source.MaKho AND target.MaSP = source.MaSP
    WHEN MATCHED THEN
        UPDATE SET target.SoLuongTon = target.SoLuongTon + source.TongSoLuong
    WHEN NOT MATCHED BY TARGET THEN
        INSERT (MaKho, MaSP, SoLuongTon) VALUES (source.MaKho, source.MaSP, source.TongSoLuong);
END;
GO

CREATE OR ALTER TRIGGER trg_HangHoanVeKho
ON HangHoanVeKho
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        RAISERROR(N'Phiếu hàng hoàn về kho không được xóa. Nếu ghi nhầm, hãy báo người quản trị để điều chỉnh tồn kho.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    IF EXISTS (
        SELECT 1
        FROM inserted i
        JOIN deleted d ON d.Id = i.Id
        WHERE i.MaDH <> d.MaDH OR i.MaPX <> d.MaPX OR i.MaKho <> d.MaKho OR i.MaSP <> d.MaSP
           OR i.SoLuong <> d.SoLuong OR d.TrangThai = N'Đã nhận về kho'
    )
    BEGIN
        RAISERROR(N'Phiếu hàng hoàn chỉ được đổi từ "Đang hoàn về" sang "Đã nhận về kho". Các thông tin khác không được sửa.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    DECLARE @VeKho TABLE (Id INT PRIMARY KEY);
    SELECT i.Id
    FROM inserted i
    LEFT JOIN deleted d ON d.Id = i.Id
    WHERE i.TrangThai = N'Đã nhận về kho' AND (d.Id IS NULL OR d.TrangThai = N'Đang hoàn về');

    MERGE TonKho WITH (ROWLOCK) AS target
    USING (
        SELECT i.MaKho, i.MaSP, SUM(i.SoLuong) AS TongSoLuong
        FROM inserted i
        JOIN @VeKho v ON v.Id = i.Id
        GROUP BY i.MaKho, i.MaSP
    ) AS source
    ON target.MaKho = source.MaKho AND target.MaSP = source.MaSP
    WHEN MATCHED THEN
        UPDATE SET target.SoLuongTon = target.SoLuongTon + source.TongSoLuong
    WHEN NOT MATCHED BY TARGET THEN
        INSERT (MaKho, MaSP, SoLuongTon) VALUES (source.MaKho, source.MaSP, source.TongSoLuong);

    SELECT N'Hàng hoàn về kho', i.MaDH, i.MaSP, i.MaKho, i.SoLuong, dbo.fn_LayNguoiDungHienTai(),
           N'Hàng của đơn ' + i.MaDH + N' đã nhận lại vào kho - ' + ISNULL(i.LyDo, N''), ISNULL(i.NgayNhanVe, GETDATE())
    FROM inserted i
    JOIN @VeKho v ON v.Id = i.Id;

    SELECT N'Hàng đang hoàn về', i.MaDH, i.MaSP, i.MaKho, i.SoLuong, dbo.fn_LayNguoiDungHienTai(),
           N'Hàng của đơn ' + i.MaDH + N' đang trên đường về kho, chưa cộng vào tồn - ' + ISNULL(i.LyDo, N''), i.NgayHoan
    FROM inserted i
    WHERE i.TrangThai = N'Đang hoàn về' AND NOT EXISTS (SELECT 1 FROM deleted);
END;
GO

CREATE OR ALTER TRIGGER trg_NhatKy_NhaCungCap
ON NhaCungCap
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @ThaoTac NVARCHAR(255);
    DECLARE @UserSession VARCHAR(20) = dbo.fn_LayNguoiDungHienTai();

    IF EXISTS (SELECT 1 FROM inserted) AND EXISTS (SELECT 1 FROM deleted)
        SET @ThaoTac = N'Cập nhật thông tin Nhà cung cấp';
    ELSE IF EXISTS (SELECT 1 FROM inserted)
        SET @ThaoTac = N'Thêm mới Nhà cung cấp';
    ELSE IF EXISTS (SELECT 1 FROM deleted)
        SET @ThaoTac = N'Xóa thông tin Nhà cung cấp';

    VALUES (@UserSession, @ThaoTac, GETDATE());
END;
GO

CREATE OR ALTER TRIGGER trg_TaoDongBoShopee
ON DonHang
