    FROM inserted i
    JOIN DoiTac dt ON i.MaDoiTac = dt.MaDoiTac
    WHERE dt.TenDoiTac LIKE N'%Shopee%'
      AND NOT EXISTS (SELECT 1 FROM DongBoShopee ds WHERE ds.MaDH = i.MaDH);
