CREATE OR ALTER TRIGGER trg_LichSu_PhieuNhap
ON ChiTietPhieuNhap
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT N'Nhập kho', pn.MaPN, pn.MaKho,
           (SELECT ISNULL(SUM(ct.SoLuong * ct.DonGia), 0) FROM ChiTietPhieuNhap ct WITH (NOLOCK) WHERE ct.MaPN = pn.MaPN),
           dbo.fn_LayNguoiDungHienTai(),
           N'Nhập kho từ nhà cung cấp ' + ISNULL(ncc.TenNCC, N'(không rõ)'), pn.NgayNhap
    FROM (SELECT DISTINCT MaPN FROM inserted) dis
    JOIN PhieuNhap pn WITH (NOLOCK) ON pn.MaPN = dis.MaPN
    LEFT JOIN NhaCungCap ncc WITH (NOLOCK) ON pn.MaNCC = ncc.MaNCC;
END;
GO

CREATE OR ALTER TRIGGER trg_LichSu_PhieuXuat
ON ChiTietPhieuXuat
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT N'Xuất kho', px.MaPX, px.MaKho,
           (SELECT ISNULL(SUM(ctx.SoLuong * sp.GiaBan), 0)
            FROM ChiTietPhieuXuat ctx WITH (NOLOCK)
            JOIN SanPham sp WITH (NOLOCK) ON ctx.MaSP = sp.MaSP
            WHERE ctx.MaPX = px.MaPX),
           dbo.fn_LayNguoiDungHienTai(),
           N'Xuất kho cho đơn hàng ' + ISNULL(px.MaDH, N''), px.NgayXuat
    FROM (SELECT DISTINCT MaPX FROM inserted) dis
    JOIN PhieuXuat px WITH (NOLOCK) ON px.MaPX = dis.MaPX;
END;
GO

CREATE OR ALTER TRIGGER trg_LichSu_DonHang
ON DonHang
AFTER INSERT, UPDATE
