               N'Tạo đơn hàng mới, trạng thái: ' + i.TrangThai, i.NgayDat
        FROM inserted i;
    END
    ELSE IF UPDATE(TrangThai)
    BEGIN
        SELECT N'Đơn hàng', i.MaDH, i.TongTien, dbo.fn_LayNguoiDungHienTai(),
               N'Cập nhật trạng thái đơn hàng: ' + ISNULL(d.TrangThai, N'') + N' -> ' + ISNULL(i.TrangThai, N''), GETDATE()
        FROM inserted i
        JOIN deleted d ON i.MaDH = d.MaDH
        WHERE ISNULL(i.TrangThai, N'') <> ISNULL(d.TrangThai, N'');
    END
END;
GO

