CREATE OR ALTER FUNCTION fn_LamSachKyTu (@VanBan NVARCHAR(MAX))
RETURNS NVARCHAR(MAX)
AS
BEGIN
    IF @VanBan IS NULL RETURN NULL;

    DECLARE @KyTuBo NVARCHAR(50) = N'!@#$%^&*()_+={}[]|\<>?~`":;''';
    DECLARE @i INT = 1;
    WHILE @i <= LEN(@KyTuBo)
    BEGIN
        SET @VanBan = REPLACE(@VanBan, SUBSTRING(@KyTuBo, @i, 1), N' ');
        SET @i = @i + 1;
    END

    SET @VanBan = REPLACE(REPLACE(REPLACE(@VanBan, NCHAR(9), N' '), NCHAR(10), N' '), NCHAR(13), N' ');
    SET @VanBan = REPLACE(REPLACE(REPLACE(@VanBan, N'  ', N' ' + NCHAR(7)), NCHAR(7) + N' ', N''), NCHAR(7), N'');

    RETURN LTRIM(RTRIM(@VanBan));
END;
GO

CREATE OR ALTER FUNCTION fn_ChuanHoaSoDienThoai (@SoDT VARCHAR(50))
RETURNS VARCHAR(20)
AS
BEGIN
    IF @SoDT IS NULL RETURN NULL;

    DECLARE @s VARCHAR(50) = @SoDT;
    WHILE PATINDEX('%[^0-9]%', @s) > 0
        SET @s = STUFF(@s, PATINDEX('%[^0-9]%', @s), 1, '');

    IF LEN(@s) = 11 AND LEFT(@s, 2) = '84'
        SET @s = '0' + SUBSTRING(@s, 3, 9);

    IF LEN(@s) = 10 AND LEFT(@s, 1) = '0' AND RIGHT(@s, 8) <> REPLICATE(RIGHT(@s, 1), 8) RETURN @s;
    RETURN NULL;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_TuDongLamSach_DuLieuGiaoDich;
GO
CREATE PROCEDURE dbo.sp_TuDongLamSach_DuLieuGiaoDich
    @HienKetQua BIT = 1
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @BatDau DATETIME = GETDATE();
    DECLARE @SoDaSua INT = 0, @SoLoi INT = 0, @Lan INT = 1;
    DECLARE @Goc NVARCHAR(100), @Chuan NVARCHAR(100);

    BEGIN TRANSACTION;
    BEGIN TRY
        UPDATE KhachHang
        SET SoDienThoai_ChuanHoa = dbo.fn_ChuanHoaSoDienThoai(SoDT),
            DiaChi_ChuanHoa = NULLIF(dbo.fn_LamSachKyTu(DiaChi), N'');

        SELECT @SoDaSua = @SoDaSua + COUNT(*)
        FROM KhachHang
        WHERE ISNULL(SoDienThoai_ChuanHoa, '') <> ISNULL(SoDT, '')
           OR ISNULL(DiaChi_ChuanHoa, N'') <> ISNULL(DiaChi, N'');

        SELECT @SoLoi = @SoLoi + COUNT(*) FROM KhachHang WHERE SoDienThoai_ChuanHoa IS NULL;

        UPDATE TraHang
        SET NoiDung_DaLamSach = CASE WHEN LyDoTra IS NULL THEN NULL
                                     ELSE N' ' + LOWER(dbo.fn_LamSachKyTu(LyDoTra)) + N' ' END;

        DECLARE cur_Teencode CURSOR LOCAL FAST_FORWARD FOR
            SELECT TuGoc, TuChuanHoa FROM TuDien_Teencode ORDER BY LEN(TuGoc) DESC, Id;

        WHILE @Lan <= 2
        BEGIN
            OPEN cur_Teencode;
            FETCH NEXT FROM cur_Teencode INTO @Goc, @Chuan;
            WHILE @@FETCH_STATUS = 0
            BEGIN
                UPDATE TraHang
                SET NoiDung_DaLamSach = REPLACE(NoiDung_DaLamSach, N' ' + LOWER(@Goc) + N' ', N' ' + @Chuan + N' ')
                WHERE NoiDung_DaLamSach IS NOT NULL;

                FETCH NEXT FROM cur_Teencode INTO @Goc, @Chuan;
            END
            CLOSE cur_Teencode;
            SET @Lan = @Lan + 1;
        END
        DEALLOCATE cur_Teencode;

        UPDATE TraHang SET NoiDung_DaLamSach = LTRIM(RTRIM(NoiDung_DaLamSach)) WHERE NoiDung_DaLamSach IS NOT NULL;

        SELECT @SoDaSua = @SoDaSua + COUNT(*)
        FROM TraHang
        WHERE NoiDung_DaLamSach IS NOT NULL AND NoiDung_DaLamSach <> LyDoTra;

        VALUES (N'Sửa số điện thoại, địa chỉ, chữ viết tắt', @SoDaSua, @SoLoi, @BatDau);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH


    IF @HienKetQua = 1
    SELECT @SoDaSua AS SoBanGhiDaSua, @SoLoi AS SoBanGhiLoi;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_PhatHienVaSua_DuLieuThieu;
GO
CREATE PROCEDURE dbo.sp_PhatHienVaSua_DuLieuThieu
    @HienKetQua BIT = 1
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @BatDau DATETIME = GETDATE();
    DECLARE @SoDaSua INT = 0, @SoLoi INT = 0;

    BEGIN TRANSACTION;
    BEGIN TRY
        UPDATE sp
        SET GiaBan = tb.GiaTB
        FROM SanPham sp
        JOIN (SELECT MaDanhMuc, AVG(GiaBan) AS GiaTB
              FROM SanPham
              WHERE GiaBan IS NOT NULL AND GiaBan > 0
              GROUP BY MaDanhMuc) tb ON tb.MaDanhMuc = sp.MaDanhMuc
        WHERE sp.GiaBan IS NULL;
        SET @SoDaSua = @SoDaSua + @@ROWCOUNT;

        UPDATE sp
        SET NguongAnToan = ISNULL((SELECT CAST(ROUND(AVG(CAST(x.NguongAnToan AS DECIMAL(18,2))), 0) AS INT)
                                   FROM SanPham x
                                   WHERE x.MaDanhMuc = sp.MaDanhMuc AND x.NguongAnToan IS NOT NULL), 10)
        FROM SanPham sp
        WHERE sp.NguongAnToan IS NULL;
        SET @SoDaSua = @SoDaSua + @@ROWCOUNT;

        UPDATE kh
        SET DiaChi = g.DiaChiGiao
        FROM KhachHang kh
        CROSS APPLY (
            SELECT TOP 1 dh.DiaChiGiao
            FROM DonHang dh
            WHERE dh.MaKH = kh.MaKH
              AND dh.HinhThucNhan = N'Giao tận nơi'
              AND dh.TrangThai IN (N'Đã giao', N'Trả hàng/Hoàn tiền')
              AND LEN(LTRIM(RTRIM(ISNULL(dh.DiaChiGiao, N'')))) >= 10
            ORDER BY dh.NgayDat DESC
        ) g
        WHERE kh.DiaChi IS NULL OR LTRIM(RTRIM(kh.DiaChi)) = N'';
        SET @SoDaSua = @SoDaSua + @@ROWCOUNT;

        SELECT @SoLoi = @SoLoi + COUNT(*) FROM SanPham WHERE GiaBan IS NULL;
        SELECT @SoLoi = @SoLoi + COUNT(*) FROM KhachHang WHERE SoDT IS NULL OR LTRIM(RTRIM(SoDT)) = '';
        SELECT @SoLoi = @SoLoi + COUNT(*) FROM KhachHang WHERE DiaChi IS NULL OR LTRIM(RTRIM(DiaChi)) = N'';

        VALUES (N'Điền chỗ còn trống', @SoDaSua, @SoLoi, @BatDau);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH


    IF @HienKetQua = 1
    SELECT @SoDaSua AS SoBanGhiDaSua, @SoLoi AS SoBanGhiConThieu;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_CanhBaoRuiRoHuyDon;
GO
CREATE PROCEDURE dbo.sp_CanhBaoRuiRoHuyDon
    @MaDH VARCHAR(20) = NULL,
    @HienKetQua BIT = 1
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH LichSu AS (
        SELECT MaKH,
               COUNT(*) AS TongDon,
               SUM(CASE WHEN ISNULL(TrangThai, N'') LIKE N'%hủy%' THEN 1 ELSE 0 END) AS DonHuy
        FROM DonHang
        WHERE MaKH IS NOT NULL
        GROUP BY MaKH
    )
    UPDATE dh
    SET TyLeRuiRoHuyDon = d.Diem,
        TrangThaiCanhBaoHuy = CASE WHEN d.Diem >= 60 THEN N'Nguy cơ cao'
                                   WHEN d.Diem >= 30 THEN N'Cần xem'
                                   ELSE N'Bình thường' END
    FROM DonHang dh
    LEFT JOIN KhachHang kh ON kh.MaKH = dh.MaKH
    LEFT JOIN LichSu ls ON ls.MaKH = dh.MaKH
    CROSS APPLY (
        SELECT LTRIM(RTRIM(ISNULL(NULLIF(dh.DiaChiGiao, N''), kh.DiaChi))) AS DiaChi,
               ISNULL(NULLIF(dh.SdtNguoiNhan, ''), kh.SoDT) AS SoDT
    ) gn
    CROSS APPLY (
        SELECT CAST(
                 CASE WHEN dbo.fn_ChuanHoaSoDienThoai(gn.SoDT) IS NULL THEN 40 ELSE 0 END
               + CASE WHEN dh.HinhThucNhan = N'Nhận tại cửa hàng' THEN 0
                      WHEN gn.DiaChi IS NULL OR LEN(gn.DiaChi) < 10 OR gn.DiaChi = N'TP.HCM' THEN 30 ELSE 0 END
               + ISNULL(ROUND(30.0 * ls.DonHuy / NULLIF(ls.TongDon, 0), 0), 0)
               AS DECIMAL(5,2)) AS Diem
    ) d
    WHERE (@MaDH IS NULL OR dh.MaDH = @MaDH);


    IF @HienKetQua = 1
    SELECT MaDH, MaKH, TyLeRuiRoHuyDon, TrangThaiCanhBaoHuy
    FROM DonHang
    WHERE (@MaDH IS NULL OR MaDH = @MaDH)
    ORDER BY TyLeRuiRoHuyDon DESC, MaDH;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_ChiaNhomKhachHang;
GO
CREATE PROCEDURE dbo.sp_ChiaNhomKhachHang
    @NgayTinh DATE = NULL,
    @HienKetQua BIT = 1
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @NgayTinh IS NULL SET @NgayTinh = dbo.fn_NgayDuLieuMoiNhat();
    IF OBJECT_ID('tempdb..#RFM') IS NOT NULL DROP TABLE #RFM;

    ;WITH Goc AS (
        SELECT dh.MaKH,
               DATEDIFF(DAY, MAX(dh.NgayDat), @NgayTinh) AS R,
               COUNT(*) AS F,
               SUM(ISNULL(dh.TongTien, 0)) AS M
        FROM DonHang dh
        WHERE dh.MaKH IS NOT NULL
          AND ISNULL(dh.TrangThai, N'') NOT LIKE N'%hủy%'
        GROUP BY dh.MaKH
    ),
    Diem AS (
        SELECT MaKH, R, F, M,
               NTILE(5) OVER (ORDER BY R DESC, MaKH) AS DiemR,
               NTILE(5) OVER (ORDER BY F ASC,  MaKH) AS DiemF,
               NTILE(5) OVER (ORDER BY M ASC,  MaKH) AS DiemM
        FROM Goc
    )
    SELECT MaKH, R, F, M, DiemR, DiemF, DiemM,
           NTILE(5) OVER (ORDER BY (DiemR + DiemF + DiemM) ASC, MaKH) AS HangRFM
    INTO #RFM
    FROM Diem;

    BEGIN TRANSACTION;
    BEGIN TRY
        UPDATE kh
        SET Nhom_RFM = CASE WHEN r.MaKH IS NULL THEN NULL
                            ELSE N'Hạng ' + CAST(r.HangRFM AS NVARCHAR(1)) + N' - ' +
                                 CASE r.HangRFM WHEN 5 THEN N'Khách ruột' WHEN 4 THEN N'Khách thân' WHEN 3 THEN N'Khách thường'
                                                WHEN 2 THEN N'Khách ít ghé' ELSE N'Khách sắp mất' END END
        FROM KhachHang kh
        LEFT JOIN #RFM r ON r.MaKH = kh.MaKH;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH


    IF @HienKetQua = 1
    SELECT kh.MaKH, kh.TenKH,
           r.R AS SoNgayTuLanMuaCuoi, r.F AS SoDon, r.M AS TongTienMua,
           r.DiemR, r.DiemF, r.DiemM, kh.Nhom_RFM
    FROM KhachHang kh
    LEFT JOIN #RFM r ON r.MaKH = kh.MaKH
    ORDER BY kh.Nhom_RFM DESC, kh.MaKH;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_ChiaNhomBanChay;
GO
CREATE PROCEDURE dbo.sp_ChiaNhomBanChay
    @TuNgay DATE = NULL,
    @DenNgay DATE = NULL,
    @TieuChi VARCHAR(10) = 'DoanhSo'
AS
BEGIN
    SET NOCOUNT ON;

    IF @TieuChi NOT IN ('DoanhSo', 'SanLuong')
    BEGIN
        RAISERROR(N'@TieuChi chỉ nhận ''DoanhSo'' hoặc ''SanLuong''!', 16, 1);
        RETURN;
    END

    ;WITH Ban AS (
        SELECT sp.MaSP, sp.TenSP,
               ISNULL(SUM(CASE WHEN @TieuChi = 'SanLuong'
                               THEN CAST(x.SoLuong AS DECIMAL(18,2))
                               ELSE CAST(x.SoLuong AS DECIMAL(18,2)) * x.DonGia END), 0) AS GiaTri
        FROM SanPham sp
        LEFT JOIN (
            SELECT ct.MaSP, ct.SoLuong, ct.DonGia
            FROM ChiTietDonHang ct
            JOIN DonHang dh ON dh.MaDH = ct.MaDH
            WHERE (@TuNgay IS NULL OR dh.NgayDat >= @TuNgay)
              AND (@DenNgay IS NULL OR dh.NgayDat < DATEADD(DAY, 1, @DenNgay))
              AND ISNULL(dh.TrangThai, N'') NOT LIKE N'%hủy%'
        ) x ON x.MaSP = sp.MaSP
        GROUP BY sp.MaSP, sp.TenSP
    ),
    Xep AS (
        SELECT MaSP, TenSP, GiaTri,
               SUM(GiaTri) OVER () AS Tong,
               SUM(GiaTri) OVER (ORDER BY GiaTri DESC, MaSP
                                 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS LuyKe
        FROM Ban
    )
    SELECT ROW_NUMBER() OVER (ORDER BY GiaTri DESC, MaSP) AS ThuHang,
           MaSP, TenSP, GiaTri,
           CASE WHEN Tong = 0 THEN 0 ELSE CAST(100.0 * GiaTri / Tong AS DECIMAL(9,2)) END AS TyLePhanTram,
           CASE WHEN Tong = 0 THEN 0 ELSE CAST(100.0 * LuyKe / Tong AS DECIMAL(9,2)) END AS TyLeLuyKe,
           CASE WHEN Tong = 0 OR GiaTri = 0 THEN 'C'
                WHEN 100.0 * (LuyKe - GiaTri) / Tong < 80 THEN 'A'
                WHEN 100.0 * (LuyKe - GiaTri) / Tong < 95 THEN 'B'
                ELSE 'C' END AS PhanLoai
    FROM Xep
    ORDER BY ThuHang;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_TimMonHayMuaChung;
GO
CREATE PROCEDURE dbo.sp_TimMonHayMuaChung
    @SupportToiThieu DECIMAL(9,6) = 0.01,
    @ConfidenceToiThieu DECIMAL(9,6) = 0.30,
    @LiftToiThieu DECIMAL(12,4) = 1.0,
    @HienKetQua BIT = 1
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @TongDon INT = (SELECT COUNT(DISTINCT MaDH) FROM ChiTietDonHang);

    BEGIN TRANSACTION;
    BEGIN TRY
        DELETE FROM DeXuat_ComboKhuyenMai;

        IF @TongDon > 0
        BEGIN
            ;WITH DemSP AS (
                SELECT MaSP, COUNT(*) AS SoDon
                FROM ChiTietDonHang
                GROUP BY MaSP
            ),
            DemCap AS (
                SELECT a.MaSP AS SPA, b.MaSP AS SPB, COUNT(*) AS SoDon
                FROM ChiTietDonHang a
                JOIN ChiTietDonHang b ON b.MaDH = a.MaDH AND b.MaSP <> a.MaSP
                GROUP BY a.MaSP, b.MaSP
            )
            SELECT c.SPA, c.SPB,
                   CAST(1.0 * c.SoDon / @TongDon AS DECIMAL(9,6)),
                   CAST(1.0 * c.SoDon / da.SoDon AS DECIMAL(9,6)),
                   CAST((1.0 * c.SoDon / da.SoDon) / (1.0 * db.SoDon / @TongDon) AS DECIMAL(12,4))
            FROM DemCap c
            JOIN DemSP da ON da.MaSP = c.SPA
            JOIN DemSP db ON db.MaSP = c.SPB
            WHERE 1.0 * c.SoDon / @TongDon >= @SupportToiThieu
              AND 1.0 * c.SoDon / da.SoDon >= @ConfidenceToiThieu
              AND (1.0 * c.SoDon / da.SoDon) / (1.0 * db.SoDon / @TongDon) >= @LiftToiThieu;
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH


    IF @HienKetQua = 1
    SELECT d.SanPhamChinhId, sp1.TenSP AS TenSPChinh,
           d.SanPhamKemId, sp2.TenSP AS TenSPKem,
           d.ChiSo_Support, d.ChiSo_Confidence, d.ChiSo_Lift
    FROM DeXuat_ComboKhuyenMai d
    JOIN SanPham sp1 ON sp1.MaSP = d.SanPhamChinhId
    JOIN SanPham sp2 ON sp2.MaSP = d.SanPhamKemId
    ORDER BY d.ChiSo_Lift DESC, d.ChiSo_Confidence DESC;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_PhanTichChuDeKhieuNai;
GO
CREATE PROCEDURE dbo.sp_PhanTichChuDeKhieuNai
    @HienKetQua BIT = 1
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRANSACTION;
    BEGIN TRY
        UPDATE th
        SET NhomLyDoChinh =
            CASE
                WHEN x.Txt IS NULL OR LTRIM(RTRIM(x.Txt)) = N'' THEN N'Không nêu lý do'
                WHEN x.Txt LIKE N'%lỗi%' OR x.Txt LIKE N'%hỏng%' OR x.Txt LIKE N'%vỡ%' OR x.Txt LIKE N'%trầy%'
                  OR x.Txt LIKE N'%xước%' OR x.Txt LIKE N'%móp%' OR x.Txt LIKE N'%không hoạt động%'
                     THEN N'Hàng lỗi / hư hỏng / trầy xước'
                WHEN x.Txt LIKE N'%khác mô tả%' OR x.Txt LIKE N'%không đúng mô tả%' OR x.Txt LIKE N'%không giống%'
                  OR x.Txt LIKE N'%khác hình%' OR x.Txt LIKE N'%hàng giả%' OR x.Txt LIKE N'%nhái%'
                     THEN N'Không đúng mô tả / hàng giả'
                WHEN x.Txt LIKE N'%sai%' OR x.Txt LIKE N'%thiếu%' OR x.Txt LIKE N'%nhầm%' OR x.Txt LIKE N'%không đúng%'
                     THEN N'Giao sai / thiếu hàng'
                WHEN x.Txt LIKE N'%chậm%' OR x.Txt LIKE N'%trễ%' OR x.Txt LIKE N'%lâu%'
                     THEN N'Giao hàng chậm'
                WHEN x.Txt LIKE N'%đổi ý%' OR x.Txt LIKE N'%không cần%' OR x.Txt LIKE N'%không thích%' OR x.Txt LIKE N'%không vừa%'
                     THEN N'Đổi ý / không có nhu cầu'
                ELSE N'Khác'
            END
        FROM TraHang th
        CROSS APPLY (SELECT COALESCE(th.NoiDung_DaLamSach, th.LyDoTra) AS Txt) x;

        MERGE ChuDe_KhieuNai AS t
        USING (
            SELECT NhomLyDoChinh AS TenChuDe,
                   COUNT(*) AS TanSuat,
                   ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC, NhomLyDoChinh) AS UuTien
            FROM TraHang
            WHERE NhomLyDoChinh IS NOT NULL
            GROUP BY NhomLyDoChinh
        ) AS s
        ON t.TenChuDe = s.TenChuDe
        WHEN MATCHED THEN
            UPDATE SET TanSuatXuatHien = s.TanSuat, MucDoUuTien = s.UuTien, NgayCapNhat = GETDATE()
        WHEN NOT MATCHED BY TARGET THEN
            INSERT (TenChuDe, TanSuatXuatHien, MucDoUuTien, NgayCapNhat)
            VALUES (s.TenChuDe, s.TanSuat, s.UuTien, GETDATE())
        WHEN NOT MATCHED BY SOURCE THEN
            DELETE;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH


    IF @HienKetQua = 1
    SELECT TenChuDe, TanSuatXuatHien, MucDoUuTien, NgayCapNhat
    FROM ChuDe_KhieuNai
    ORDER BY MucDoUuTien;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_DanhGiaUyTinNhaCungCap;
GO
CREATE PROCEDURE dbo.sp_DanhGiaUyTinNhaCungCap
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH SPvaNCC AS (
        SELECT MaSP, MaNCC FROM vw_SanPham_NCCGanNhat WHERE MaNCC IS NOT NULL
    ),
    Nhap AS (
        SELECT pn.MaNCC, COUNT(DISTINCT pn.MaPN) AS SoPhieuNhap, SUM(ctn.SoLuong) AS TongSLNhap
        FROM PhieuNhap pn
        LEFT JOIN ChiTietPhieuNhap ctn ON ctn.MaPN = pn.MaPN
        GROUP BY pn.MaNCC
    ),
    Xuat AS (
        SELECT s.MaNCC, SUM(ctx.SoLuong) AS TongSLXuat
        FROM ChiTietPhieuXuat ctx
        JOIN SPvaNCC s ON s.MaSP = ctx.MaSP
        GROUP BY s.MaNCC
    ),
    Tra AS (
        SELECT s.MaNCC, SUM(th.SoLuong) AS TongSLTra
        FROM TraHang th
        JOIN SPvaNCC s ON s.MaSP = th.MaSP
        GROUP BY s.MaNCC
    ),
    HangVe AS (
        SELECT MaNCC, AVG(CAST(DATEDIFF(DAY, NgayDatHang, NgayNhap) AS FLOAT)) AS SoNgayHangVe_TB
        FROM PhieuNhap
        WHERE NgayDatHang IS NOT NULL
        GROUP BY MaNCC
    ),
    Tong AS (
        SELECT ncc.MaNCC, ncc.TenNCC,
               ISNULL(n.SoPhieuNhap, 0) AS SoPhieuNhap,
               ISNULL(n.TongSLNhap, 0) AS TongSLNhap,
               ISNULL(x.TongSLXuat, 0) AS TongSLXuat,
               ISNULL(t.TongSLTra, 0) AS TongSLTra,
               hv.SoNgayHangVe_TB
        FROM NhaCungCap ncc
        LEFT JOIN HangVe hv ON hv.MaNCC = ncc.MaNCC
        LEFT JOIN Nhap n ON n.MaNCC = ncc.MaNCC
        LEFT JOIN Xuat x ON x.MaNCC = ncc.MaNCC
        LEFT JOIN Tra  t ON t.MaNCC = ncc.MaNCC
    )
    SELECT MaNCC, TenNCC, SoPhieuNhap, TongSLNhap, TongSLXuat, TongSLTra,
           CAST(ROUND(SoNgayHangVe_TB, 1) AS DECIMAL(6,1)) AS SoNgayHangVe_TB,
           CASE WHEN TongSLXuat = 0 THEN NULL
                ELSE CAST(100.0 * TongSLTra / TongSLXuat AS DECIMAL(9,2)) END AS TyLeTra_PhanTram,
           CASE WHEN TongSLXuat = 0 THEN NULL
                ELSE CAST(100.0 - CASE WHEN 100.0 * TongSLTra / TongSLXuat > 100 THEN 100.0
                                       ELSE 100.0 * TongSLTra / TongSLXuat END AS DECIMAL(9,2)) END AS DiemUyTin
    FROM Tong
    ORDER BY DiemUyTin DESC, MaNCC;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_UocLuongNguyCoRoiBo;
GO
CREATE PROCEDURE dbo.sp_UocLuongNguyCoRoiBo
    @NgayTinh DATE = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET @NgayTinh = ISNULL(@NgayTinh, dbo.fn_NgayDuLieuMoiNhat());

    ;WITH G AS (
        SELECT MaKH, COUNT(*) AS SoDon, MIN(CAST(NgayDat AS DATE)) AS Dau, MAX(CAST(NgayDat AS DATE)) AS Cuoi
        FROM DonHang
        WHERE MaKH IS NOT NULL AND ISNULL(TrangThai, N'') NOT LIKE N'%hủy%'
        GROUP BY MaKH
    ),
    T AS (
        SELECT MaKH, Cuoi,
               CASE WHEN DATEDIFF(DAY, Dau, Cuoi) * 1.0 / NULLIF(SoDon - 1, 0) < 1 THEN 1.0
                    ELSE DATEDIFF(DAY, Dau, Cuoi) * 1.0 / NULLIF(SoDon - 1, 0) END AS ChuKy
        FROM G
        WHERE SoDon >= 2
    )
    UPDATE kh
    SET XacSuatRoiBo = CASE WHEN t.MaKH IS NULL THEN NULL
                            WHEN x.Ngay / t.ChuKy / 3.0 > 1 THEN 1.0
                            ELSE CAST(x.Ngay / t.ChuKy / 3.0 AS DECIMAL(5,4)) END
    FROM KhachHang kh
    LEFT JOIN T t ON t.MaKH = kh.MaKH
    OUTER APPLY (SELECT CASE WHEN t.Cuoi IS NULL OR DATEDIFF(DAY, t.Cuoi, @NgayTinh) < 0 THEN 0
                             ELSE DATEDIFF(DAY, t.Cuoi, @NgayTinh) END AS Ngay) x;

    SELECT MaKH, TenKH, XacSuatRoiBo FROM KhachHang ORDER BY XacSuatRoiBo DESC, MaKH;
END;
GO

