CREATE TABLE DanhGiaSanPham (
    MaDanhGia VARCHAR(20) PRIMARY KEY,
    MaSP VARCHAR(50) NOT NULL FOREIGN KEY REFERENCES SanPham(MaSP),
    MaDH VARCHAR(20) NOT NULL FOREIGN KEY REFERENCES DonHang(MaDH),
    MaKH VARCHAR(20) NULL FOREIGN KEY REFERENCES KhachHang(MaKH),
    SoSao INT NOT NULL CHECK (SoSao BETWEEN 1 AND 5),
    NoiDung NVARCHAR(1000) NULL,
    NgayDanhGia DATETIME NOT NULL DEFAULT GETDATE(),
    CONSTRAINT UQ_DanhGia_DonSP UNIQUE (MaDH, MaSP)
);

