;WITH Lich AS (
    SELECT CAST('20251001' AS DATE) AS Ngay
    UNION ALL
    SELECT DATEADD(DAY, 1, Ngay) FROM Lich WHERE Ngay < '20260930'
),
Ban AS (
    SELECT CAST(dh.NgayDat AS DATE) AS Ngay,
           COUNT(DISTINCT dh.MaDH) AS SoDon,
           SUM(ct.SoLuong) AS SoLuong,
           SUM(ct.ThanhTien) AS DoanhThu
    FROM DonHang dh
    JOIN ChiTietDonHang ct ON ct.MaDH = dh.MaDH
    WHERE ISNULL(dh.TrangThai, N'') NOT LIKE N'%hủy%'
    GROUP BY CAST(dh.NgayDat AS DATE)
)
SELECT l.Ngay,
       ISNULL(b.SoDon, 0),
       ISNULL(b.SoLuong, 0),
       ISNULL(b.DoanhThu, 0),
       CASE WHEN ds.MaDot IS NULL THEN 0 ELSE 1 END,
       ds.TenDot,
       CASE WHEN nl.Ngay IS NULL THEN 0 ELSE 1 END,
       CASE WHEN DATEDIFF(DAY, '19000101', l.Ngay) % 7 >= 5 THEN 1 ELSE 0 END,
       LAG(ISNULL(b.SoDon, 0), 7) OVER (ORDER BY l.Ngay),
       CAST(AVG(CAST(ISNULL(b.SoDon, 0) AS DECIMAL(10,2))) OVER (ORDER BY l.Ngay ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS DECIMAL(10,2))
FROM Lich l
LEFT JOIN Ban b ON b.Ngay = l.Ngay
LEFT JOIN DotSale ds ON l.Ngay BETWEEN ds.NgayBatDau AND ds.NgayKetThuc
LEFT JOIN NgayLe nl ON nl.Ngay = l.Ngay
OPTION (MAXRECURSION 400);
GO

