CREATE OR ALTER FUNCTION fn_SoVN (@x FLOAT, @soLe INT)
RETURNS NVARCHAR(30)
AS
BEGIN
    DECLARE @kq NVARCHAR(30);
    IF @x IS NULL
        SET @kq = N'';
    ELSE IF @soLe = 0
        SET @kq = CAST(CAST(ROUND(@x, 0) AS DECIMAL(18, 0)) AS NVARCHAR(30));
    ELSE
        SET @kq = REPLACE(CAST(CAST(ROUND(@x, 1) AS DECIMAL(18, 1)) AS NVARCHAR(30)), '.', ',');
    RETURN @kq;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_PhanTichCamXuc_DanhGia;
GO
CREATE PROCEDURE dbo.sp_PhanTichCamXuc_DanhGia
    @HienKetQua BIT = 1
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF OBJECT_ID('tempdb..#Chu') IS NOT NULL DROP TABLE #Chu;
    CREATE TABLE #Chu (
        Loai NVARCHAR(10) NOT NULL,
        MaDoiTuong VARCHAR(50) NOT NULL,
        Goc NVARCHAR(MAX) NULL,
        Txt NVARCHAR(MAX) NULL
    );

    SELECT N'Đánh giá', MaDanhGia, NoiDung, NoiDung FROM DanhGiaSanPham
    UNION ALL
    SELECT N'Trả hàng', MaTraHang, LyDoTra, LyDoTra FROM TraHang;

    UPDATE #Chu
    SET Txt = N' ' + dbo.fn_LamSachKyTu(
                  REPLACE(REPLACE(REPLACE(REPLACE(LOWER(ISNULL(Txt, N'')), N',', N' '), N'.', N' '), N'-', N' '), N'/', N' ')
              ) + N' ';

    DECLARE @Goc NVARCHAR(100), @Chuan NVARCHAR(100), @Lan INT = 1;
    DECLARE cur_Teen CURSOR LOCAL FAST_FORWARD FOR
        SELECT TuGoc, TuChuanHoa FROM TuDien_Teencode ORDER BY LEN(TuGoc) DESC, Id;
    WHILE @Lan <= 2
    BEGIN
        OPEN cur_Teen;
        FETCH NEXT FROM cur_Teen INTO @Goc, @Chuan;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            UPDATE #Chu SET Txt = REPLACE(Txt, N' ' + LOWER(@Goc) + N' ', N' ' + @Chuan + N' ');
            FETCH NEXT FROM cur_Teen INTO @Goc, @Chuan;
        END
        CLOSE cur_Teen;
        SET @Lan = @Lan + 1;
    END
    DEALLOCATE cur_Teen;

    BEGIN TRANSACTION;
    BEGIN TRY
        DELETE FROM PhanTich_CamXuc_DanhGia WHERE GanTay = 0;

        ;WITH Van AS (
            SELECT c.Loai, c.MaDoiTuong, c.Goc, c.Txt FROM #Chu c
            WHERE NOT EXISTS (SELECT 1 FROM PhanTich_CamXuc_DanhGia m
                              WHERE m.GanTay = 1 AND m.LoaiDoiTuong = c.Loai AND m.DoiTuongId = c.MaDoiTuong)
        ),
        Khop AS (
            SELECT v.Loai, v.MaDoiTuong,
                   CASE WHEN v.Txt LIKE CONCAT(N'% không ', d.TuKhoa, N' %')
                          OR v.Txt LIKE CONCAT(N'% chưa ',  d.TuKhoa, N' %')
                          OR v.Txt LIKE CONCAT(N'% chẳng ', d.TuKhoa, N' %')
                        THEN -d.Diem ELSE d.Diem END AS Diem
            FROM Van v
            JOIN TuDien_CamXuc d ON v.Txt LIKE CONCAT(N'% ', d.TuKhoa, N' %')
        ),
        Gom AS (
            SELECT Loai, MaDoiTuong,
                   SUM(CASE WHEN Diem > 0 THEN 1 ELSE 0 END) AS Khen,
                   SUM(CASE WHEN Diem < 0 THEN 1 ELSE 0 END) AS Che
            FROM Khop
            GROUP BY Loai, MaDoiTuong
        )
        SELECT v.MaDoiTuong, v.Loai,
               CAST(CASE WHEN ISNULL(g.Khen, 0) + ISNULL(g.Che, 0) = 0 THEN 0
                         ELSE 1.0 * (g.Khen - g.Che) / (g.Khen + g.Che) END AS DECIMAL(6, 4)),
               CASE WHEN ISNULL(g.Khen, 0) > ISNULL(g.Che, 0) THEN N'Khen'
                    WHEN ISNULL(g.Che, 0) > ISNULL(g.Khen, 0) THEN N'Chê'
                    ELSE N'Trung tính' END,
               v.Goc, 0
        FROM Van v
        LEFT JOIN Gom g ON g.Loai = v.Loai AND g.MaDoiTuong = v.MaDoiTuong;

        UPDATE th
        SET th.CamXucKhachHang = p.NhomCamXuc
        FROM TraHang th
        JOIN PhanTich_CamXuc_DanhGia p ON p.LoaiDoiTuong = N'Trả hàng' AND p.DoiTuongId = th.MaTraHang;

        UPDATE sp
        SET sp.DiemCamXuc_CSAT = x.CSAT
        FROM SanPham sp
        LEFT JOIN (
            SELECT MaSP, CAST(100.0 * SUM(CASE WHEN SoSao >= 4 THEN 1 ELSE 0 END) / COUNT(*) AS DECIMAL(5, 2)) AS CSAT
            FROM DanhGiaSanPham GROUP BY MaSP
        ) x ON x.MaSP = sp.MaSP;

        SELECT N'Đọc cảm xúc đánh giá và trả hàng', COUNT(*), 0, GETDATE() FROM PhanTich_CamXuc_DanhGia;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH


    IF @HienKetQua = 1
    SELECT LoaiDoiTuong, NhomCamXuc, COUNT(*) AS SoLuong
    FROM PhanTich_CamXuc_DanhGia
    GROUP BY LoaiDoiTuong, NhomCamXuc
    ORDER BY LoaiDoiTuong, NhomCamXuc;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_BangThongBao_CamXuc;
GO
CREATE PROCEDURE dbo.sp_BangThongBao_CamXuc
    @CsatDo DECIMAL(5, 2) = 60,
    @CsatVang DECIMAL(5, 2) = 80,
    @MinDanhGia INT = 10
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (SELECT 1 FROM TraHang WHERE NhomLyDoChinh IS NULL)
       OR (EXISTS (SELECT 1 FROM DanhGiaSanPham) AND NOT EXISTS (SELECT 1 FROM PhanTich_CamXuc_DanhGia))
    BEGIN
        RAISERROR(N'Chưa chạy đủ các bước trước. Chạy lần lượt: EXEC sp_TuDongLamSach_DuLieuGiaoDich; EXEC sp_PhanTichChuDeKhieuNai; EXEC sp_PhanTichCamXuc_DanhGia; rồi mới chạy lại thủ tục này.', 16, 1);
        RETURN;
    END

    ;WITH DG AS (
        SELECT dg.MaSP,
               COUNT(*) AS SoDanhGia,
               AVG(CAST(dg.SoSao AS FLOAT)) AS SaoTB,
               SUM(CASE WHEN dg.SoSao >= 4 THEN 1 ELSE 0 END) AS SoTot,
               SUM(CASE WHEN p.NhomCamXuc = N'Chê' THEN 1 ELSE 0 END) AS SoChe
        FROM DanhGiaSanPham dg
        LEFT JOIN PhanTich_CamXuc_DanhGia p ON p.LoaiDoiTuong = N'Đánh giá' AND p.DoiTuongId = dg.MaDanhGia
        GROUP BY dg.MaSP
    ),
    Xuat AS (
        SELECT x.MaSP, x.SL - ISNULL(h.SL, 0) AS SLXuat
        FROM (SELECT MaSP, SUM(SoLuong) AS SL FROM ChiTietPhieuXuat GROUP BY MaSP) x
        LEFT JOIN (SELECT MaSP, SUM(SoLuong) AS SL FROM HangHoanVeKho GROUP BY MaSP) h ON h.MaSP = x.MaSP
    ),
    Tra AS (SELECT MaSP, SUM(SoLuong) AS SLTra FROM TraHang GROUP BY MaSP),
    TopLyDo AS (
        SELECT MaSP, NhomLyDoChinh,
               ROW_NUMBER() OVER (PARTITION BY MaSP ORDER BY COUNT(*) DESC, MIN(MaTraHang)) AS Hang
        FROM TraHang
        GROUP BY MaSP, NhomLyDoChinh
    ),
    Goc AS (
        SELECT sp.MaSP, sp.TenSP, sp.MaDanhMuc, dm.TenDanhMuc,
               ISNULL(d.SoDanhGia, 0) AS SoDanhGia, d.SaoTB, ISNULL(d.SoTot, 0) AS SoTot, ISNULL(d.SoChe, 0) AS SoChe,
               ISNULL(x.SLXuat, 0) AS SLXuat, ISNULL(t.SLTra, 0) AS SLTra, l.NhomLyDoChinh AS LyDoTraNhieuNhat
        FROM SanPham sp
        LEFT JOIN DanhMuc dm ON dm.MaDanhMuc = sp.MaDanhMuc
        LEFT JOIN DG d ON d.MaSP = sp.MaSP
        LEFT JOIN Xuat x ON x.MaSP = sp.MaSP
        LEFT JOIN Tra t ON t.MaSP = sp.MaSP
        LEFT JOIN TopLyDo l ON l.MaSP = sp.MaSP AND l.Hang = 1
    ),
    Tinh AS (
        SELECT *,
               CASE WHEN SoDanhGia = 0 THEN NULL ELSE 100.0 * SoTot / SoDanhGia END AS CSAT,
               CASE WHEN SoDanhGia = 0 THEN NULL ELSE 100.0 * SoChe / SoDanhGia END AS TyLeChuChe,
               CASE WHEN SLXuat = 0 THEN NULL ELSE 100.0 * SLTra / SLXuat END AS TyLeTra,
               100.0 * SUM(SoTot) OVER (PARTITION BY MaDanhMuc) / NULLIF(SUM(SoDanhGia) OVER (PARTITION BY MaDanhMuc), 0) AS CSAT_DanhMuc
        FROM Goc
    ),
    Tt AS (
        SELECT *,
               CASE WHEN SoDanhGia = 0 THEN N'CHƯA CÓ ĐÁNH GIÁ'
                    WHEN CSAT < @CsatDo THEN N'ĐỎ'
                    WHEN CSAT < @CsatVang THEN N'VÀNG'
                    ELSE N'XANH' END AS TrangThai
        FROM Tinh
    )
    SELECT MaSP, TenSP, MaDanhMuc, TenDanhMuc, SoDanhGia, SaoTB, CSAT, TyLeChuChe, SLXuat, SLTra, TyLeTra,
           LyDoTraNhieuNhat, CSAT_DanhMuc, TrangThai,
           CASE WHEN SoDanhGia = 0 THEN N'Chưa có đánh giá nào để đọc cảm xúc.'
                ELSE CONCAT(
                    CASE TrangThai WHEN N'ĐỎ' THEN N'Khách đang KHÔNG hài lòng'
                                   WHEN N'VÀNG' THEN N'Khách tạm hài lòng, cần theo dõi'
                                   ELSE N'Khách hài lòng' END,
                    N': ', dbo.fn_SoVN(CSAT, 0), N'% đánh giá từ 4 sao trở lên, trung bình ', dbo.fn_SoVN(SaoTB, 1),
                    N' sao (', SoDanhGia, N' đánh giá). Lời chê chiếm ', dbo.fn_SoVN(TyLeChuChe, 0), N'%.',
                    CASE WHEN TyLeTra IS NULL THEN N''
                         ELSE CONCAT(N' Trả hàng ', dbo.fn_SoVN(TyLeTra, 1), N'%',
                                     CASE WHEN LyDoTraNhieuNhat IS NULL THEN N'.'
                                          ELSE CONCAT(N', lý do nhiều nhất: ', LyDoTraNhieuNhat, N'.') END) END,
                    CASE WHEN SoDanhGia < @MinDanhGia
                         THEN CONCAT(N' (Mới ', SoDanhGia, N' đánh giá, ít quá nên chưa đáng tin.)') ELSE N'' END
                ) END AS ThongBao
    FROM Tt
    ORDER BY CSAT, MaSP;

    SELECT dm.MaDanhMuc, dm.TenDanhMuc,
           COUNT(*) AS SoDanhGia,
           AVG(CAST(dg.SoSao AS FLOAT)) AS SaoTB,
           100.0 * SUM(CASE WHEN dg.SoSao >= 4 THEN 1 ELSE 0 END) / COUNT(*) AS CSAT
    FROM DanhMuc dm
    JOIN SanPham sp ON sp.MaDanhMuc = dm.MaDanhMuc
    JOIN DanhGiaSanPham dg ON dg.MaSP = sp.MaSP
    GROUP BY dm.MaDanhMuc, dm.TenDanhMuc
    ORDER BY CSAT;
END;
GO

CREATE OR ALTER FUNCTION dbo.fn_DuBaoBanHang
(
    @DenNgay DATE,
    @SoNgayPhanTich INT,
    @SoNgayGan INT,
    @HeSoZ FLOAT,
    @LeadTimeMacDinh FLOAT,
    @NgayTonNhieu INT,
    @ThayDoiPhanTram FLOAT,
    @MinSoBan INT
)
RETURNS TABLE
AS
RETURN
(
    WITH Moc AS (
        SELECT ISNULL(@DenNgay, (SELECT CAST(MAX(NgayXuat) AS DATE) FROM PhieuXuat)) AS DenNgay
    ),
    Khoang AS (
        SELECT DenNgay,
               DATEADD(DAY, -(@SoNgayPhanTich - 1), DenNgay) AS Tu,
               DATEADD(DAY, -(@SoNgayGan - 1), DenNgay) AS TuGan
        FROM Moc
    ),
    BanNgay AS (
        SELECT ctx.MaSP, CAST(px.NgayXuat AS DATE) AS Ngay, SUM(ctx.SoLuong) AS SL
        FROM ChiTietPhieuXuat ctx
        JOIN PhieuXuat px ON px.MaPX = ctx.MaPX
        CROSS JOIN Khoang k
        WHERE px.NgayXuat >= k.Tu AND px.NgayXuat < DATEADD(DAY, 1, k.DenNgay)
        GROUP BY ctx.MaSP, CAST(px.NgayXuat AS DATE)
    ),
    TongHop AS (
        SELECT b.MaSP,
               CAST(SUM(b.SL) AS FLOAT) AS Tong,
               CAST(SUM(CAST(b.SL AS FLOAT) * b.SL) AS FLOAT) AS Binh,
               CAST(SUM(CASE WHEN b.Ngay >= k.TuGan THEN b.SL ELSE 0 END) AS FLOAT) AS TongGan
        FROM BanNgay b
        CROSS JOIN Khoang k
        GROUP BY b.MaSP
    ),
    LeadNCC AS (
        SELECT pn.MaNCC,
               AVG(CAST(DATEDIFF(DAY, pn.NgayDatHang, pn.NgayNhap) AS FLOAT)) AS LT_TB,
               ISNULL(STDEV(CAST(DATEDIFF(DAY, pn.NgayDatHang, pn.NgayNhap) AS FLOAT)), 0) AS LT_Lech
        FROM PhieuNhap pn
        CROSS JOIN Khoang k
        WHERE pn.NgayDatHang IS NOT NULL AND pn.NgayNhap < DATEADD(DAY, 1, k.DenNgay)
        GROUP BY pn.MaNCC
    ),
    Ton AS (
        SELECT MaSP, SUM(SoLuongTon) AS TonHienTai FROM TonKho GROUP BY MaSP
    ),
    DonCoMon AS (
        SELECT DISTINCT MaDH, MaSP FROM ChiTietDonHang
    ),
    MuaChung AS (
        SELECT a.MaSP, c.MaSP AS MaSPKem, COUNT(*) AS SoDon,
               ROW_NUMBER() OVER (PARTITION BY a.MaSP ORDER BY COUNT(*) DESC, c.MaSP) AS Hang
        FROM DonCoMon a
        JOIN DonCoMon c ON c.MaDH = a.MaDH AND c.MaSP <> a.MaSP
        GROUP BY a.MaSP, c.MaSP
    ),
    Tinh AS (
        SELECT sp.MaSP, sp.TenSP, n.MaNCC, ncc.TenNCC, k.DenNgay,
               ISNULL(t.TonHienTai, 0) AS TonHienTai,
               ISNULL(h.Tong, 0) AS Tong,
               ISNULL(h.Tong, 0) / @SoNgayPhanTich AS ADS,
               ISNULL(h.TongGan, 0) / @SoNgayGan AS ADS30,
               CASE WHEN h.Tong IS NULL THEN 0
                    WHEN (h.Binh - h.Tong * h.Tong / @SoNgayPhanTich) < 0 THEN 0
                    ELSE SQRT((h.Binh - h.Tong * h.Tong / @SoNgayPhanTich) / (@SoNgayPhanTich - 1)) END AS DoLechNgay,
               ISNULL(l.LT_TB, @LeadTimeMacDinh) AS LeadTime,
               ISNULL(l.LT_Lech, 0) AS LT_Lech,
               CASE WHEN l.LT_TB IS NULL THEN 1 ELSE 0 END AS LeadTimeUoc,
               spk.TenSP AS MonHayMuaChung,
               mc.SoDon AS SoDonMuaChung
        FROM SanPham sp
        CROSS JOIN Khoang k
        LEFT JOIN vw_SanPham_NCCGanNhat n ON n.MaSP = sp.MaSP
        LEFT JOIN NhaCungCap ncc ON ncc.MaNCC = n.MaNCC
        LEFT JOIN LeadNCC l ON l.MaNCC = n.MaNCC
        LEFT JOIN TongHop h ON h.MaSP = sp.MaSP
        LEFT JOIN Ton t ON t.MaSP = sp.MaSP
        LEFT JOIN MuaChung mc ON mc.MaSP = sp.MaSP AND mc.Hang = 1
        LEFT JOIN SanPham spk ON spk.MaSP = mc.MaSPKem
    ),
    Tinh2 AS (
        SELECT *,
               CAST(CEILING(@HeSoZ * SQRT(LeadTime * DoLechNgay * DoLechNgay + ADS * ADS * LT_Lech * LT_Lech)) AS INT) AS TonAnToan,
               CASE WHEN Tong >= @MinSoBan AND ADS30 > ADS THEN ADS30 ELSE ADS END AS TocDoDuDoan
        FROM Tinh
    ),
    Tinh3 AS (
        SELECT *,
               CAST(CEILING(ADS * LeadTime) AS INT) + TonAnToan AS ROP,
               CASE WHEN ADS > 0 THEN ROUND(TonHienTai / ADS, 1) END AS SoNgayConLai,
               CASE WHEN ADS > 0 AND Tong >= @MinSoBan THEN ROUND(100.0 * (ADS30 / ADS - 1), 1) END AS XuHuongPT,
               CAST(ROUND(TocDoDuDoan * 30, 0) AS INT) AS DuDoan30Ngay
        FROM Tinh2
    ),
    Tinh4 AS (
        SELECT *,
               CASE WHEN ADS = 0 THEN N'Không có bán'
                    WHEN Tong < @MinSoBan THEN N'Bán ít, chưa đủ số liệu'
                    WHEN XuHuongPT >= @ThayDoiPhanTram THEN N'ĐANG HOT - bán nhanh lên'
                    WHEN XuHuongPT <= -@ThayDoiPhanTram THEN N'ĐANG NGUỘI - bán chậm lại'
                    ELSE N'Bán đều' END AS Cau,
               CASE WHEN ADS = 0 THEN N'KHÔNG BÁN'
                    WHEN TonHienTai < ADS * LeadTime THEN N'KHẨN CẤP'
                    WHEN TonHienTai <= ROP THEN N'ĐẶT HÀNG NGAY'
                    WHEN SoNgayConLai > @NgayTonNhieu THEN N'TỒN NHIỀU'
                    ELSE N'ỔN' END AS TrangThai
        FROM Tinh3
    ),
    Tinh5 AS (
        SELECT *,
               CASE WHEN TrangThai IN (N'KHẨN CẤP', N'ĐẶT HÀNG NGAY')
                         AND CAST(CEILING(TocDoDuDoan * (LeadTime + 30)) AS INT) + TonAnToan - TonHienTai > 0
                    THEN CAST(CEILING(TocDoDuDoan * (LeadTime + 30)) AS INT) + TonAnToan - TonHienTai
                    ELSE 0 END AS SoNenNhap
        FROM Tinh4
    )
    SELECT MaSP, TenSP, MaNCC, TenNCC, DenNgay, TonHienTai, Tong, ADS, ADS30, DoLechNgay, LeadTime, LT_Lech, LeadTimeUoc,
           TonAnToan, ROP, SoNgayConLai, XuHuongPT, TocDoDuDoan, DuDoan30Ngay, SoNenNhap, MonHayMuaChung, SoDonMuaChung,
           Cau, TrangThai,
           CASE WHEN TrangThai = N'KHÔNG BÁN'
                THEN CONCAT(N'Không bán được cái nào trong ', @SoNgayPhanTich, N' ngày qua. Tồn ', TonHienTai, N' cái.')
                ELSE CONCAT(
                    N'Bán TB ', dbo.fn_SoVN(ADS, 1), N' cái/ngày (', LOWER(Cau), N'), hàng về mất TB ', dbo.fn_SoVN(LeadTime, 1), N' ngày',
                    CASE WHEN LeadTimeUoc = 1 THEN N' (chưa có dữ liệu thật, đang tạm tính)' ELSE N'' END,
                    N'. Tồn ', TonHienTai, N' cái, đủ bán ~', dbo.fn_SoVN(SoNgayConLai, 1), N' ngày; mức phải đặt hàng là ', ROP, N' cái. ',
                    CASE TrangThai
                         WHEN N'KHẨN CẤP' THEN N'KHẨN CẤP: tồn không đủ bán trong lúc chờ hàng về, đặt ngay.'
                         WHEN N'ĐẶT HÀNG NGAY' THEN N'Tồn đã chạm mức phải đặt hàng, cần đặt ngay.'
                         WHEN N'TỒN NHIỀU' THEN CONCAT(N'Tồn đủ bán hơn ', @NgayTonNhieu, N' ngày, chưa cần nhập thêm.')
                         ELSE N'Còn đủ hàng, chưa cần đặt.' END
                ) END AS ThongBao,
           CASE WHEN TrangThai = N'KHÔNG BÁN' AND TonHienTai > 0
                THEN CONCAT(N'Không bán được cái nào trong ', @SoNgayPhanTich, N' ngày qua mà còn tồn ', TonHienTai,
                            N' cái: xả hàng (giảm giá, tặng kèm',
                            CASE WHEN MonHayMuaChung IS NULL THEN N'' ELSE CONCAT(N', ghép với "', MonHayMuaChung, N'"') END, N').')
                WHEN TrangThai = N'KHÔNG BÁN' THEN N'Không bán, không còn tồn: chưa cần làm gì.'
                WHEN TrangThai = N'KHẨN CẤP'
                THEN CONCAT(N'Đặt NGAY ', SoNenNhap, N' cái: tồn chỉ đủ bán ', dbo.fn_SoVN(SoNgayConLai, 1),
                            N' ngày mà hàng về mất ', dbo.fn_SoVN(LeadTime, 1), N' ngày.',
                            CASE WHEN Cau = N'ĐANG HOT - bán nhanh lên' THEN N' Món đang hot nên số đặt đã tính theo tốc độ bán 30 ngày gần nhất.' ELSE N'' END)
                WHEN TrangThai = N'ĐẶT HÀNG NGAY'
                THEN CONCAT(N'Đặt ', SoNenNhap, N' cái trong tuần này để đủ bán 30 ngày sau khi hàng về.',
                            CASE WHEN Cau = N'ĐANG HOT - bán nhanh lên' THEN N' Món đang hot nên số đặt đã tính theo tốc độ bán 30 ngày gần nhất.' ELSE N'' END)
                WHEN TrangThai = N'TỒN NHIỀU'
                THEN CONCAT(N'Tồn đủ bán ', dbo.fn_SoVN(SoNgayConLai, 1), N' ngày: chưa nhập thêm',
                            CASE WHEN MonHayMuaChung IS NULL THEN N'' ELSE CONCAT(N', làm combo với "', MonHayMuaChung, N'" để bán nhanh hơn') END, N'.')
                WHEN Cau = N'ĐANG HOT - bán nhanh lên'
                THEN CONCAT(N'Đang hot: đăng bài, chạy quảng cáo ngay và xem tồn kho mỗi ngày',
                            CASE WHEN MonHayMuaChung IS NULL THEN N'' ELSE CONCAT(N'; gợi ý khách mua kèm "', MonHayMuaChung, N'"') END, N'.')
                WHEN Cau = N'ĐANG NGUỘI - bán chậm lại' THEN N'Đang bán chậm lại: xem lại giá, ảnh, đánh giá xấu gần đây.'
                ELSE N'Ổn, giữ như hiện tại.' END AS ViecNenLam
    FROM Tinh5
);
GO

CREATE OR ALTER VIEW dbo.vw_DuBaoSanPham
AS
SELECT * FROM dbo.fn_DuBaoBanHang(NULL, 90, 30, 1.65, 7, 60, 20, 30);
GO

CREATE OR ALTER VIEW dbo.vw_CungCau
AS
WITH Moc AS (
    SELECT CAST(MAX(NgayXuat) AS DATE) AS DenNgay FROM PhieuXuat
),
DonHopLe AS (
    SELECT ct.MaSP, ct.SoLuong, ct.DonGia, dh.NgayDat,
           CASE WHEN EXISTS (SELECT 1 FROM DotSale ds WHERE CAST(dh.NgayDat AS DATE) BETWEEN ds.NgayBatDau AND ds.NgayKetThuc)
                THEN 1 ELSE 0 END AS LaNgaySale
    FROM ChiTietDonHang ct
    JOIN DonHang dh ON dh.MaDH = ct.MaDH
    WHERE ISNULL(dh.TrangThai, N'') NOT LIKE N'%hủy%'
),
Ban AS (
    SELECT d.MaSP,
           SUM(CASE WHEN d.NgayDat >= DATEADD(DAY, -29, m.DenNgay) AND d.NgayDat < DATEADD(DAY, 1, m.DenNgay) THEN d.SoLuong ELSE 0 END) AS SL30,
           SUM(CASE WHEN d.NgayDat >= DATEADD(DAY, -29, m.DenNgay) AND d.NgayDat < DATEADD(DAY, 1, m.DenNgay) THEN d.SoLuong * d.DonGia ELSE 0 END) AS Tien30,
           SUM(CASE WHEN d.NgayDat >= DATEADD(DAY, -89, m.DenNgay) AND d.NgayDat < DATEADD(DAY, -29, m.DenNgay) THEN d.SoLuong ELSE 0 END) AS SLTruoc,
           SUM(CASE WHEN d.NgayDat >= DATEADD(DAY, -89, m.DenNgay) AND d.NgayDat < DATEADD(DAY, -29, m.DenNgay) THEN d.SoLuong * d.DonGia ELSE 0 END) AS TienTruoc,
           SUM(CASE WHEN d.LaNgaySale = 1 THEN d.SoLuong ELSE 0 END) AS SLSale,
           SUM(CASE WHEN d.LaNgaySale = 1 THEN d.SoLuong * d.DonGia ELSE 0 END) AS TienSale,
           SUM(CASE WHEN d.LaNgaySale = 0 THEN d.SoLuong ELSE 0 END) AS SLThuong,
           SUM(CASE WHEN d.LaNgaySale = 0 THEN d.SoLuong * d.DonGia ELSE 0 END) AS TienThuong
    FROM DonHopLe d
    CROSS JOIN Moc m
    GROUP BY d.MaSP
),
GiaNhap AS (
    SELECT MaSP, SUM(SoLuong * DonGia) / NULLIF(SUM(SoLuong), 0) AS GiaNhapTB
    FROM ChiTietPhieuNhap
    GROUP BY MaSP
),
Gom AS (
    SELECT v.MaSP, v.TenSP, v.TonHienTai, v.ADS, v.ADS30, v.XuHuongPT, v.Cau, v.SoNgayConLai, v.LeadTime, v.TrangThai,
           v.DuDoan30Ngay, v.SoNenNhap, v.MonHayMuaChung, sp.GiaBan, gn.GiaNhapTB,
           CASE WHEN b.SL30 > 0 THEN b.Tien30 / b.SL30 END AS GiaThucBan30,
           CASE WHEN b.SLTruoc > 0 THEN b.TienTruoc / b.SLTruoc END AS GiaThucBanTruoc,
           CASE WHEN b.SLSale > 0 THEN b.TienSale / b.SLSale END AS GiaTBNgaySale,
           CASE WHEN b.SLThuong > 0 THEN b.TienThuong / b.SLThuong END AS GiaTBNgayThuong
    FROM vw_DuBaoSanPham v
    JOIN SanPham sp ON sp.MaSP = v.MaSP
    LEFT JOIN Ban b ON b.MaSP = v.MaSP
    LEFT JOIN GiaNhap gn ON gn.MaSP = v.MaSP
),
Nhan AS (
    SELECT *,
           CASE WHEN GiaThucBan30 IS NOT NULL AND GiaThucBanTruoc > 0
                THEN ROUND(100.0 * (GiaThucBan30 / GiaThucBanTruoc - 1), 1) END AS GiaDoiPT,
           CAST(ROUND(TonHienTai * ISNULL(GiaNhapTB, 0), 0) AS DECIMAL(18, 0)) AS TienNamTrongKho,
           GiaTBNgayThuong - GiaNhapTB AS LaiMoiCaiNgayThuong,
           GiaTBNgaySale - GiaNhapTB AS LaiMoiCaiNgaySale,
           CASE WHEN TrangThai = N'KHÔNG BÁN' THEN N'Cung > Cầu: không ai mua'
                WHEN TrangThai IN (N'KHẨN CẤP', N'ĐẶT HÀNG NGAY') THEN N'Cung < Cầu: hàng ít, khách nhiều'
                WHEN TrangThai = N'TỒN NHIỀU' OR Cau = N'ĐANG NGUỘI - bán chậm lại' THEN N'Cung > Cầu: hàng nhiều, khách ít'
                ELSE N'Cung = Cầu: cân bằng' END AS CungCau,
           CASE WHEN TrangThai = N'KHÔNG BÁN' THEN N'Hết sóng'
                WHEN Cau = N'ĐANG HOT - bán nhanh lên' THEN N'Đầu sóng: khách đang đổ vào'
                WHEN Cau = N'ĐANG NGUỘI - bán chậm lại' THEN N'Cuối sóng: khách đang bớt'
                WHEN Cau = N'Bán ít, chưa đủ số liệu' THEN N'Chưa rõ: bán còn ít'
                ELSE N'Giữa sóng: bán đều' END AS GiaiDoan,
           CASE WHEN ADS = 0 OR SoNgayConLai IS NULL THEN N'Kẹt tiền: hàng không bán ra được'
                WHEN SoNgayConLai <= 15 THEN N'Nhanh: dưới 15 ngày bán hết tồn'
                WHEN SoNgayConLai <= 45 THEN N'Vừa: 15 - 45 ngày bán hết tồn'
                ELSE N'Chậm: trên 45 ngày mới bán hết tồn' END AS ThuTienVe
    FROM Gom
),
Nhan2 AS (
    SELECT *,
           CASE WHEN GiaDoiPT IS NULL THEN N'Chưa đủ số liệu giá'
                WHEN GiaDoiPT >= 3 THEN N'Giá đang lên'
                WHEN GiaDoiPT <= -3 THEN N'Giá đang xuống'
                ELSE N'Giá đứng yên' END AS GiaXuHuong,
           CASE WHEN MonHayMuaChung IS NULL THEN N'' ELSE CONCAT(N' (combo với "', MonHayMuaChung, N'")') END AS GoiYCombo
    FROM Nhan
)
SELECT MaSP, TenSP, TonHienTai, ADS, ADS30, XuHuongPT, Cau, SoNgayConLai, LeadTime, TrangThai, DuDoan30Ngay, SoNenNhap, MonHayMuaChung,
       GiaBan, GiaNhapTB, GiaThucBan30, GiaThucBanTruoc, GiaDoiPT, GiaXuHuong, GiaTBNgayThuong, GiaTBNgaySale,
       LaiMoiCaiNgayThuong, LaiMoiCaiNgaySale, TienNamTrongKho, CungCau, GiaiDoan, ThuTienVe,
       CONCAT(
           CASE WHEN TrangThai = N'KHÔNG BÁN' AND TonHienTai > 0
                    THEN CONCAT(N'Hết sóng, không ai mua: xả hàng sớm để lấy tiền về, đừng nhập thêm. Đang kẹt ',
                                FORMAT(TienNamTrongKho, 'N0', 'vi-VN'), N' đ trong kho.')
                WHEN TrangThai = N'KHÔNG BÁN' THEN N'Không bán, không tồn: chưa cần làm gì.'
                WHEN GiaiDoan LIKE N'Đầu sóng%' AND CungCau LIKE N'Cung < Cầu%'
                    THEN CONCAT(N'Đầu sóng, hàng đang thiếu: giữ giá, chưa cần giảm giá; nhập thêm ', SoNenNhap,
                                N' cái nhưng đừng ôm quá nhiều vì sóng nào cũng qua.')
                WHEN GiaiDoan LIKE N'Đầu sóng%'
                    THEN N'Đầu sóng, khách đang đổ vào: giữ giá, đẩy quảng cáo, xem tồn kho mỗi ngày để không bị đứt hàng.'
                WHEN GiaiDoan LIKE N'Cuối sóng%' AND CungCau LIKE N'Cung > Cầu%'
                    THEN CONCAT(N'Cuối sóng, hàng nhiều khách ít: dừng nhập, xả bớt', GoiYCombo,
                                N' trước khi giá rớt sâu. Đang kẹt ', FORMAT(TienNamTrongKho, 'N0', 'vi-VN'), N' đ trong kho.')
                WHEN GiaiDoan LIKE N'Cuối sóng%' AND CungCau LIKE N'Cung < Cầu%'
                    THEN CONCAT(N'Cuối sóng nhưng hàng sắp hết: chỉ đặt ', SoNenNhap, N' cái cho đủ bán, đừng nhập dư.')
                WHEN GiaiDoan LIKE N'Cuối sóng%' THEN N'Cuối sóng, khách bớt dần: nhập ít lại, chưa cần giảm giá.'
                WHEN CungCau LIKE N'Cung < Cầu%' THEN CONCAT(N'Hàng sắp thiếu: đặt ', SoNenNhap, N' cái, giữ giá.')
                WHEN CungCau LIKE N'Cung > Cầu%' THEN CONCAT(N'Tồn nhiều so với sức bán: chưa nhập thêm', GoiYCombo, N'.')
                ELSE N'Cân bằng: lời đủ là được, nhập đều tay theo tốc độ bán.' END,
           CASE WHEN LaiMoiCaiNgaySale IS NULL OR LaiMoiCaiNgayThuong IS NULL THEN N''
                WHEN LaiMoiCaiNgaySale < 0
                    THEN CONCAT(N' Ngày sale khách đông nhưng mỗi cái đang lỗ ', FORMAT(-LaiMoiCaiNgaySale, 'N0', 'vi-VN'), N' đ: đừng giảm sâu như cũ.')
                WHEN LaiMoiCaiNgayThuong > 0 AND LaiMoiCaiNgaySale < 0.5 * LaiMoiCaiNgayThuong
                    THEN CONCAT(N' Ngày sale khách đông nhưng lãi mỗi cái chỉ còn ',
                                FORMAT(ROUND(100.0 * LaiMoiCaiNgaySale / LaiMoiCaiNgayThuong, 0), 'N0', 'vi-VN'), N'% so với ngày thường: giảm ít lại.')
                ELSE N'' END
       ) AS NenLamGi
FROM Nhan2;
GO

CREATE OR ALTER FUNCTION dbo.fn_CungCauTheoThang (@MaSP VARCHAR(50))
RETURNS TABLE
AS
RETURN
(
    WITH Thang AS (
        SELECT DISTINCT DATEFROMPARTS(YEAR(NgayDat), MONTH(NgayDat), 1) AS DauThang FROM DonHang
    ),
    Cau AS (
        SELECT DATEFROMPARTS(YEAR(dh.NgayDat), MONTH(dh.NgayDat), 1) AS DauThang,
               SUM(ct.SoLuong) AS SL, SUM(ct.SoLuong * ct.DonGia) AS Tien
        FROM ChiTietDonHang ct
        JOIN DonHang dh ON dh.MaDH = ct.MaDH
        WHERE ct.MaSP = @MaSP AND ISNULL(dh.TrangThai, N'') NOT LIKE N'%hủy%'
        GROUP BY DATEFROMPARTS(YEAR(dh.NgayDat), MONTH(dh.NgayDat), 1)
    ),
    BienDong AS (
        SELECT pn.NgayNhap AS Ngay, ctn.SoLuong AS SL, 1 AS LaNhap
        FROM ChiTietPhieuNhap ctn JOIN PhieuNhap pn ON pn.MaPN = ctn.MaPN WHERE ctn.MaSP = @MaSP
        UNION ALL
        SELECT px.NgayXuat, -ctx.SoLuong, 0
        FROM ChiTietPhieuXuat ctx JOIN PhieuXuat px ON px.MaPX = ctx.MaPX WHERE ctx.MaSP = @MaSP
        UNION ALL
        SELECT th.NgayTra, th.SoLuong, 0 FROM TraHang th WHERE th.MaSP = @MaSP AND th.TinhTrangHang = N'Còn bán được'
        UNION ALL
        SELECT h.NgayNhanVe, h.SoLuong, 0 FROM HangHoanVeKho h WHERE h.MaSP = @MaSP AND h.TrangThai = N'Đã nhận về kho'
    ),
    Gom AS (
        SELECT t.DauThang,
               ISNULL(c.SL, 0) AS Cau,
               ISNULL((SELECT SUM(b.SL) FROM BienDong b WHERE b.Ngay < t.DauThang), 0) AS TonDauThang,
               ISNULL((SELECT SUM(b.SL) FROM BienDong b
                       WHERE b.LaNhap = 1 AND b.Ngay >= t.DauThang AND b.Ngay < DATEADD(MONTH, 1, t.DauThang)), 0) AS NhapTrongThang,
               CASE WHEN c.SL > 0 THEN c.Tien / c.SL END AS GiaThucBanTB
        FROM Thang t
        LEFT JOIN Cau c ON c.DauThang = t.DauThang
    )
    SELECT DauThang, Cau, TonDauThang, NhapTrongThang, TonDauThang + NhapTrongThang AS Cung, GiaThucBanTB,
           CASE WHEN Cau > 0 THEN ROUND(1.0 * (TonDauThang + NhapTrongThang) / Cau, 1) END AS DuBanMayThang,
           CASE WHEN Cau = 0 AND TonDauThang + NhapTrongThang = 0 THEN N'Không hàng, không khách'
                WHEN Cau = 0 THEN N'Không ai mua'
                WHEN 1.0 * (TonDauThang + NhapTrongThang) / Cau < 1.5 THEN N'Hàng mỏng: đủ bán dưới 1,5 tháng'
                WHEN 1.0 * (TonDauThang + NhapTrongThang) / Cau <= 3 THEN N'Vừa đủ: đủ bán 1,5 - 3 tháng'
                ELSE N'Hàng dư: đủ bán trên 3 tháng' END AS CungCau
    FROM Gom
);
GO

DROP PROCEDURE IF EXISTS dbo.sp_BangThongBao_KhoHang;
GO
CREATE PROCEDURE dbo.sp_BangThongBao_KhoHang
    @DenNgay DATE = NULL,
    @SoNgayPhanTich INT = 90,
    @SoNgayGan INT = 30,
    @HeSoZ FLOAT = 1.65,
    @LeadTimeMacDinh FLOAT = 7,
    @NgayTonNhieu INT = 60,
    @ThayDoiPhanTram FLOAT = 20,
    @MinSoBan INT = 30,
    @HienKetQua BIT = 1
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @SoNgayPhanTich < 2 OR @SoNgayGan < 1 OR @SoNgayGan > @SoNgayPhanTich OR @HeSoZ < 0 OR @LeadTimeMacDinh < 0
    BEGIN
        RAISERROR(N'Số nhập vào không hợp lệ: số ngày xét >= 2, số ngày gần từ 1 đến số ngày xét, hệ số tồn dự phòng >= 0, số ngày hàng về >= 0.', 16, 1);
        RETURN;
    END

    IF @DenNgay IS NULL SELECT @DenNgay = CAST(MAX(NgayXuat) AS DATE) FROM PhieuXuat;
    IF @DenNgay IS NULL
    BEGIN
        RAISERROR(N'Chưa có phiếu xuất kho nào để tính tốc độ bán.', 16, 1);
        RETURN;
    END

    IF OBJECT_ID('tempdb..#KQ') IS NOT NULL DROP TABLE #KQ;
    SELECT * INTO #KQ
    FROM dbo.fn_DuBaoBanHang(@DenNgay, @SoNgayPhanTich, @SoNgayGan, @HeSoZ, @LeadTimeMacDinh, @NgayTonNhieu, @ThayDoiPhanTram, @MinSoBan);

    UPDATE sp
    SET sp.TonKhoAnToan = k.TonAnToan,
        sp.DiemDatHangLai_ROP = k.ROP,
        sp.SoNgayConLai_DuKien = CAST(k.SoNgayConLai AS DECIMAL(10, 1))
    FROM SanPham sp
    JOIN #KQ k ON k.MaSP = sp.MaSP;

    IF @HienKetQua = 0 RETURN;

    SELECT TrangThai, COUNT(*) AS SoSanPham FROM #KQ GROUP BY TrangThai
    ORDER BY CASE TrangThai WHEN N'KHẨN CẤP' THEN 0 WHEN N'ĐẶT HÀNG NGAY' THEN 1 WHEN N'TỒN NHIỀU' THEN 2 WHEN N'ỔN' THEN 3 ELSE 4 END;

    SELECT MaSP, TenSP, TenNCC, TonHienTai, ADS AS BanTB_Ngay, XuHuongPT AS ThayDoi30Ngay_PhanTram, Cau AS XuHuongBan,
           DuDoan30Ngay, LeadTime AS HangVe_Ngay, LT_Lech AS HangVe_LechChuan, TonAnToan, ROP, SoNgayConLai AS DuBan_Ngay,
           SoNenNhap, MonHayMuaChung, TrangThai, ViecNenLam, ThongBao
    FROM #KQ
    ORDER BY CASE TrangThai WHEN N'KHẨN CẤP' THEN 0 WHEN N'ĐẶT HÀNG NGAY' THEN 1 WHEN N'TỒN NHIỀU' THEN 2 WHEN N'ỔN' THEN 3 ELSE 4 END,
             SoNgayConLai;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_TinhMucPhaiDatHang;
GO
CREATE PROCEDURE dbo.sp_TinhMucPhaiDatHang
    @SoNgayPhanTich INT = 90,
    @LeadTimeNgay INT = 7,
    @HeSoZ DECIMAL(4,2) = 1.65,
    @DenNgay DATE = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @SoNgayPhanTich < 2 OR @LeadTimeNgay < 1 OR @HeSoZ < 0
    BEGIN
        RAISERROR(N'Số nhập vào không hợp lệ: số ngày xét phải >= 2, số ngày hàng về >= 1, hệ số tồn dự phòng >= 0.', 16, 1);
        RETURN;
    END

    DECLARE @SoNgayGan INT = CASE WHEN @SoNgayPhanTich < 30 THEN @SoNgayPhanTich ELSE 30 END;
    DECLARE @Z FLOAT = @HeSoZ;
    DECLARE @LT FLOAT = @LeadTimeNgay;

    EXEC dbo.sp_BangThongBao_KhoHang
        @DenNgay = @DenNgay,
        @SoNgayPhanTich = @SoNgayPhanTich,
        @SoNgayGan = @SoNgayGan,
        @HeSoZ = @Z,
        @LeadTimeMacDinh = @LT,
        @HienKetQua = 0;

    SELECT MaSP, TenSP, TonKhoAnToan, DiemDatHangLai_ROP, SoNgayConLai_DuKien
    FROM SanPham
    ORDER BY MaSP;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_BangThongBao_MuaTheoCamXuc;
GO
CREATE PROCEDURE dbo.sp_BangThongBao_MuaTheoCamXuc
    @DenNgay DATE = NULL,
    @SoNgay INT = 365,
    @SoNgayMuaLai INT = 60,
    @MinSoBan INT = 30,
    @NguongKeo FLOAT = 1.3,
    @NguongHung FLOAT = 2.0,
    @HeSoDaoDong FLOAT = 1.96
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @SoNgay < 1 OR @SoNgayMuaLai < 1 OR @MinSoBan < 1 OR @NguongKeo > @NguongHung OR @HeSoDaoDong < 0
    BEGIN
        RAISERROR(N'Số nhập vào không hợp lệ: số ngày >= 1, mức "kéo" không được lớn hơn mức "hứng", hệ số dao động >= 0.', 16, 1);
        RETURN;
    END
    IF EXISTS (SELECT 1 FROM TraHang WHERE NhomLyDoChinh IS NULL)
    BEGIN
        RAISERROR(N'Chưa chạy đủ các bước trước. Chạy lần lượt: EXEC sp_TuDongLamSach_DuLieuGiaoDich; EXEC sp_PhanTichChuDeKhieuNai; rồi chạy lại thủ tục này.', 16, 1);
        RETURN;
    END
    IF EXISTS (SELECT 1 FROM DotSale a JOIN DotSale b ON a.MaDot < b.MaDot AND a.NgayBatDau <= b.NgayKetThuc AND b.NgayBatDau <= a.NgayKetThuc)
    BEGIN
        RAISERROR(N'Bảng DotSale có các đợt sale chồng ngày lên nhau, không đếm đúng số ngày sale được. Hãy sửa lại bảng DotSale.', 16, 1);
        RETURN;
    END

    IF @DenNgay IS NULL SELECT @DenNgay = CAST(MAX(NgayDat) AS DATE) FROM DonHang;
    IF @DenNgay IS NULL
    BEGIN
        RAISERROR(N'Chưa có đơn hàng nào.', 16, 1);
        RETURN;
    END
    DECLARE @Tu DATE = DATEADD(DAY, -(@SoNgay - 1), @DenNgay);
    DECLARE @MocMuaLai DATE = DATEADD(DAY, -@SoNgayMuaLai, @DenNgay);

    IF OBJECT_ID('tempdb..#Co') IS NOT NULL DROP TABLE #Co;
    IF OBJECT_ID('tempdb..#Ban') IS NOT NULL DROP TABLE #Ban;
    CREATE TABLE #Co (NgaySale INT NOT NULL, NgayThuong INT NOT NULL);
    CREATE TABLE #Ban (MaSP VARCHAR(50) NOT NULL, LaSale INT NOT NULL, SoBan INT NOT NULL, SoTra INT NOT NULL, SoDoiY INT NOT NULL);

    ;WITH Cat AS (
        SELECT CASE WHEN NgayBatDau < @Tu THEN @Tu ELSE NgayBatDau END AS Bd,
               CASE WHEN NgayKetThuc > @DenNgay THEN @DenNgay ELSE NgayKetThuc END AS Kt
        FROM DotSale
    )
    SELECT ISNULL(SUM(CASE WHEN Kt >= Bd THEN DATEDIFF(DAY, Bd, Kt) + 1 ELSE 0 END), 0),
           @SoNgay - ISNULL(SUM(CASE WHEN Kt >= Bd THEN DATEDIFF(DAY, Bd, Kt) + 1 ELSE 0 END), 0)
    FROM Cat;

    SELECT x.MaSP, x.LaSale, SUM(x.SoBan), SUM(x.SoTra), SUM(x.SoDoiY)
    FROM (
        SELECT ctd.MaSP,
               CASE WHEN EXISTS (SELECT 1 FROM DotSale s WHERE CAST(dh.NgayDat AS DATE) BETWEEN s.NgayBatDau AND s.NgayKetThuc) THEN 1 ELSE 0 END AS LaSale,
               ctd.SoLuong AS SoBan, 0 AS SoTra, 0 AS SoDoiY
        FROM ChiTietDonHang ctd
        JOIN DonHang dh ON dh.MaDH = ctd.MaDH
        WHERE ISNULL(dh.TrangThai, N'') NOT LIKE N'%hủy%' AND dh.NgayDat >= @Tu AND dh.NgayDat < DATEADD(DAY, 1, @DenNgay)
        UNION ALL
        SELECT th.MaSP,
               CASE WHEN EXISTS (SELECT 1 FROM DotSale s WHERE CAST(dh.NgayDat AS DATE) BETWEEN s.NgayBatDau AND s.NgayKetThuc) THEN 1 ELSE 0 END,
               0, th.SoLuong,
               CASE WHEN th.NhomLyDoChinh = N'Đổi ý / không có nhu cầu' THEN th.SoLuong ELSE 0 END
        FROM TraHang th
        JOIN DonHang dh ON dh.MaDH = th.MaDH
        WHERE ISNULL(dh.TrangThai, N'') NOT LIKE N'%hủy%' AND dh.NgayDat >= @Tu AND dh.NgayDat < DATEADD(DAY, 1, @DenNgay)
    ) x
    GROUP BY x.MaSP, x.LaSale;

    ;WITH G AS (
        SELECT MaSP,
               SUM(CASE WHEN LaSale = 1 THEN SoBan ELSE 0 END) AS BanSale,
               SUM(CASE WHEN LaSale = 0 THEN SoBan ELSE 0 END) AS BanThuong,
               SUM(CASE WHEN LaSale = 1 THEN SoTra ELSE 0 END) AS TraSale,
               SUM(CASE WHEN LaSale = 0 THEN SoTra ELSE 0 END) AS TraThuong
        FROM #Ban
        GROUP BY MaSP
    ),
    T AS (
        SELECT sp.MaSP, sp.TenSP,
               ISNULL(g.BanSale, 0) AS BanSale, ISNULL(g.BanThuong, 0) AS BanThuong,
               ISNULL(g.TraSale, 0) AS TraSale, ISNULL(g.TraThuong, 0) AS TraThuong,
               c.NgaySale, c.NgayThuong
        FROM SanPham sp
        LEFT JOIN G g ON g.MaSP = sp.MaSP
        CROSS JOIN #Co c
    ),
    T2 AS (
        SELECT *,
               1.0 * BanSale / NULLIF(NgaySale, 0) AS BanTB_Sale,
               1.0 * BanThuong / NULLIF(NgayThuong, 0) AS BanTB_Thuong,
               100.0 * TraSale / NULLIF(BanSale, 0) AS TraSalePT,
               100.0 * TraThuong / NULLIF(BanThuong, 0) AS TraThuongPT
        FROM T
    ),
    T3 AS (
        SELECT *, BanTB_Sale / NULLIF(BanTB_Thuong, 0) AS Lift FROM T2
    ),
    T4 AS (
        SELECT *,
               CASE WHEN BanSale < @MinSoBan THEN N'Chưa đủ số liệu'
                    WHEN Lift >= @NguongHung THEN N'MUA THEO HỨNG SALE'
                    WHEN Lift >= @NguongKeo THEN N'SALE CÓ KÉO THÊM ĐƠN'
                    ELSE N'ÍT BỊ SALE KÉO' END AS KieuMua
        FROM T3
    )
    SELECT MaSP, TenSP, BanSale, BanThuong, TraSale, TraThuong, BanTB_Sale, BanTB_Thuong, Lift, TraSalePT, TraThuongPT, KieuMua,
           CASE WHEN BanSale + BanThuong = 0 THEN N'Chưa bán được cái nào trong kỳ.'
                ELSE CONCAT(
                    N'Ngày sale bán TB ', dbo.fn_SoVN(BanTB_Sale, 1), N' cái/ngày',
                    CASE WHEN Lift IS NULL THEN N''
                         ELSE CONCAT(N', gấp ', dbo.fn_SoVN(Lift, 1), N' lần ngày thường (', dbo.fn_SoVN(BanTB_Thuong, 1), N' cái/ngày)') END,
                    N'. Trả hàng: ',
                    CASE WHEN TraSalePT IS NULL THEN N'–' ELSE CONCAT(dbo.fn_SoVN(TraSalePT, 1), N'%') END, N' ở ngày sale, ',
                    CASE WHEN TraThuongPT IS NULL THEN N'–' ELSE CONCAT(dbo.fn_SoVN(TraThuongPT, 1), N'%') END, N' ở ngày thường.',
                    CASE WHEN BanSale < @MinSoBan
                         THEN CONCAT(N' (Chỉ bán ', BanSale, N' cái trong ngày sale, ít quá nên chưa đáng tin.)') ELSE N'' END
                ) END AS ThongBao
    FROM T4
    ORDER BY CASE WHEN Lift IS NULL THEN 1 ELSE 0 END, Lift DESC;

    ;WITH T AS (
        SELECT CAST(ISNULL(SUM(CASE WHEN b.LaSale = 1 THEN b.SoBan ELSE 0 END), 0) AS FLOAT) AS BanSale,
               CAST(ISNULL(SUM(CASE WHEN b.LaSale = 0 THEN b.SoBan ELSE 0 END), 0) AS FLOAT) AS BanThuong,
               CAST(ISNULL(SUM(CASE WHEN b.LaSale = 1 THEN b.SoTra ELSE 0 END), 0) AS FLOAT) AS TraSale,
               CAST(ISNULL(SUM(CASE WHEN b.LaSale = 0 THEN b.SoTra ELSE 0 END), 0) AS FLOAT) AS TraThuong,
               CAST(ISNULL(SUM(CASE WHEN b.LaSale = 1 THEN b.SoDoiY ELSE 0 END), 0) AS FLOAT) AS DoiYSale,
               CAST(ISNULL(SUM(CASE WHEN b.LaSale = 0 THEN b.SoDoiY ELSE 0 END), 0) AS FLOAT) AS DoiYThuong,
               MAX(c.NgaySale) AS NgaySale, MAX(c.NgayThuong) AS NgayThuong
        FROM #Co c
        LEFT JOIN #Ban b ON 1 = 1
    ),
    Cap AS (
        SELECT 2 AS Thu, N'Đơn mua ngày sale có bị trả nhiều hơn không (hối hận sau mua)?' AS CauHoi,
               TraSale / NULLIF(BanSale, 0) AS p1, BanSale AS n1, TraThuong / NULLIF(BanThuong, 0) AS p2, BanThuong AS n2
        FROM T
        UNION ALL
        SELECT 3, N'Trong hàng bị trả, lý do "đổi ý / không cần" có nhiều hơn ở đơn ngày sale không?',
               DoiYSale / NULLIF(TraSale, 0), TraSale, DoiYThuong / NULLIF(TraThuong, 0), TraThuong
        FROM T
    ),
    Tinh AS (
        SELECT *, p1 - p2 AS Chenh,
               @HeSoDaoDong * SQRT(p1 * (1 - p1) / NULLIF(n1, 0) + p2 * (1 - p2) / NULLIF(n2, 0)) AS DaoDong
        FROM Cap
    )
    SELECT 1 AS Thu, N'Ngày sale bán gấp mấy lần ngày thường?' AS CauHoi,
           CASE WHEN BanThuong = 0 OR NgayThuong = 0 OR NgaySale = 0 THEN N'–'
                ELSE CONCAT(dbo.fn_SoVN((BanSale / NgaySale) / (BanThuong / NgayThuong), 1), N' lần') END AS SoDo,
           CONCAT(N'Cả shop bán TB ', dbo.fn_SoVN(BanSale / NULLIF(NgaySale, 0), 1), N' cái/ngày vào ngày sale, so với ',
                  dbo.fn_SoVN(BanThuong / NULLIF(NgayThuong, 0), 1),
                  N' cái/ngày vào ngày thường. Đây là dấu hiệu khách mua theo hứng khuyến mãi; dữ liệu không đo trực tiếp được cảm xúc lúc mua.') AS KetLuan
    FROM T
    UNION ALL
    SELECT Thu, CauHoi,
           CASE WHEN p1 IS NULL OR p2 IS NULL THEN N'–'
                ELSE CONCAT(dbo.fn_SoVN(100 * p1, 1), N'% so với ', dbo.fn_SoVN(100 * p2, 1), N'%') END,
           CASE WHEN n1 < @MinSoBan OR n2 < @MinSoBan
                     THEN CONCAT(N'Chưa đủ số liệu để so sánh (cần mỗi bên từ ', @MinSoBan, N' trở lên).')
                WHEN Chenh > DaoDong
                     THEN CONCAT(N'Khác biệt có thật: ngày sale CAO hơn ', dbo.fn_SoVN(100 * Chenh, 1), N' điểm % so với ngày thường, vượt mức dao động ±', dbo.fn_SoVN(100 * DaoDong, 1), N' điểm %.')
                WHEN Chenh < -DaoDong
                     THEN CONCAT(N'Khác biệt có thật: ngày sale THẤP hơn ', dbo.fn_SoVN(100 * ABS(Chenh), 1), N' điểm % so với ngày thường, vượt mức dao động ±', dbo.fn_SoVN(100 * DaoDong, 1), N' điểm %.')
                ELSE CONCAT(N'Chưa kết luận được: ngày sale ', CASE WHEN Chenh >= 0 THEN N'cao' ELSE N'thấp' END, N' hơn ', dbo.fn_SoVN(100 * ABS(Chenh), 1),
                            N' điểm % so với ngày thường nhưng chỉ ngang mức dao động ±', dbo.fn_SoVN(100 * DaoDong, 1), N' điểm % do ít mẫu.') END
    FROM Tinh
    ORDER BY Thu;

    ;WITH R AS (
        SELECT dg.MaDanhGia,
               CASE WHEN dg.SoSao >= 4 THEN N'Vui (4-5 sao)' WHEN dg.SoSao = 3 THEN N'Bình thường (3 sao)' ELSE N'Buồn (1-2 sao)' END AS Nhom,
               CASE WHEN dg.SoSao >= 4 THEN N'Vui' WHEN dg.SoSao = 3 THEN N'Bình thường' ELSE N'Buồn' END AS TenNhom,
               CASE WHEN EXISTS (SELECT 1 FROM DonHang o
                                 WHERE o.MaKH = dg.MaKH AND ISNULL(o.TrangThai, N'') NOT LIKE N'%hủy%'
                                   AND o.NgayDat > dg.NgayDanhGia AND o.NgayDat <= DATEADD(DAY, @SoNgayMuaLai, dg.NgayDanhGia))
                    THEN 1 ELSE 0 END AS MuaLai
        FROM DanhGiaSanPham dg
        WHERE dg.MaKH IS NOT NULL AND CAST(dg.NgayDanhGia AS DATE) >= @Tu AND CAST(dg.NgayDanhGia AS DATE) <= @MocMuaLai
    ),
    L AS (
        SELECT Nhom, TenNhom, COUNT(*) AS SoLuot, SUM(MuaLai) AS SoMuaLai, 1.0 * SUM(MuaLai) / COUNT(*) AS p
        FROM R
        GROUP BY Nhom, TenNhom
    ),
    V AS (SELECT p AS pV, SoLuot AS nV FROM L WHERE Nhom = N'Vui (4-5 sao)'),
    K AS (
        SELECT l.Nhom, l.TenNhom, l.SoLuot, l.SoMuaLai, 100.0 * l.p AS TyLeMuaLai, l.SoLuot AS n1, v.nV AS n2,
               l.p - v.pV AS Chenh,
               @HeSoDaoDong * SQRT(l.p * (1 - l.p) / l.SoLuot + v.pV * (1 - v.pV) / v.nV) AS DaoDong
        FROM L l
        CROSS JOIN V v
    )
    SELECT Nhom, SoLuot AS SoLuotDanhGia, SoMuaLai AS SoLuotMuaLai, TyLeMuaLai,
           CASE WHEN Nhom = N'Vui (4-5 sao)' THEN N'Nhóm đối chiếu.'
                WHEN n1 < @MinSoBan OR n2 < @MinSoBan
                     THEN CONCAT(N'Chưa đủ số liệu để so sánh (cần mỗi bên từ ', @MinSoBan, N' trở lên).')
                WHEN Chenh > DaoDong
                     THEN CONCAT(N'Khác biệt có thật: nhóm ', TenNhom, N' CAO hơn ', dbo.fn_SoVN(100 * Chenh, 1), N' điểm % so với nhóm Vui, vượt mức dao động ±', dbo.fn_SoVN(100 * DaoDong, 1), N' điểm %.')
                WHEN Chenh < -DaoDong
                     THEN CONCAT(N'Khác biệt có thật: nhóm ', TenNhom, N' THẤP hơn ', dbo.fn_SoVN(100 * ABS(Chenh), 1), N' điểm % so với nhóm Vui, vượt mức dao động ±', dbo.fn_SoVN(100 * DaoDong, 1), N' điểm %.')
                ELSE CONCAT(N'Chưa kết luận được: nhóm ', TenNhom, N' ', CASE WHEN Chenh >= 0 THEN N'cao' ELSE N'thấp' END, N' hơn ', dbo.fn_SoVN(100 * ABS(Chenh), 1),
                            N' điểm % so với nhóm Vui nhưng chỉ ngang mức dao động ±', dbo.fn_SoVN(100 * DaoDong, 1), N' điểm % do ít mẫu.') END AS KetLuan
    FROM K
    ORDER BY CASE Nhom WHEN N'Vui (4-5 sao)' THEN 0 WHEN N'Bình thường (3 sao)' THEN 1 ELSE 2 END;
END;
GO

CREATE TABLE TuDien_LyDoMua (
    Id INT IDENTITY(1,1) PRIMARY KEY,
    TuKhoa NVARCHAR(100) NOT NULL UNIQUE,
    NhomLyDo NVARCHAR(40) NOT NULL,
    ThuTuNhom INT NOT NULL
);

CREATE TABLE KhaoSat_LyDoMua (
    Id INT IDENTITY(1,1) PRIMARY KEY,
    MaDH VARCHAR(20) NOT NULL UNIQUE FOREIGN KEY REFERENCES DonHang(MaDH),
    MaKH VARCHAR(20) NULL FOREIGN KEY REFERENCES KhachHang(MaKH),
    NgayTraLoi DATETIME NOT NULL,
    LoiKhachNoi NVARCHAR(500) NULL,
    MucHaoHung INT NULL CHECK (MucHaoHung BETWEEN 1 AND 5)
);

CREATE TABLE PhanTich_LyDoMua (
    Id INT IDENTITY(1,1) PRIMARY KEY,
    KhaoSatId INT NOT NULL UNIQUE FOREIGN KEY REFERENCES KhaoSat_LyDoMua(Id),
    NhomLyDo NVARCHAR(40) NOT NULL,
    ThuTuNhom INT NOT NULL,
    SoTuKhop INT NOT NULL
);
GO

GO

CREATE TABLE CachBan_TheoLyDoMua (
    NhomLyDo NVARCHAR(40) PRIMARY KEY,
    KieuLyDo NVARCHAR(20) NOT NULL,
    CachBanHop NVARCHAR(400) NOT NULL
);
