DROP PROCEDURE IF EXISTS dbo.sp_PhanTichLyDoMua;
GO
CREATE PROCEDURE dbo.sp_PhanTichLyDoMua
    @HienKetQua BIT = 1
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF OBJECT_ID('tempdb..#Chu') IS NOT NULL DROP TABLE #Chu;
    CREATE TABLE #Chu (KhaoSatId INT NOT NULL, Txt NVARCHAR(MAX) NULL);


    UPDATE #Chu
    SET Txt = N' ' + dbo.fn_LamSachKyTu(
                  REPLACE(REPLACE(REPLACE(REPLACE(LOWER(ISNULL(Txt, N'')), N',', N' '), N'.', N' '), N'-', N' '), N'/', N' ')
              ) + N' ';

    DECLARE @Goc NVARCHAR(100), @Chuan NVARCHAR(100), @Lan INT = 1;
    DECLARE cur_Teen CURSOR LOCAL FAST_FORWARD FOR
        SELECT TuGoc, TuChuanHoa FROM TuDien_Teencode ORDER BY LEN(TuGoc) DESC, Id;
    WHILE @Lan <= 2
    BEGIN
        OPEN cur_Teen;
        FETCH NEXT FROM cur_Teen INTO @Goc, @Chuan;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            UPDATE #Chu SET Txt = REPLACE(Txt, N' ' + LOWER(@Goc) + N' ', N' ' + @Chuan + N' ');
            FETCH NEXT FROM cur_Teen INTO @Goc, @Chuan;
        END
        CLOSE cur_Teen;
        SET @Lan = @Lan + 1;
    END
    DEALLOCATE cur_Teen;

    BEGIN TRANSACTION;
    BEGIN TRY
        DELETE FROM PhanTich_LyDoMua;

        ;WITH Khop AS (
            SELECT v.KhaoSatId, d.NhomLyDo, d.ThuTuNhom, COUNT(*) AS SoTu
            FROM #Chu v
            JOIN TuDien_LyDoMua d ON v.Txt LIKE CONCAT(N'% ', d.TuKhoa, N' %')
            GROUP BY v.KhaoSatId, d.NhomLyDo, d.ThuTuNhom
        ),
        Xep AS (
            SELECT KhaoSatId, NhomLyDo, ThuTuNhom, SoTu,
                   ROW_NUMBER() OVER (PARTITION BY KhaoSatId ORDER BY SoTu DESC, ThuTuNhom) AS Hang
            FROM Khop
        )
        SELECT v.KhaoSatId, ISNULL(x.NhomLyDo, N'Khác / không rõ'), ISNULL(x.ThuTuNhom, 99), ISNULL(x.SoTu, 0)
        FROM #Chu v
        LEFT JOIN Xep x ON x.KhaoSatId = v.KhaoSatId AND x.Hang = 1;

        SELECT N'Xếp nhóm lý do mua', COUNT(*), 0, GETDATE() FROM PhanTich_LyDoMua;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH


    IF @HienKetQua = 1
    SELECT NhomLyDo, COUNT(*) AS SoCau FROM PhanTich_LyDoMua GROUP BY NhomLyDo ORDER BY COUNT(*) DESC;
END;
GO

DROP PROCEDURE IF EXISTS dbo.sp_BangThongBao_LyDoMua;
GO
CREATE PROCEDURE dbo.sp_BangThongBao_LyDoMua
    @MinSoBan INT = 30,
    @HeSoDaoDong FLOAT = 1.96
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM KhaoSat_LyDoMua)
    BEGIN
        RAISERROR(N'Chưa có câu trả lời khảo sát nào trong bảng KhaoSat_LyDoMua.', 16, 1);
        RETURN;
    END
    IF (SELECT COUNT(*) FROM PhanTich_LyDoMua) <> (SELECT COUNT(*) FROM KhaoSat_LyDoMua)
    BEGIN
        RAISERROR(N'Chưa xếp nhóm hết các câu trả lời. Chạy: EXEC sp_PhanTichLyDoMua; rồi chạy lại thủ tục này.', 16, 1);
        RETURN;
    END

    ;WITH D AS (
        SELECT p.NhomLyDo, p.ThuTuNhom, k.MucHaoHung, dh.TongTien,
               CASE WHEN EXISTS (SELECT 1 FROM TraHang th WHERE th.MaDH = k.MaDH) THEN 1 ELSE 0 END AS CoTra
        FROM KhaoSat_LyDoMua k
        JOIN PhanTich_LyDoMua p ON p.KhaoSatId = k.Id
        JOIN DonHang dh ON dh.MaDH = k.MaDH
    ),
    G AS (
        SELECT NhomLyDo, MIN(ThuTuNhom) AS ThuTu, COUNT(*) AS SoCau,
               AVG(CAST(MucHaoHung AS FLOAT)) AS HaoHung, AVG(CAST(TongTien AS FLOAT)) AS GiaTriDon, SUM(CoTra) AS SoTra
        FROM D
        GROUP BY NhomLyDo
    ),
    T AS (SELECT SUM(SoCau) AS TongCau, SUM(SoTra) AS TongTra FROM G),
    K AS (
        SELECT g.NhomLyDo, g.ThuTu, g.SoCau, g.HaoHung, g.GiaTriDon, g.SoTra,
               100.0 * g.SoCau / t.TongCau AS TyLe,
               1.0 * g.SoTra / g.SoCau AS p1, g.SoCau AS n1,
               1.0 * (t.TongTra - g.SoTra) / NULLIF(t.TongCau - g.SoCau, 0) AS p2, t.TongCau - g.SoCau AS n2
        FROM G g CROSS JOIN T t
    ),
    K2 AS (
        SELECT *, p1 - p2 AS Chenh,
               @HeSoDaoDong * SQRT(p1 * (1 - p1) / n1 + p2 * (1 - p2) / NULLIF(n2, 0)) AS DaoDong
        FROM K
    ),
    K3 AS (
        SELECT *,
               CASE WHEN n1 < @MinSoBan OR n2 < @MinSoBan
                         THEN CONCAT(N'Chưa đủ số liệu để so sánh (cần mỗi bên từ ', @MinSoBan, N' trở lên).')
                    WHEN Chenh > DaoDong
                         THEN CONCAT(N'Khác biệt có thật: nhóm này CAO hơn ', dbo.fn_SoVN(100 * Chenh, 1), N' điểm % so với các nhóm còn lại, vượt mức dao động ±', dbo.fn_SoVN(100 * DaoDong, 1), N' điểm %.')
                    WHEN Chenh < -DaoDong
                         THEN CONCAT(N'Khác biệt có thật: nhóm này THẤP hơn ', dbo.fn_SoVN(100 * ABS(Chenh), 1), N' điểm % so với các nhóm còn lại, vượt mức dao động ±', dbo.fn_SoVN(100 * DaoDong, 1), N' điểm %.')
                    ELSE CONCAT(N'Chưa kết luận được: nhóm này ', CASE WHEN Chenh >= 0 THEN N'cao' ELSE N'thấp' END, N' hơn ', dbo.fn_SoVN(100 * ABS(Chenh), 1),
                                N' điểm % so với các nhóm còn lại nhưng chỉ ngang mức dao động ±', dbo.fn_SoVN(100 * DaoDong, 1), N' điểm % do ít mẫu.') END AS KetLuan
        FROM K2
    )
    SELECT NhomLyDo, SoCau, TyLe, HaoHung, GiaTriDon, 100.0 * p1 AS TraHangPT, 100.0 * p2 AS TraHangPT_NhomKhac, KetLuan,
           CONCAT(NhomLyDo, N': ', SoCau, N' câu trả lời (', dbo.fn_SoVN(TyLe, 1), N'%), hào hứng TB ', dbo.fn_SoVN(HaoHung, 1),
                  N'/5, giá trị đơn TB ', dbo.fn_SoVN(GiaTriDon / 1000000.0, 1), N' triệu. Có trả hàng ở ', dbo.fn_SoVN(100 * p1, 1),
                  N'% đơn (các nhóm còn lại: ', dbo.fn_SoVN(100 * p2, 1), N'%). ', KetLuan) AS ThongBao
    FROM K3
    ORDER BY SoCau DESC, ThuTu;
END;
GO

