    CHECK (TrangThai IN (N'Chờ xác nhận', N'Chờ lấy hàng', N'Đang giao', N'Đã giao', N'Trả hàng/Hoàn tiền', N'Đã hủy'));
ALTER TABLE VanDon WITH CHECK ADD CONSTRAINT CK_VanDon_TrangThai
    CHECK (TrangThai IN (N'Đang giao', N'Đã giao', N'Giao không thành công'));
GO

CREATE OR ALTER TRIGGER trg_KiemTraTrangThaiDonHang
ON DonHang
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT UPDATE(TrangThai) RETURN;

    IF EXISTS (
        SELECT 1
        FROM inserted i
        JOIN deleted d ON d.MaDH = i.MaDH
        WHERE d.TrangThai = N'Đã hủy' AND ISNULL(i.TrangThai, N'') <> N'Đã hủy'
    )
    BEGIN
        RAISERROR(N'Đơn đã hủy thì không mở lại được. Hãy tạo đơn mới.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END
END;
GO

CREATE OR ALTER TRIGGER trg_KiemTraXuatKhoTheoDon
ON ChiTietPhieuXuat
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (
        SELECT 1
        FROM inserted i
        JOIN PhieuXuat px ON px.MaPX = i.MaPX
        JOIN DonHang dh ON dh.MaDH = px.MaDH
        WHERE ISNULL(dh.TrangThai, N'') LIKE N'%hủy%'
    )
    BEGIN
        RAISERROR(N'Đơn đã hủy thì không xuất kho.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT DISTINCT px.MaDH, i.MaSP
            FROM inserted i
            JOIN PhieuXuat px ON px.MaPX = i.MaPX
            WHERE px.MaDH IS NOT NULL
        ) k
        OUTER APPLY (
            SELECT SUM(cx.SoLuong) AS DaXuat
            FROM ChiTietPhieuXuat cx
            JOIN PhieuXuat p2 ON p2.MaPX = cx.MaPX
            WHERE p2.MaDH = k.MaDH AND cx.MaSP = k.MaSP
        ) x
        OUTER APPLY (
            SELECT SUM(ct.SoLuong) AS DaDat
            FROM ChiTietDonHang ct
            WHERE ct.MaDH = k.MaDH AND ct.MaSP = k.MaSP
        ) d
        WHERE x.DaXuat > ISNULL(d.DaDat, 0)
    )
    BEGIN
        RAISERROR(N'Xuất kho nhiều hơn số khách đặt, hoặc xuất món không có trong đơn.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END
END;
GO

CREATE OR ALTER TRIGGER trg_KiemTraTraHang
ON TraHang
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (SELECT 1 FROM inserted WHERE MaDH IS NULL)
    BEGIN
        RAISERROR(N'Phiếu trả hàng phải ghi mã đơn hàng.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    IF EXISTS (
        SELECT 1
        FROM inserted i
        JOIN DonHang dh ON dh.MaDH = i.MaDH
        WHERE ISNULL(dh.TrangThai, N'') NOT IN (N'Đã giao', N'Trả hàng/Hoàn tiền')
    )
    BEGIN
        RAISERROR(N'Chỉ nhận trả hàng cho đơn đã giao tới khách. Đơn chưa giao thì dùng Hủy đơn.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    IF EXISTS (
        SELECT 1
        FROM (SELECT DISTINCT MaDH, MaSP FROM inserted) k
        OUTER APPLY (SELECT SUM(t.SoLuong) AS DaTra FROM TraHang t WHERE t.MaDH = k.MaDH AND t.MaSP = k.MaSP) tr
        OUTER APPLY (SELECT SUM(ct.SoLuong) AS DaMua FROM ChiTietDonHang ct WHERE ct.MaDH = k.MaDH AND ct.MaSP = k.MaSP) mu
        WHERE tr.DaTra > ISNULL(mu.DaMua, 0)
    )
    BEGIN
        RAISERROR(N'Số lượng trả nhiều hơn số khách đã mua trong đơn.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    IF EXISTS (
        SELECT 1
        FROM inserted i
        JOIN ChiTietDonHang ct ON ct.MaDH = i.MaDH AND ct.MaSP = i.MaSP
        JOIN DonHang dh ON dh.MaDH = i.MaDH
        WHERE i.SoTienHoan > ROUND(i.SoLuong * ct.DonGia * (dh.TongTien - dh.GiamGiaCuaShop) / NULLIF(dh.TongTien, 0), 0)
    )
    BEGIN
        RAISERROR(N'Tiền hoàn lớn hơn số khách thực trả cho số hàng này (giảm giá của shop đã được chia theo giá trị từng món).', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    UPDATE dh
    SET dh.TrangThai = N'Trả hàng/Hoàn tiền'
    FROM DonHang dh
    JOIN (SELECT DISTINCT MaDH FROM inserted) i ON i.MaDH = dh.MaDH
    WHERE dh.TrangThai = N'Đã giao';
END;
GO

CREATE OR ALTER PROCEDURE dbo.sp_HuyDon
    @MaDH VARCHAR(20),
    @LyDo NVARCHAR(255),
    @ChoPhepKhiDangGiao BIT = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @TuMo BIT = CASE WHEN @@TRANCOUNT = 0 THEN 1 ELSE 0 END;
    BEGIN TRY
        IF @TuMo = 1
        BEGIN
            BEGIN TRANSACTION;
        END

        DECLARE @TT NVARCHAR(50);
        SELECT @TT = TrangThai FROM DonHang WITH (UPDLOCK) WHERE MaDH = @MaDH;

        IF @TT IS NULL
            THROW 50040, N'Không tìm thấy đơn hàng.', 1;
        IF @TT = N'Đã hủy'
            THROW 50041, N'Đơn này đã hủy rồi.', 1;
        IF @TT IN (N'Đã giao', N'Trả hàng/Hoàn tiền')
            THROW 50042, N'Đơn đã giao tới khách thì không hủy được. Nếu khách muốn trả, hãy dùng "Trả hàng & hoàn tiền".', 1;
        IF @TT = N'Đang giao' AND @ChoPhepKhiDangGiao = 0
            THROW 50043, N'Đơn đang trên đường giao nên chưa hủy được. Chờ kết quả giao: nếu giao không thành công thì bấm "Giao không thành công" ở màn Vận đơn. Khi hàng về tới kho, bấm "Nhận hàng hoàn về kho" ở Danh sách đơn hàng.', 1;
        IF LEN(LTRIM(RTRIM(ISNULL(@LyDo, N'')))) = 0
            THROW 50044, N'Chưa nhập lý do hủy đơn.', 1;

        SELECT px.MaDH, px.MaPX, px.MaKho, cx.MaSP, cx.SoLuong, LTRIM(RTRIM(@LyDo)),
               CASE WHEN @TT = N'Chờ lấy hàng' THEN N'Đã nhận về kho' ELSE N'Đang hoàn về' END,
               CASE WHEN @TT = N'Chờ lấy hàng' THEN GETDATE() END
        FROM PhieuXuat px
        JOIN ChiTietPhieuXuat cx ON cx.MaPX = px.MaPX
        WHERE px.MaDH = @MaDH
          AND NOT EXISTS (SELECT 1 FROM HangHoanVeKho h WHERE h.MaPX = px.MaPX AND h.MaSP = cx.MaSP);

        UPDATE DonHang
        SET TrangThai = N'Đã hủy', NgayHuy = GETDATE(), LyDoHuy = LTRIM(RTRIM(@LyDo))
        WHERE MaDH = @MaDH;

        IF @TuMo = 1 COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @TuMo = 1 AND @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

CREATE OR ALTER PROCEDURE dbo.sp_TaoDonHang
    @MaKH VARCHAR(20) = NULL,
    @TenKH NVARCHAR(255) = NULL,
    @SoDT VARCHAR(20) = NULL,
    @DiaChi NVARCHAR(255) = NULL,
    @MaDoiTac VARCHAR(20),
    @PhuongThucThanhToan NVARCHAR(50),
    @GiamGiaCuaShop DECIMAL(18,2) = 0,
    @PhiVanChuyenKhachTra DECIMAL(18,2) = 0,
    @DsHang dbo.DanhSachHangMua READONLY,
    @MaDH VARCHAR(20) OUTPUT,
    @HinhThucNhan NVARCHAR(30) = N'Giao tận nơi'
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF NOT EXISTS (SELECT 1 FROM @DsHang)
            THROW 50010, N'Đơn chưa có món hàng nào.', 1;
        IF NOT EXISTS (SELECT 1 FROM DoiTac WHERE MaDoiTac = @MaDoiTac)
            THROW 50011, N'Chưa chọn kênh bán.', 1;
        IF EXISTS (SELECT 1 FROM @DsHang d WHERE NOT EXISTS (SELECT 1 FROM SanPham sp WHERE sp.MaSP = d.MaSP))
            THROW 50012, N'Có mã sản phẩm không có trong danh sách sản phẩm.', 1;
        IF EXISTS (SELECT 1 FROM @DsHang d JOIN SanPham sp ON sp.MaSP = d.MaSP WHERE sp.DangKinhDoanh = 0)
            THROW 50027, N'Có sản phẩm đã ngừng kinh doanh. Hãy bỏ món đó ra khỏi đơn.', 1;
        IF LEN(LTRIM(RTRIM(ISNULL(@PhuongThucThanhToan, N'')))) = 0
            THROW 50013, N'Chưa chọn cách khách trả tiền.', 1;
        IF ISNULL(@GiamGiaCuaShop, 0) < 0 OR ISNULL(@PhiVanChuyenKhachTra, 0) < 0
            THROW 50014, N'Giảm giá và phí vận chuyển không được là số âm.', 1;

        SET @HinhThucNhan = ISNULL(NULLIF(LTRIM(RTRIM(@HinhThucNhan)), N''), N'Giao tận nơi');
        IF @HinhThucNhan NOT IN (N'Giao tận nơi', N'Nhận tại cửa hàng')
            THROW 50023, N'Hình thức nhận hàng chỉ được là "Giao tận nơi" hoặc "Nhận tại cửa hàng".', 1;
        DECLARE @LoaiKenh NVARCHAR(30), @TenKenh NVARCHAR(255);
        SELECT @LoaiKenh = LoaiKenh, @TenKenh = TenDoiTac FROM DoiTac WHERE MaDoiTac = @MaDoiTac;
        IF @HinhThucNhan = N'Nhận tại cửa hàng' AND @LoaiKenh <> N'Cửa hàng'
            THROW 50024, N'Chỉ đơn bán ở cửa hàng mới chọn được "Nhận tại cửa hàng". Đơn trên sàn phải giao tận nơi.', 1;
        IF @PhuongThucThanhToan = N'Tiền mặt tại cửa hàng' AND @HinhThucNhan <> N'Nhận tại cửa hàng'
            THROW 50025, N'"Tiền mặt tại cửa hàng" chỉ dùng khi khách nhận hàng tại quầy. Giao tận nơi mà thu tiền mặt thì chọn COD.', 1;
        IF @PhuongThucThanhToan = N'Ví ShopeePay' AND @TenKenh NOT LIKE N'%Shopee%'
            THROW 50026, N'Ví ShopeePay chỉ có khi khách đặt trên Shopee.', 1;

        DECLARE @SdtChuan VARCHAR(20) = dbo.fn_ChuanHoaSoDienThoai(@SoDT);
        IF ISNULL(@MaKH, '') = ''
        BEGIN
            IF LEN(LTRIM(RTRIM(ISNULL(@TenKH, N'')))) = 0
                THROW 50015, N'Chưa nhập tên khách.', 1;
            IF @SdtChuan IS NULL
                THROW 50016, N'Số điện thoại khách không đúng (cần 10 số, bắt đầu bằng số 0, không phải số giả như 0900000000).', 1;
            IF @HinhThucNhan = N'Giao tận nơi' AND LEN(LTRIM(RTRIM(ISNULL(@DiaChi, N'')))) < 10
                THROW 50017, N'Địa chỉ giao hàng quá ngắn. Hãy ghi đủ số nhà, đường, phường/xã, quận/huyện, tỉnh/thành.', 1;

            SET @MaKH = NULL;
            SELECT TOP 1 @MaKH = MaKH
            FROM KhachHang WITH (UPDLOCK, HOLDLOCK)
            WHERE dbo.fn_ChuanHoaSoDienThoai(SoDT) = @SdtChuan
            ORDER BY MaKH;

            IF @MaKH IS NULL
            BEGIN
                DECLARE @SoKH INT = (SELECT ISNULL(MAX(TRY_CAST(SUBSTRING(MaKH, 3, 20) AS INT)), 0) + 1
                                     FROM KhachHang WITH (UPDLOCK, HOLDLOCK) WHERE MaKH LIKE 'KH%');
                SET @MaKH = 'KH' + CASE WHEN @SoKH < 1000 THEN RIGHT('00' + CAST(@SoKH AS VARCHAR(10)), 3) ELSE CAST(@SoKH AS VARCHAR(10)) END;
                VALUES (@MaKH, LTRIM(RTRIM(@TenKH)), @SdtChuan, NULLIF(LTRIM(RTRIM(@DiaChi)), N''), @SdtChuan);
            END
        END
        ELSE IF NOT EXISTS (SELECT 1 FROM KhachHang WHERE MaKH = @MaKH)
            THROW 50018, N'Không tìm thấy mã khách hàng.', 1;

        DECLARE @TenNhan NVARCHAR(255), @SdtNhan VARCHAR(20), @DiaChiNhan NVARCHAR(255), @Den BIT;
        SELECT @TenNhan = ISNULL(NULLIF(LTRIM(RTRIM(@TenKH)), N''), kh.TenKH),
               @SdtNhan = ISNULL(@SdtChuan, kh.SoDT),
               @DiaChiNhan = CASE WHEN @HinhThucNhan = N'Nhận tại cửa hàng' THEN N'Nhận tại cửa hàng ' + @TenKenh
                                  ELSE ISNULL(NULLIF(LTRIM(RTRIM(@DiaChi)), N''), kh.DiaChi) END,
               @Den = ISNULL(kh.DanhSachDen_Blacklist, 0)
        FROM KhachHang kh
        WHERE kh.MaKH = @MaKH;

        IF @HinhThucNhan = N'Giao tận nơi' AND LEN(LTRIM(RTRIM(ISNULL(@DiaChiNhan, N'')))) < 10
            THROW 50017, N'Địa chỉ giao hàng quá ngắn. Hãy ghi đủ số nhà, đường, phường/xã, quận/huyện, tỉnh/thành.', 1;
        IF @Den = 1 AND @PhuongThucThanhToan LIKE N'%COD%'
            THROW 50022, N'Khách này nằm trong danh sách đen (từng nhận đơn rồi không lấy hàng). Chỉ nhận đơn trả tiền trước, không nhận COD.', 1;

        DECLARE @Hang TABLE (MaSP VARCHAR(50) PRIMARY KEY, SoLuong INT NOT NULL, DonGia DECIMAL(18,2) NOT NULL, CoTheBan INT NULL);

        SELECT d.MaSP, d.SoLuong,
               ISNULL((SELECT MIN(km.GiaApDung)
                       FROM LichSuGiaKhuyenMai km
                       WHERE km.MaSP = d.MaSP AND CAST(GETDATE() AS DATE) BETWEEN km.TuNgay AND km.DenNgay),
                      ISNULL(sp.GiaBan, 0))
        FROM @DsHang d
        JOIN SanPham sp ON sp.MaSP = d.MaSP;

        IF EXISTS (SELECT 1 FROM @Hang WHERE DonGia <= 0)
            THROW 50019, N'Có sản phẩm chưa có giá bán. Hãy nhập giá bán ở màn Sản phẩm trước.', 1;

        UPDATE h
        SET h.CoTheBan = ISNULL(ton.Ton, 0) - ISNULL(giu.Giu, 0)
        FROM @Hang h
        OUTER APPLY (SELECT SUM(tk.SoLuongTon) AS Ton FROM TonKho tk WITH (UPDLOCK) WHERE tk.MaSP = h.MaSP) ton
        OUTER APPLY (
            SELECT SUM(ct.SoLuong) AS Giu
            FROM ChiTietDonHang ct
            JOIN DonHang dh ON dh.MaDH = ct.MaDH
            WHERE ct.MaSP = h.MaSP AND dh.TrangThai = N'Chờ xác nhận'
        ) giu;

        IF EXISTS (SELECT 1 FROM @Hang WHERE SoLuong > CoTheBan)
        BEGIN
            DECLARE @Thieu NVARCHAR(2000) = N'';
            SELECT @Thieu = @Thieu + sp.TenSP + N': khách đặt ' + CAST(h.SoLuong AS NVARCHAR(10))
                          + N', còn bán được ' + CAST(CASE WHEN h.CoTheBan < 0 THEN 0 ELSE h.CoTheBan END AS NVARCHAR(10)) + N'. '
            FROM @Hang h
            JOIN SanPham sp ON sp.MaSP = h.MaSP
            WHERE h.SoLuong > h.CoTheBan;
            SET @Thieu = N'Không đủ hàng để bán (đã trừ hàng đang giữ cho đơn chờ xác nhận). ' + @Thieu;
            THROW 50020, @Thieu, 1;
        END

        DECLARE @TienHang DECIMAL(18,2) = (SELECT SUM(SoLuong * DonGia) FROM @Hang);
        IF ISNULL(@GiamGiaCuaShop, 0) > @TienHang
            THROW 50021, N'Giảm giá của shop lớn hơn tiền hàng.', 1;

        DECLARE @SoDH INT = (SELECT ISNULL(MAX(TRY_CAST(SUBSTRING(MaDH, 3, 20) AS INT)), 0) + 1
                             FROM DonHang WITH (UPDLOCK, HOLDLOCK) WHERE MaDH LIKE 'DH%');
        SET @MaDH = 'DH' + CASE WHEN @SoDH < 1000 THEN RIGHT('00' + CAST(@SoDH AS VARCHAR(10)), 3) ELSE CAST(@SoDH AS VARCHAR(10)) END;

                             HinhThucNhan, TenNguoiNhan, SdtNguoiNhan, DiaChiGiao)
        VALUES (@MaDH, GETDATE(), @MaKH, @MaDoiTac, N'Chờ xác nhận', 0, LTRIM(RTRIM(@PhuongThucThanhToan)),
                ISNULL(@GiamGiaCuaShop, 0), ISNULL(@PhiVanChuyenKhachTra, 0),
                @HinhThucNhan, @TenNhan, @SdtNhan, LTRIM(RTRIM(@DiaChiNhan)));

        SELECT @MaDH, MaSP, SoLuong, DonGia FROM @Hang;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

CREATE OR ALTER PROCEDURE dbo.sp_XacNhanVaXuatKho
    @MaDH VARCHAR(20),
    @MaKho VARCHAR(20),
    @NguoiLap NVARCHAR(100),
    @MaPX VARCHAR(20) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @TT NVARCHAR(50), @Loi NVARCHAR(2048);
        SELECT @TT = TrangThai FROM DonHang WITH (UPDLOCK) WHERE MaDH = @MaDH;

        IF @TT IS NULL
            THROW 50030, N'Không tìm thấy đơn hàng.', 1;
        IF @TT <> N'Chờ xác nhận'
        BEGIN
            SET @Loi = N'Chỉ xác nhận và xuất kho cho đơn đang "Chờ xác nhận". Đơn này đang: ' + @TT + N'.';
            THROW 50031, @Loi, 1;
        END
        IF NOT EXISTS (SELECT 1 FROM Kho WHERE MaKho = @MaKho)
            THROW 50032, N'Không tìm thấy kho xuất.', 1;
        IF NOT EXISTS (SELECT 1 FROM ChiTietDonHang WHERE MaDH = @MaDH)
            THROW 50033, N'Đơn này chưa có món hàng nào để xuất.', 1;

        IF EXISTS (
            SELECT 1
            FROM ChiTietDonHang ct
            LEFT JOIN TonKho tk WITH (UPDLOCK) ON tk.MaKho = @MaKho AND tk.MaSP = ct.MaSP
            WHERE ct.MaDH = @MaDH AND ISNULL(tk.SoLuongTon, 0) < ct.SoLuong
        )
        BEGIN
            SET @Loi = N'Kho ' + @MaKho + N' không đủ hàng: ';
            SELECT @Loi = @Loi + sp.TenSP + N' cần ' + CAST(ct.SoLuong AS NVARCHAR(10)) + N', kho còn ' + CAST(ISNULL(tk.SoLuongTon, 0) AS NVARCHAR(10)) + N'. '
            FROM ChiTietDonHang ct
            JOIN SanPham sp ON sp.MaSP = ct.MaSP
            LEFT JOIN TonKho tk ON tk.MaKho = @MaKho AND tk.MaSP = ct.MaSP
            WHERE ct.MaDH = @MaDH AND ISNULL(tk.SoLuongTon, 0) < ct.SoLuong;
            SET @Loi = @Loi + N'Hãy chọn kho khác hoặc nhập thêm hàng.';
            THROW 50034, @Loi, 1;
        END

        DECLARE @SoPX INT = (SELECT ISNULL(MAX(TRY_CAST(SUBSTRING(MaPX, 3, 20) AS INT)), 0) + 1
                             FROM PhieuXuat WITH (UPDLOCK, HOLDLOCK) WHERE MaPX LIKE 'PX%');
        SET @MaPX = 'PX' + CASE WHEN @SoPX < 1000 THEN RIGHT('00' + CAST(@SoPX AS VARCHAR(10)), 3) ELSE CAST(@SoPX AS VARCHAR(10)) END;

        VALUES (@MaPX, @MaDH, @MaKho, GETDATE(), @NguoiLap);

        SELECT @MaPX, MaSP, SoLuong FROM ChiTietDonHang WHERE MaDH = @MaDH;

        UPDATE DonHang
        SET TrangThai = CASE WHEN HinhThucNhan = N'Nhận tại cửa hàng' THEN N'Đã giao' ELSE N'Chờ lấy hàng' END,
            NgayXacNhan = GETDATE(),
            NgayGiao = CASE WHEN HinhThucNhan = N'Nhận tại cửa hàng' THEN GETDATE() ELSE NgayGiao END
        WHERE MaDH = @MaDH;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

CREATE OR ALTER PROCEDURE dbo.sp_TaoVanDon
    @MaDH VARCHAR(20),
    @DonViVC NVARCHAR(100),
    @MaTracking VARCHAR(100),
    @MaVanDon VARCHAR(50) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @TT NVARCHAR(50), @Loi NVARCHAR(2048);
        SELECT @TT = TrangThai FROM DonHang WITH (UPDLOCK) WHERE MaDH = @MaDH;

        IF @TT IS NULL
            THROW 50050, N'Không tìm thấy đơn hàng.', 1;
        IF @TT <> N'Chờ lấy hàng'
        BEGIN
            SET @Loi = N'Chỉ giao cho đơn vị vận chuyển khi đơn đã xuất kho ("Chờ lấy hàng"). Đơn này đang: ' + @TT + N'.';
            THROW 50051, @Loi, 1;
        END
        IF LEN(LTRIM(RTRIM(ISNULL(@DonViVC, N'')))) = 0
            THROW 50052, N'Chưa nhập đơn vị vận chuyển.', 1;
        IF LEN(LTRIM(RTRIM(ISNULL(@MaTracking, '')))) = 0
            THROW 50053, N'Chưa nhập mã vận đơn của đơn vị vận chuyển.', 1;

        DECLARE @Moi TABLE (MaVanDon VARCHAR(50));
        OUTPUT inserted.MaVanDon INTO @Moi (MaVanDon)
        VALUES (@MaDH, LTRIM(RTRIM(@DonViVC)), LTRIM(RTRIM(@MaTracking)), N'Đang giao', GETDATE());

        SELECT TOP 1 @MaVanDon = MaVanDon FROM @Moi;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

CREATE OR ALTER PROCEDURE dbo.sp_CapNhatGiaoHang
    @MaDH VARCHAR(20),
    @KetQua NVARCHAR(50),
    @GhiChu NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @TT NVARCHAR(50), @Loi NVARCHAR(2048);
        SELECT @TT = TrangThai FROM DonHang WITH (UPDLOCK) WHERE MaDH = @MaDH;

        IF @TT IS NULL
            THROW 50060, N'Không tìm thấy đơn hàng.', 1;
        IF @TT <> N'Đang giao'
        BEGIN
            SET @Loi = N'Chỉ ghi kết quả giao cho đơn "Đang giao". Đơn này đang: ' + @TT + N'.';
            THROW 50061, @Loi, 1;
        END
        IF @KetQua NOT IN (N'Đã giao', N'Giao không thành công')
            THROW 50062, N'Kết quả giao chỉ được là "Đã giao" hoặc "Giao không thành công".', 1;

        IF @KetQua = N'Đã giao'
        BEGIN
            UPDATE VanDon
            SET TrangThai = N'Đã giao', NgayGiaoXong = GETDATE()
            WHERE MaDH = @MaDH AND TrangThai = N'Đang giao';
        END
        ELSE
        BEGIN
            UPDATE VanDon
            SET TrangThai = N'Giao không thành công'
            WHERE MaDH = @MaDH AND TrangThai = N'Đang giao';

            DECLARE @LyDo NVARCHAR(255) = N'Giao không thành công' + CASE WHEN LEN(LTRIM(RTRIM(ISNULL(@GhiChu, N'')))) > 0
                                                                          THEN N': ' + LTRIM(RTRIM(@GhiChu)) ELSE N'' END;
            EXEC dbo.sp_HuyDon @MaDH = @MaDH, @LyDo = @LyDo, @ChoPhepKhiDangGiao = 1;
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

CREATE OR ALTER PROCEDURE dbo.sp_NhanHangHoanVeKho
    @MaDH VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        UPDATE HangHoanVeKho
        SET TrangThai = N'Đã nhận về kho', NgayNhanVe = GETDATE()
        WHERE MaDH = @MaDH AND TrangThai = N'Đang hoàn về';
        IF @@ROWCOUNT = 0
            THROW 50070, N'Đơn này không có hàng nào đang hoàn về kho.', 1;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

CREATE OR ALTER VIEW dbo.vw_XuatKhoBatThuong
AS
SELECT N'Xuất kho không gắn đơn hàng' AS LoaiBatThuong, px.MaPX, px.NgayXuat, px.MaKho, px.MaDH, cx.MaSP, sp.TenSP,
       cx.SoLuong AS SoLuongDangNgo, cx.SoLuong * ISNULL(sp.GiaVon, 0) AS GiaTriTheoGiaVon, px.NguoiLap,
       N'Phiếu xuất không ghi mã đơn nên không biết hàng đi đâu.' AS GhiChu
FROM PhieuXuat px
JOIN ChiTietPhieuXuat cx ON cx.MaPX = px.MaPX
JOIN SanPham sp ON sp.MaSP = cx.MaSP
WHERE px.MaDH IS NULL
UNION ALL
SELECT N'Xuất nhiều hơn khách đặt', x.MaPX, x.NgayXuat, x.MaKho, x.MaDH, x.MaSP, sp.TenSP,
       x.DaXuat - ISNULL(d.DaDat, 0), (x.DaXuat - ISNULL(d.DaDat, 0)) * ISNULL(sp.GiaVon, 0), x.NguoiLap,
       N'Khách đặt ' + CAST(ISNULL(d.DaDat, 0) AS NVARCHAR(10)) + N' cái, kho xuất ' + CAST(x.DaXuat AS NVARCHAR(10)) + N' cái.'
FROM (
    SELECT px.MaDH, cx.MaSP, MIN(px.MaPX) AS MaPX, MIN(px.NgayXuat) AS NgayXuat, MIN(px.MaKho) AS MaKho,
           MIN(px.NguoiLap) AS NguoiLap, SUM(cx.SoLuong) AS DaXuat
    FROM PhieuXuat px
    JOIN ChiTietPhieuXuat cx ON cx.MaPX = px.MaPX
    WHERE px.MaDH IS NOT NULL
    GROUP BY px.MaDH, cx.MaSP
) x
JOIN SanPham sp ON sp.MaSP = x.MaSP
OUTER APPLY (SELECT SUM(ct.SoLuong) AS DaDat FROM ChiTietDonHang ct WHERE ct.MaDH = x.MaDH AND ct.MaSP = x.MaSP) d
WHERE x.DaXuat > ISNULL(d.DaDat, 0)
UNION ALL
SELECT N'Xuất kho ngoài giờ (22h - 8h)', px.MaPX, px.NgayXuat, px.MaKho, px.MaDH, cx.MaSP, sp.TenSP,
       cx.SoLuong, cx.SoLuong * ISNULL(sp.GiaVon, 0), px.NguoiLap,
       N'Lập lúc ' + CONVERT(NVARCHAR(5), px.NgayXuat, 108) + N', ngoài giờ đóng gói của kho.'
FROM PhieuXuat px
JOIN ChiTietPhieuXuat cx ON cx.MaPX = px.MaPX
JOIN SanPham sp ON sp.MaSP = cx.MaSP
WHERE DATEPART(HOUR, px.NgayXuat) >= 22 OR DATEPART(HOUR, px.NgayXuat) < 8;
GO


CREATE OR ALTER PROCEDURE dbo.sp_LayMaMoi
    @Loai VARCHAR(5),
    @Ma VARCHAR(20) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @So INT;
    IF @Loai = 'PN'
        SELECT @So = ISNULL(MAX(TRY_CAST(SUBSTRING(MaPN, 3, 20) AS INT)), 0) + 1 FROM PhieuNhap WITH (UPDLOCK, HOLDLOCK) WHERE MaPN LIKE 'PN%';
    ELSE IF @Loai = 'TH'
        SELECT @So = ISNULL(MAX(TRY_CAST(SUBSTRING(MaTraHang, 3, 20) AS INT)), 0) + 1 FROM TraHang WITH (UPDLOCK, HOLDLOCK) WHERE MaTraHang LIKE 'TH%';
    ELSE IF @Loai = 'BH'
        SELECT @So = ISNULL(MAX(TRY_CAST(SUBSTRING(MaBaoHanh, 3, 20) AS INT)), 0) + 1 FROM BaoHanh WITH (UPDLOCK, HOLDLOCK) WHERE MaBaoHanh LIKE 'BH%';
    ELSE IF @Loai = 'CB'
        SELECT @So = ISNULL(MAX(TRY_CAST(SUBSTRING(MaCanhBao, 3, 20) AS INT)), 0) + 1 FROM CanhBaoTonHet WITH (UPDLOCK, HOLDLOCK) WHERE MaCanhBao LIKE 'CB%';
    ELSE IF @Loai = 'DG'
        SELECT @So = ISNULL(MAX(TRY_CAST(SUBSTRING(MaDanhGia, 3, 20) AS INT)), 0) + 1 FROM DanhGiaSanPham WITH (UPDLOCK, HOLDLOCK) WHERE MaDanhGia LIKE 'DG%';
    ELSE IF @Loai = 'TT'
        SELECT @So = ISNULL(MAX(TRY_CAST(SUBSTRING(MaTT, 3, 20) AS INT)), 0) + 1 FROM ThanhToanNCC WITH (UPDLOCK, HOLDLOCK) WHERE MaTT LIKE 'TT%';
    ELSE IF @Loai = 'KK'
        SELECT @So = ISNULL(MAX(TRY_CAST(SUBSTRING(MaKK, 3, 20) AS INT)), 0) + 1 FROM PhieuKiemKe WITH (UPDLOCK, HOLDLOCK) WHERE MaKK LIKE 'KK%';
    ELSE IF @Loai = 'CK'
        SELECT @So = ISNULL(MAX(TRY_CAST(SUBSTRING(MaCK, 3, 20) AS INT)), 0) + 1 FROM PhieuChuyenKho WITH (UPDLOCK, HOLDLOCK) WHERE MaCK LIKE 'CK%';
    ELSE
        THROW 50090, N'Loại chứng từ này chưa có cách đánh mã.', 1;

    SET @Ma = @Loai + CASE WHEN @So < 1000 THEN RIGHT('00' + CAST(@So AS VARCHAR(10)), 3) ELSE CAST(@So AS VARCHAR(10)) END;
END;
GO

CREATE OR ALTER TRIGGER trg_LichSuGiaBan
ON SanPham
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    SELECT i.MaSP, d.GiaBan, i.GiaBan, i.GiaVon, GETDATE(), dbo.fn_LayNguoiDungHienTai()
    FROM inserted i
    LEFT JOIN deleted d ON d.MaSP = i.MaSP
    WHERE (d.MaSP IS NULL AND i.GiaBan IS NOT NULL)
       OR (d.MaSP IS NOT NULL AND ISNULL(d.GiaBan, -1) <> ISNULL(i.GiaBan, -1));
END;
GO

CREATE OR ALTER PROCEDURE dbo.sp_NhanBaoHanh
    @MaDH VARCHAR(20),
    @MaSP VARCHAR(50),
    @LyDoHong NVARCHAR(255),
    @SoNgayHen INT = 14,
    @MaBH VARCHAR(20) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @NgayGiao DATETIME, @TrangThai NVARCHAR(50), @SoThang INT, @TenSP NVARCHAR(255);
    SELECT @NgayGiao = NgayGiao, @TrangThai = TrangThai FROM DonHang WHERE MaDH = @MaDH;
    IF @TrangThai IS NULL
        THROW 50100, N'Không tìm thấy mã đơn này.', 1;
    IF @TrangThai NOT IN (N'Đã giao', N'Trả hàng/Hoàn tiền') OR @NgayGiao IS NULL
        THROW 50101, N'Đơn này chưa giao tới khách nên chưa nhận bảo hành.', 1;
    IF NOT EXISTS (SELECT 1 FROM ChiTietDonHang WHERE MaDH = @MaDH AND MaSP = @MaSP)
        THROW 50102, N'Sản phẩm này không có trong đơn.', 1;
    IF LEN(LTRIM(RTRIM(ISNULL(@LyDoHong, N'')))) = 0
        THROW 50103, N'Hãy ghi lỗi khách báo (ví dụ: không lên nguồn, mất kết nối bluetooth).', 1;

    SELECT @SoThang = SoThangBaoHanh, @TenSP = TenSP FROM SanPham WHERE MaSP = @MaSP;
    IF DATEADD(MONTH, @SoThang, @NgayGiao) < GETDATE()
    BEGIN
        DECLARE @HetHan NVARCHAR(400) = @TenSP + N' bảo hành ' + CAST(@SoThang AS NVARCHAR(5)) + N' tháng, giao ngày '
            + CONVERT(NVARCHAR(10), @NgayGiao, 103) + N' nên đã hết hạn từ ngày '
            + CONVERT(NVARCHAR(10), DATEADD(MONTH, @SoThang, @NgayGiao), 103) + N'.';
        THROW 50104, @HetHan, 1;
    END
    IF (SELECT SUM(SoLuong) FROM ChiTietDonHang WHERE MaDH = @MaDH AND MaSP = @MaSP)
       <= ISNULL((SELECT SUM(SoLuong) FROM TraHang WHERE MaDH = @MaDH AND MaSP = @MaSP), 0)
        THROW 50105, N'Khách đã trả lại hết món này nên không còn món nào để bảo hành.', 1;
    IF EXISTS (SELECT 1 FROM BaoHanh WHERE MaDH = @MaDH AND MaSP = @MaSP AND TrangThai = N'Đang xử lý')
        THROW 50106, N'Món này đang có phiếu bảo hành chưa xong. Hãy cập nhật kết quả phiếu đó.', 1;
    IF @SoNgayHen IS NULL OR @SoNgayHen < 1 SET @SoNgayHen = 14;

    BEGIN TRY
        BEGIN TRANSACTION;
        EXEC dbo.sp_LayMaMoi @Loai = 'BH', @Ma = @MaBH OUTPUT;
        VALUES (@MaBH, @MaSP, @MaDH, LTRIM(RTRIM(@LyDoHong)), GETDATE(), DATEADD(DAY, @SoNgayHen, GETDATE()), N'Đang xử lý');
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

CREATE OR ALTER PROCEDURE dbo.sp_TraKetQuaBaoHanh
    @MaBH VARCHAR(20),
    @KetQua NVARCHAR(40),
    @CachXuLy NVARCHAR(255),
    @ChiPhiShopChiu DECIMAL(18,2) = 0
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM BaoHanh WHERE MaBaoHanh = @MaBH)
        THROW 50107, N'Không tìm thấy phiếu bảo hành.', 1;
    IF ISNULL(@KetQua, N'') NOT IN (N'Đã sửa xong, trả khách', N'Hãng đổi máy mới, trả khách', N'Từ chối bảo hành', N'Chuyển sang trả hàng')
        THROW 50108, N'Hãy chọn kết quả bảo hành.', 1;
    IF LEN(LTRIM(RTRIM(ISNULL(@CachXuLy, N'')))) = 0
        THROW 50109, N'Hãy ghi đã xử lý thế nào (ví dụ: hãng thay pin, hoặc lý do từ chối).', 1;
    IF ISNULL(@ChiPhiShopChiu, 0) < 0
        THROW 50110, N'Chi phí shop chịu không được là số âm.', 1;

    UPDATE BaoHanh
    SET TrangThai = @KetQua, CachXuLy = LTRIM(RTRIM(@CachXuLy)), ChiPhiShopChiu = ISNULL(@ChiPhiShopChiu, 0), NgayTraKhach = GETDATE()
    WHERE MaBaoHanh = @MaBH AND TrangThai = N'Đang xử lý';
    IF @@ROWCOUNT = 0
        THROW 50111, N'Phiếu này đã có kết quả rồi.', 1;

    SELECT N'Bảo hành', MaBaoHanh, MaSP, ChiPhiShopChiu, dbo.fn_LayNguoiDungHienTai(),
           N'Trả kết quả bảo hành: ' + TrangThai + N' - ' + CachXuLy, NgayTraKhach
    FROM BaoHanh WHERE MaBaoHanh = @MaBH;
END;
GO

CREATE OR ALTER PROCEDURE dbo.sp_LapPhieuKiemKe
    @MaKho VARCHAR(20),
    @NguoiKiem NVARCHAR(100),
    @MaKK VARCHAR(20) OUTPUT,
    @NgayKiemKe DATETIME = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF NOT EXISTS (SELECT 1 FROM Kho WHERE MaKho = @MaKho)
        THROW 50120, N'Không tìm thấy kho.', 1;
    IF EXISTS (SELECT 1 FROM PhieuKiemKe WHERE MaKho = @MaKho AND TrangThai = N'Đang kiểm')
        THROW 50121, N'Kho này đang có phiếu kiểm kê chưa chốt. Hãy chốt phiếu đó trước.', 1;
    BEGIN TRY
        BEGIN TRANSACTION;
        EXEC dbo.sp_LayMaMoi @Loai = 'KK', @Ma = @MaKK OUTPUT;
        VALUES (@MaKK, @MaKho, ISNULL(@NgayKiemKe, GETDATE()), @NguoiKiem, N'Đang kiểm');
        SELECT @MaKK, MaSP, SoLuongTon FROM TonKho WHERE MaKho = @MaKho;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

CREATE OR ALTER PROCEDURE dbo.sp_ChotKiemKe
    @MaKK VARCHAR(20),
    @NgayChot DATETIME = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @MaKho VARCHAR(20), @TrangThai NVARCHAR(20);
    SELECT @MaKho = MaKho, @TrangThai = TrangThai FROM PhieuKiemKe WHERE MaKK = @MaKK;
    IF @MaKho IS NULL
        THROW 50122, N'Không tìm thấy phiếu kiểm kê.', 1;
    IF @TrangThai <> N'Đang kiểm'
        THROW 50123, N'Phiếu này đã chốt rồi.', 1;
    IF EXISTS (SELECT 1 FROM ChiTietKiemKe WHERE MaKK = @MaKK AND ThucTe IS NULL)
        THROW 50124, N'Còn món chưa nhập số đếm thực tế.', 1;
    IF EXISTS (SELECT 1 FROM ChiTietKiemKe WHERE MaKK = @MaKK AND ChenhLech <> 0 AND LEN(LTRIM(RTRIM(ISNULL(LyDoLech, N'')))) = 0)
        THROW 50125, N'Món nào đếm ra khác sổ thì phải ghi lý do lệch (thất lạc, hỏng, đếm sai lúc xuất...).', 1;
    SET @NgayChot = ISNULL(@NgayChot, GETDATE());

    BEGIN TRY
        BEGIN TRANSACTION;
        IF EXISTS (SELECT 1 FROM ChiTietKiemKe ct
                   JOIN TonKho tk WITH (UPDLOCK) ON tk.MaKho = @MaKho AND tk.MaSP = ct.MaSP
                   WHERE ct.MaKK = @MaKK AND tk.SoLuongTon + ct.ChenhLech < 0)
            THROW 50126, N'Trừ phần thiếu thì tồn kho bị âm (có thể hàng đã xuất trong lúc đếm). Hãy đếm lại món đó.', 1;

        UPDATE tk
        SET tk.SoLuongTon = tk.SoLuongTon + ct.ChenhLech
        FROM TonKho tk
        JOIN ChiTietKiemKe ct ON ct.MaSP = tk.MaSP
        WHERE ct.MaKK = @MaKK AND tk.MaKho = @MaKho AND ct.ChenhLech <> 0;

        SELECT N'Kiểm kê', @MaKK, ct.MaSP, @MaKho, ct.ChenhLech, ct.ChenhLech * ISNULL(sp.GiaVon, 0), dbo.fn_LayNguoiDungHienTai(),
               N'Đếm thực tế ' + CAST(ct.ThucTe AS NVARCHAR(10)) + N', sổ ghi ' + CAST(ct.SoSach AS NVARCHAR(10)) + N'. ' + ct.LyDoLech, @NgayChot
        FROM ChiTietKiemKe ct
        JOIN SanPham sp ON sp.MaSP = ct.MaSP
        WHERE ct.MaKK = @MaKK AND ct.ChenhLech <> 0;

        UPDATE PhieuKiemKe SET TrangThai = N'Đã chốt', NgayChot = @NgayChot WHERE MaKK = @MaKK;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

CREATE OR ALTER PROCEDURE dbo.sp_ChuyenKho
    @TuKho VARCHAR(20),
    @DenKho VARCHAR(20),
    @MaSP VARCHAR(50),
    @SoLuong INT,
    @NguoiLap NVARCHAR(100),
    @MaCK VARCHAR(20) OUTPUT,
    @NgayChuyen DATETIME = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF @TuKho = @DenKho
        THROW 50130, N'Kho đi và kho đến phải khác nhau.', 1;
    IF NOT EXISTS (SELECT 1 FROM Kho WHERE MaKho = @TuKho) OR NOT EXISTS (SELECT 1 FROM Kho WHERE MaKho = @DenKho)
        THROW 50131, N'Không tìm thấy kho.', 1;
    IF ISNULL(@SoLuong, 0) <= 0
        THROW 50132, N'Số lượng chuyển phải lớn hơn 0.', 1;
    IF EXISTS (SELECT 1 FROM PhieuKiemKe WHERE MaKho IN (@TuKho, @DenKho) AND TrangThai = N'Đang kiểm')
        THROW 50133, N'Một trong hai kho đang kiểm kê. Chốt kiểm kê xong rồi mới chuyển hàng.', 1;
    SET @NgayChuyen = ISNULL(@NgayChuyen, GETDATE());

    BEGIN TRY
        BEGIN TRANSACTION;
        DECLARE @Ton INT = (SELECT SoLuongTon FROM TonKho WITH (UPDLOCK) WHERE MaKho = @TuKho AND MaSP = @MaSP);
        IF ISNULL(@Ton, 0) < @SoLuong
        BEGIN
            DECLARE @ThieuHang NVARCHAR(300) = N'Kho đi chỉ còn ' + CAST(ISNULL(@Ton, 0) AS NVARCHAR(10)) + N', không đủ để chuyển '
                                                + CAST(@SoLuong AS NVARCHAR(10)) + N'.';
            THROW 50134, @ThieuHang, 1;
        END

        UPDATE TonKho SET SoLuongTon = SoLuongTon - @SoLuong WHERE MaKho = @TuKho AND MaSP = @MaSP;
        MERGE TonKho AS dich
        USING (SELECT @DenKho AS MaKho, @MaSP AS MaSP) AS nguon
        ON dich.MaKho = nguon.MaKho AND dich.MaSP = nguon.MaSP
        WHEN MATCHED THEN UPDATE SET dich.SoLuongTon = dich.SoLuongTon + @SoLuong
        WHEN NOT MATCHED THEN INSERT (MaKho, MaSP, SoLuongTon) VALUES (@DenKho, @MaSP, @SoLuong);

        EXEC dbo.sp_LayMaMoi @Loai = 'CK', @Ma = @MaCK OUTPUT;
        VALUES (@MaCK, @TuKho, @DenKho, @MaSP, @SoLuong, @NgayChuyen, @NguoiLap);

        VALUES (N'Chuyển kho', @MaCK, @MaSP, @TuKho, -@SoLuong, dbo.fn_LayNguoiDungHienTai(), N'Chuyển sang ' + @DenKho, @NgayChuyen),
               (N'Chuyển kho', @MaCK, @MaSP, @DenKho, @SoLuong, dbo.fn_LayNguoiDungHienTai(), N'Nhận từ ' + @TuKho, @NgayChuyen);
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

CREATE OR ALTER TRIGGER trg_ThanhToanNCC_KhongVuot
ON ThanhToanNCC
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (
        SELECT 1
        FROM PhieuNhap pn
        JOIN (SELECT DISTINCT MaPN FROM inserted) i ON i.MaPN = pn.MaPN
        WHERE (SELECT SUM(t.SoTien) FROM ThanhToanNCC t WHERE t.MaPN = pn.MaPN) > pn.TongTien
    )
    BEGIN
        RAISERROR(N'Tổng tiền đã trả cho phiếu nhập lớn hơn tiền của phiếu nhập.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END
END;
GO

CREATE OR ALTER PROCEDURE dbo.sp_TraTienNhaCungCap
    @MaPN VARCHAR(20),
    @SoTien DECIMAL(18,2),
    @HinhThuc NVARCHAR(50),
    @NguoiLap NVARCHAR(100),
    @MaTT VARCHAR(20) OUTPUT,
    @NgayTra DATETIME = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF NOT EXISTS (SELECT 1 FROM PhieuNhap WHERE MaPN = @MaPN)
        THROW 50140, N'Không tìm thấy phiếu nhập.', 1;
    IF ISNULL(@SoTien, 0) <= 0
        THROW 50141, N'Số tiền trả phải lớn hơn 0.', 1;
    IF ISNULL(@HinhThuc, N'') NOT IN (N'Tiền mặt', N'Chuyển khoản ngân hàng')
        THROW 50142, N'Hãy chọn trả bằng tiền mặt hay chuyển khoản.', 1;
    BEGIN TRY
        BEGIN TRANSACTION;
        DECLARE @ConNo DECIMAL(18,2) = (SELECT pn.TongTien - ISNULL((SELECT SUM(t.SoTien) FROM ThanhToanNCC t WITH (UPDLOCK, HOLDLOCK) WHERE t.MaPN = pn.MaPN), 0)
                                        FROM PhieuNhap pn WHERE pn.MaPN = @MaPN);
        IF @SoTien > @ConNo
        BEGIN
            DECLARE @ThongBao NVARCHAR(300) = N'Phiếu này chỉ còn nợ ' + FORMAT(@ConNo, 'N0', 'vi-VN') + N' đ, không trả nhiều hơn được.';
            THROW 50143, @ThongBao, 1;
        END
        EXEC dbo.sp_LayMaMoi @Loai = 'TT', @Ma = @MaTT OUTPUT;
        VALUES (@MaTT, @MaPN, ISNULL(@NgayTra, GETDATE()), @SoTien, @HinhThuc, @NguoiLap);
        VALUES (N'Trả tiền nhà cung cấp', @MaTT, @SoTien, dbo.fn_LayNguoiDungHienTai(), N'Trả cho phiếu nhập ' + @MaPN, ISNULL(@NgayTra, GETDATE()));
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

CREATE OR ALTER VIEW dbo.vw_CongNoNhaCungCap
AS
SELECT pn.MaPN, pn.NgayNhap, pn.MaNCC, ncc.TenNCC, pn.MaKho, pn.TongTien,
       ISNULL(tt.DaTra, 0) AS DaTra,
       pn.TongTien - ISNULL(tt.DaTra, 0) AS ConNo,
       ncc.SoNgayCongNo,
       DATEADD(DAY, ncc.SoNgayCongNo, CAST(pn.NgayNhap AS DATE)) AS HanTra,
       tt.LanTraCuoi,
       CASE WHEN pn.TongTien - ISNULL(tt.DaTra, 0) <= 0 THEN N'Đã trả đủ'
            WHEN DATEADD(DAY, ncc.SoNgayCongNo, CAST(pn.NgayNhap AS DATE)) < dbo.fn_NgayDuLieuMoiNhat() THEN N'Quá hạn'
            ELSE N'Chưa tới hạn' END AS TinhTrang
FROM PhieuNhap pn
JOIN NhaCungCap ncc ON ncc.MaNCC = pn.MaNCC
OUTER APPLY (SELECT SUM(t.SoTien) AS DaTra, MAX(t.NgayTra) AS LanTraCuoi FROM ThanhToanNCC t WHERE t.MaPN = pn.MaPN) tt;
GO

CREATE OR ALTER PROCEDURE dbo.sp_GhiTienSanChuyenVe
    @MaDH VARCHAR(20),
    @MaDot VARCHAR(30),
    @NgayChuyen DATETIME,
    @SoTienSanTra DECIMAL(18,2),
    @GhiChu NVARCHAR(255) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM DonHang dh JOIN DoiTac dt ON dt.MaDoiTac = dh.MaDoiTac
                   WHERE dh.MaDH = @MaDH AND dt.LoaiKenh = N'Sàn thương mại điện tử')
        THROW 50150, N'Mã đơn này không phải đơn bán trên sàn.', 1;
    IF NOT EXISTS (SELECT 1 FROM DonHang WHERE MaDH = @MaDH AND TrangThai IN (N'Đã giao', N'Trả hàng/Hoàn tiền'))
        THROW 50151, N'Đơn này chưa giao xong nên sàn chưa chuyển tiền.', 1;
    IF LEN(LTRIM(RTRIM(ISNULL(@MaDot, '')))) = 0
        THROW 50152, N'Hãy ghi mã đợt chuyển tiền (lấy trong báo cáo thu nhập của sàn).', 1;

    MERGE TienSanChuyenVe AS dich
    USING (SELECT @MaDH AS MaDH) AS nguon ON dich.MaDH = nguon.MaDH
    WHEN MATCHED THEN UPDATE SET MaDot = @MaDot, NgayChuyen = @NgayChuyen, SoTienSanTra = @SoTienSanTra, GhiChu = @GhiChu
    WHEN NOT MATCHED THEN INSERT (MaDH, MaDot, NgayChuyen, SoTienSanTra, GhiChu) VALUES (@MaDH, @MaDot, @NgayChuyen, @SoTienSanTra, @GhiChu);
END;
GO

CREATE OR ALTER VIEW dbo.vw_DoiSoatTienSan
AS
SELECT t.MaDH, t.MaDoiTac, t.KenhBan, dh.NgayGiao, tr.NgayTraCuoi,
       t.TienShopNhan AS ShopTinhDuocNhan,
       c.SoTienSanTra, c.NgayChuyen, c.MaDot,
       CASE WHEN c.MaDH IS NULL THEN NULL ELSE c.SoTienSanTra - t.TienShopNhan END AS ChenhLech,
       CASE WHEN c.MaDH IS NULL AND DATEDIFF(DAY, COALESCE(tr.NgayTraCuoi, dh.NgayGiao), dbo.fn_NgayDuLieuMoiNhat()) > 14
                THEN N'Quá 14 ngày sàn chưa chuyển tiền'
            WHEN c.MaDH IS NULL THEN N'Sàn chưa chuyển (chưa tới hạn)'
            WHEN c.SoTienSanTra = t.TienShopNhan THEN N'Khớp'
            WHEN c.SoTienSanTra < t.TienShopNhan THEN N'Sàn trả thiếu'
            ELSE N'Sàn trả dư' END AS TinhTrang,
       c.GhiChu
FROM dbo.vw_TienDonHang t
JOIN DonHang dh ON dh.MaDH = t.MaDH
JOIN DoiTac dt ON dt.MaDoiTac = t.MaDoiTac AND dt.LoaiKenh = N'Sàn thương mại điện tử'
OUTER APPLY (SELECT MAX(th.NgayTra) AS NgayTraCuoi FROM TraHang th WHERE th.MaDH = t.MaDH) tr
LEFT JOIN TienSanChuyenVe c ON c.MaDH = t.MaDH
WHERE t.DaGiao = 1;
GO

CREATE OR ALTER VIEW dbo.vw_LaiRongTheoThang
AS
WITH Don AS (
    SELECT DATEFROMPARTS(YEAR(NgayDat), MONTH(NgayDat), 1) AS Thang,
           SUM(TienHang) AS TienHang, SUM(GiamGiaCuaShop) AS GiamGiaCuaShop, SUM(PhiSan) AS PhiSan,
           SUM(TienHoanKhach) AS TienHoanKhach, SUM(TienShopNhan) AS TienShopNhan,
           SUM(GiaVonHangBan) AS GiaVonHangBan, SUM(LaiGop) AS LaiGop
    FROM dbo.vw_TienDonHang
    WHERE DaHuy = 0
    GROUP BY DATEFROMPARTS(YEAR(NgayDat), MONTH(NgayDat), 1)
), ChiPhi AS (
    SELECT Thang, SUM(SoTien) AS ChiPhiVanHanh FROM ChiPhiVanHanh GROUP BY Thang
), MatHang AS (
    SELECT DATEFROMPARTS(YEAR(NgayXuat), MONTH(NgayXuat), 1) AS Thang, SUM(GiaTriTheoGiaVon) AS Tien
    FROM dbo.vw_XuatKhoBatThuong
    WHERE LoaiBatThuong IN (N'Xuất kho không gắn đơn hàng', N'Xuất nhiều hơn khách đặt')
    GROUP BY DATEFROMPARTS(YEAR(NgayXuat), MONTH(NgayXuat), 1)
    UNION ALL
    SELECT DATEFROMPARTS(YEAR(p.NgayChot), MONTH(p.NgayChot), 1), SUM(-ct.ChenhLech * ISNULL(sp.GiaVon, 0))
    FROM ChiTietKiemKe ct
    JOIN PhieuKiemKe p ON p.MaKK = ct.MaKK
    JOIN SanPham sp ON sp.MaSP = ct.MaSP
    WHERE p.TrangThai = N'Đã chốt' AND ct.ChenhLech <> 0
    GROUP BY DATEFROMPARTS(YEAR(p.NgayChot), MONTH(p.NgayChot), 1)
), MatHangThang AS (
    SELECT Thang, SUM(Tien) AS HangMatHong FROM MatHang GROUP BY Thang
), BaoHanhThang AS (
    SELECT DATEFROMPARTS(YEAR(NgayTraKhach), MONTH(NgayTraKhach), 1) AS Thang, SUM(ChiPhiShopChiu) AS ChiPhiBaoHanh
    FROM BaoHanh
    WHERE NgayTraKhach IS NOT NULL
    GROUP BY DATEFROMPARTS(YEAR(NgayTraKhach), MONTH(NgayTraKhach), 1)
), CacThang AS (
    SELECT Thang FROM Don UNION SELECT Thang FROM ChiPhi UNION SELECT Thang FROM MatHangThang UNION SELECT Thang FROM BaoHanhThang
)
SELECT ct.Thang,
       ISNULL(d.TienHang, 0) AS TienHang,
       ISNULL(d.GiamGiaCuaShop, 0) AS GiamGiaCuaShop,
       ISNULL(d.PhiSan, 0) AS PhiSan,
       ISNULL(d.TienHoanKhach, 0) AS TienHoanKhach,
       ISNULL(d.TienShopNhan, 0) AS TienShopNhan,
       ISNULL(d.GiaVonHangBan, 0) AS GiaVonHangBan,
       ISNULL(d.LaiGop, 0) AS LaiGop,
       ISNULL(c.ChiPhiVanHanh, 0) AS ChiPhiVanHanh,
       ISNULL(m.HangMatHong, 0) AS HangMatHong,
       ISNULL(b.ChiPhiBaoHanh, 0) AS ChiPhiBaoHanh,
       ISNULL(d.LaiGop, 0) - ISNULL(c.ChiPhiVanHanh, 0) - ISNULL(m.HangMatHong, 0) - ISNULL(b.ChiPhiBaoHanh, 0) AS LaiRong
FROM CacThang ct
LEFT JOIN Don d ON d.Thang = ct.Thang
LEFT JOIN ChiPhi c ON c.Thang = ct.Thang
LEFT JOIN MatHangThang m ON m.Thang = ct.Thang
LEFT JOIN BaoHanhThang b ON b.Thang = ct.Thang;
GO

