INSERT INTO CachBan_TheoLyDoMua (NhomLyDo, KieuLyDo, CachBanHop) VALUES
    (N'Hên / tâm linh', N'Cảm xúc', N'Bán theo dịp: ngày vía, đầu năm, khai trương. Gói quà đỏ, lời chúc may mắn, giao đúng ngày đẹp.'),
    (N'Thói quen', N'Cảm xúc', N'Giữ mọi thứ quen thuộc: giá ổn định, giao đúng hẹn, nhắn nhắc khi gần hết hàng. Đừng đổi đóng gói lung tung.'),
    (N'Sợ bỏ lỡ', N'Cảm xúc', N'Cho khách thấy người khác đang mua: "đã bán 1.000+", "còn 5 cái", đánh giá có ảnh, đếm ngược giờ sale.'),
    (N'Đẳng cấp / thể diện', N'Cảm xúc', N'Bán hình ảnh sang: hộp đẹp, hàng chính hãng, bảo hành dài. Không giảm giá sâu vì làm mất cảm giác sang.'),
    (N'Hâm mộ thương hiệu', N'Cảm xúc', N'Nói nhiều về hãng: hàng chính hãng, mẫu mới nhất, câu chuyện của hãng. Có hàng mới thì báo nhóm này đầu tiên.'),
    (N'Hưng phấn khuyến mãi', N'Cảm xúc', N'Dồn ưu đãi vào ngày sale, ghi rõ giá gốc - giá giảm. Lưu ý nhóm này dễ đổi ý nên ghi rõ mô tả, ảnh thật.'),
    (N'Nhu cầu thực dụng', N'Cần dùng thật', N'Ghi rõ thông số, so sánh, hướng dẫn dùng. Nhóm này cần lý do rõ ràng, trả lời câu hỏi nhanh là chốt.'),
    (N'Khác / không rõ', N'Không rõ', N'Câu trả lời không khớp từ nào trong từ điển. Đọc thử vài câu rồi thêm từ khóa vào từ điển lý do mua.');
